local config = {
  ui_story_5075_50750100_1_dialog_content = "（經歷了蜃風號上的驚險航程，我們終於跨越大海，踏上了龍洲的土地。）",
  ui_story_5075_50750100_2_dialog_content = "（月白與仲胥兩人必須在港口押送一批商會貨物，行程稍晚兩天。）",
  ui_story_5075_50750100_3_dialog_content = "（儘管林家商會盛情相邀同行……）",
  ui_story_5075_50750100_4_dialog_content = "（我還需履行艾斯特拉大陸使節的職責，先一步隨丹棠與玖前往濟國都城。）",
  ui_story_5075_50750100_5_dialog_content = "龍娘娘，拜拜倷。",
  ui_story_5075_50750100_6_dialog_content = "覅下雨，明朝替倷供豆干——",
  ui_story_5075_50750100_7_dialog_content = "<color=#e8d9bb>嘩啦。</color>",
  ui_story_5075_50750100_8_dialog_content = "嗚哇！",
  ui_story_5075_50750100_9_dialog_content = "PlayerName公子，小心！",
  ui_story_5075_50750100_10_dialog_content = "我知道你對濟國的景色甚感好奇，但這河上小舟不比蜃風號。",
  ui_story_5075_50750100_11_dialog_content = "若是看得太出神，一不小心就要掉進水裡了。",
  ui_story_5075_50750100_12_dialog_content = "我好不容易才從艾斯特拉大陸請來你這位珍貴的使節……",
  ui_story_5075_50750100_13_dialog_content = "跨越茫茫大海，在暗鬼與海盜的襲擊下都安然無恙。",
  ui_story_5075_50750100_14_dialog_content = "若是在距王宮僅一步之遙時落水出事，可真是我的罪過了。",
  ui_story_5075_50750100_15_dialog_content = "啊哈哈……抱歉，讓妳擔心了。",
  ui_story_5075_50750100_16_dialog_content = "我剛才光顧著聽船伕唱歌，都忘了自己在船上。",
  ui_story_5075_50750100_17_dialog_content = "從港口一路走來，總能聽到這樣的歌。",
  ui_story_5075_50750100_18_dialog_content = "歌詞好像是當地的語言？調子好輕快。他們唱的是什麼？",
  ui_story_5075_50750100_19_dialog_content = "那是「棹歌」。",
  ui_story_5075_50750100_20_dialog_content = "濟國多湖河，百姓伴水而生，船伕、漁民自然也多。",
  ui_story_5075_50750100_21_dialog_content = "久而久之，便有了這些行船時所唱的調子。",
  ui_story_5075_50750100_22_dialog_content = "唱山色青，水明靜。也唱柳垂絲，花滿樹。",
  ui_story_5075_50750100_23_dialog_content = "還有就是你剛剛聽到的，向神靈祈求庇佑的歌。",
  ui_story_5075_50750100_24_dialog_content = "「龍女娘娘，請保佑天氣晴朗，行船順利。」",
  ui_story_5075_50750100_25_dialog_content = "「等我安全到家，就獻上美味的豆腐干給您。」",
  ui_story_5075_50750100_26_dialog_content = "——大概是這個意思。",
  ui_story_5075_50750100_27_dialog_content = "喔，龍女啊！",
  ui_story_5075_50750100_28_dialog_content = "之前在雙榭城，妳教薇絲跳的那支舞就叫<color=#FFB400>《龍女鎮海》</color>。",
  ui_story_5075_50750100_29_dialog_content = "記得妳說過，龍女是龍洲沿海百姓都很信仰的神靈，對不對？",
  ui_story_5075_50750100_30_dialog_content = "……神明也喜歡吃豆腐干嗎？",
  ui_story_5075_50750100_31_dialog_content = "呵呵，不是的。這首歌的結尾句其實沒有標準的歌詞。",
  ui_story_5075_50750100_32_dialog_content = "龍女並不要求供品，所以人們會將想獻給她的東西加進唱詞中，聊表心意。",
  ui_story_5075_50750100_33_dialog_content = "剛剛那位船伕唱「豆干」，可能只是因為他家剛好做了豆干呢。",
  ui_story_5075_50750100_34_dialog_content = "這樣都可以嗎？真是率性的神明啊。",
  ui_story_5075_50750100_35_dialog_content = "我還以為在雙榭城就已經算見識過龍洲文化了……",
  ui_story_5075_50750100_36_dialog_content = "等身臨其境，才發現每走一步都能見到從未聽過的新奇事物。",
  ui_story_5075_50750100_37_dialog_content = "真希望能讓薇絲和卡蓮她們也看看啊。",
  ui_story_5075_50750100_38_dialog_content = "說不定很快就可以了。",
  ui_story_5075_50750100_39_dialog_content = "對喔，我們此行的目的就是加強兩塊大陸之間的交流。",
  ui_story_5075_50750100_40_dialog_content = "要是一切順利，艾斯特拉的朋友們也能多來龍洲逛逛了！",
  ui_story_5075_50750100_41_dialog_content = "還有雙方應對暗鬼的方略與技術。",
  ui_story_5075_50750100_42_dialog_content = "若能互助合作，也能讓兩邊的百姓更快過上安寧的日子。",
  ui_story_5075_50750100_43_dialog_content = "想要實現這種願景，就需仰賴您這位使節大人發揮了～",
  ui_story_5075_50750100_44_dialog_content = "<color=#e8d9bb>咚。</color>",
  ui_story_5075_50750100_45_dialog_content = "殿下，PlayerName閣下，船已靠岸，前面就是目的地了。",
  ui_story_5075_50750100_46_dialog_content = "我們得在這裡登岸入城。",
  ui_story_5075_50750100_47_dialog_content = "PlayerName公子，請先稍慢一步。",
  ui_story_5075_50750100_48_dialog_content = "<color=#e8d9bb>丹棠率先下船，站在岸上，含笑抬手，輕施一禮。</color>",
  ui_story_5075_50750100_49_dialog_content = "我乃灼華郡主，亦是受濟王親遣，出使艾斯特拉大陸的使臣。",
  ui_story_5075_50750100_50_dialog_content = "貴使願接受我的邀請，不遠萬里前來龍洲。",
  ui_story_5075_50750100_51_dialog_content = "請容我再度表達尊敬與謝意。",
  ui_story_5075_50750100_52_dialog_content = "歡迎來到<color=#FFB400>濟國的都城</color>",
  ui_story_5075_50750100_53_dialog_content = "——<color=#FFB400>皓津</color>。",
  ui_story_5075_50750100_54_dialog_content = "嗯，這番好意，我收下了！",
  ui_story_5075_50750100_55_dialog_content = "接下來，就換我履行艾斯特拉使節之職了。",
  ui_story_5075_50750100_56_dialog_content = "殿下，前方有宮廷內侍來接待，我們得回宮覆命濟王了。",
  ui_story_5075_50750100_57_dialog_content = "那PlayerName公子……",
  ui_story_5075_50750100_58_dialog_content = "見過郡主殿下，使者大人。",
  ui_story_5075_50750100_59_dialog_content = "在下禮賓館主事，特來迎接使者大人。",
  ui_story_5075_50750100_60_dialog_content = "使者大人之後在濟的日常行動與護衛，都將由禮賓館負責。",
  ui_story_5075_50750100_61_dialog_content = "看來我們要暫時分開了。",
  ui_story_5075_50750100_62_dialog_content = "過兩天等正事做完，月白她們也回來了，我們再聚一聚，帶你好好逛逛皓津。",
  ui_story_5075_50750100_63_dialog_content = "馬上就到春朔節了，這是龍洲最重要的節日。",
  ui_story_5075_50750100_64_dialog_content = "屆時街上燈舞龍游，遍地華彩，還有販賣各種點心小吃的廟會……",
  ui_story_5075_50750100_65_dialog_content = "一定會讓公子印象深刻。",
  ui_story_5075_50750100_66_dialog_content = "好，我會好好期待！",
  ui_story_5075_50750100_67_dialog_content = "（但我們誰也沒想到，明明是如此簡單的計畫，卻生出那麼多波折……）",
  ui_story_5075_50750100_68_dialog_content = "<color=#e8d9bb>禮賓館</color>",
  ui_story_5075_50750100_69_dialog_content = "使者大人，請用茶。",
  ui_story_5075_50750100_70_dialog_content = "用剛從山上運來的泉水所烹的紫筍茶，最清冽甘甜不過了。",
  ui_story_5075_50750100_71_dialog_content = "很好喝！謝謝。",
  ui_story_5075_50750100_72_dialog_content = "婢不知使者大人的口味，便將各色點心都略做了些。",
  ui_story_5075_50750100_73_dialog_content = "金乳酥、七疊糕、玉露團……若您還有什麼想吃的，儘管吩咐。",
  ui_story_5075_50750100_74_dialog_content = "這，這還只是「略做了些」嗎？！",
  ui_story_5075_50750100_75_dialog_content = "使者大人，婢來服侍您更衣沐浴。",
  ui_story_5075_50750100_76_dialog_content = "不不不！不用麻煩了，這個我自己來就可以！",
  ui_story_5075_50750100_77_dialog_content = "你、你們這招待也太熱情了……",
  ui_story_5075_50750100_78_dialog_content = "弄得我好緊張，生怕做錯什麼事影響艾斯特拉的形象，哈哈。",
  ui_story_5075_50750100_79_dialog_content = "不過，明天就該進宮談正事了吧，我也不會在這裡待太久。",
  ui_story_5075_50750100_80_dialog_content = "<color=#e8d9bb>第二天</color>",
  ui_story_5075_50750100_81_dialog_content = "有動靜！來喊我進宮的人到了？",
  ui_story_5075_50750100_82_dialog_content = "使者大人，大王聽聞您不遠萬里從海外來使，心甚悅。",
  ui_story_5075_50750100_83_dialog_content = "特遣婢來贈您珍茶名果、錦衣玉帶、絹布綾羅，併薰香數種供您選用。",
  ui_story_5075_50750100_84_dialog_content = "這些全都是給我用的？可是……",
  ui_story_5075_50750100_85_dialog_content = "禮已送到，婢先行告退。",
  ui_story_5075_50750100_86_dialog_content = "還望使者大人在濟之日，生活康樂，也好讓灼華郡主放心。",
  ui_story_5075_50750100_87_dialog_content = "<color=#e8d9bb>第三天</color>",
  ui_story_5075_50750100_88_dialog_content = "……怎麼還不能進宮啊。",
  ui_story_5075_50750100_89_dialog_content = "使者大人可是感到無趣？那您喜歡看戲嗎？",
  ui_story_5075_50750100_90_dialog_content = "若是喜歡，婢這就去請知名的優伶來為您唱堂會。",
  ui_story_5075_50750100_91_dialog_content = "那個，我不是說……",
  ui_story_5075_50750100_92_dialog_content = "您不喜歡？那可要聽評彈，看雜耍？",
  ui_story_5075_50750100_93_dialog_content = "若是不愛好這類，也可試試鬥蟋蟀、鬥鵪鶉，皓津城玩樂的法子可多呢。",
  ui_story_5075_50750100_94_dialog_content = "不，我現在真的不需要什麼蟋蟀、鵪鶉……",
  ui_story_5075_50750100_95_dialog_content = "我想出去！我要去見濟王殿下！",
  ui_story_5075_50750100_96_dialog_content = "<color=#e8d9bb>第四天</color>",
  ui_story_5075_50750100_97_dialog_content = "啊，終於出來了。",
  ui_story_5075_50750100_98_dialog_content = "但這裡是哪裡？好多牌子，濟王應該不住在這裡吧……",
  ui_story_5075_50750100_99_dialog_content = "回使者大人的話，使者大人這兩天茶飯不思，興許是憋悶所致。",
  ui_story_5075_50750100_100_dialog_content = "所以婢去拜託主事官，為您安排了賞樂行程。",
  ui_story_5075_50750100_101_dialog_content = "對初來皓津的客人來說，這南山龍女廟可是最不容錯過的一景。",
  ui_story_5075_50750100_102_dialog_content = "此處不光山峰聳秀，怪石玲瓏，傳聞還曾有龍女娘娘的神蹟顯現呢。",
  ui_story_5075_50750100_103_dialog_content = "您可按心意賞景或拜神，閒雜人等都已清退，不會有人打擾您。",
  ui_story_5075_50750100_104_dialog_content = "啊？還為我趕走了其他人？難怪這麼冷清……",
  ui_story_5075_50750100_105_dialog_content = "其實不用這麼麻煩，我又不是什麼大人物，跟大家一起參觀也沒關係呀。",
  ui_story_5075_50750100_106_dialog_content = "使者大人說笑了。您是濟國的貴客，婢等自當盡心。",
  ui_story_5075_50750100_107_dialog_content = "那麼，請您隨意。",
  ui_story_5075_50750100_108_dialog_content = "（好吧……既然來了，就四處逛逛吧。）",
  ui_story_5075_50750100_109_dialog_content = "（正殿中央的塑像就是傳說中的龍女娘娘嗎？好莊嚴啊。）",
  ui_story_5075_50750100_110_dialog_content = "（周圍的供品果然像丹棠說的，什麼都有。瓜果蔬菜、茶葉點心……）",
  ui_story_5075_50750100_111_dialog_content = "咦，有人！這裡還有別人？",
  ui_story_5075_50750100_112_dialog_content = "<color=#e8d9bb>叮——</color>",
  ui_story_5075_50750100_113_dialog_content = "這是……哪位侍女掉的飾品？還是剛才那個人的？",
  ui_story_5075_50750100_114_dialog_content = "使者大人——",
  ui_story_5075_50750100_115_dialog_content = "婢已經檢查過數次，廟內除您之外再無其他香客。",
  ui_story_5075_50750100_116_dialog_content = "但大殿裡確實有個人影，好像還掉了東西……",
  ui_story_5075_50750100_117_dialog_content = "婢沒有看見……呀！",
  ui_story_5075_50750100_118_dialog_content = "台上的供品怎都不見了？！",
  ui_story_5075_50750100_119_dialog_content = "怎，怎麼會……",
  ui_story_5075_50750100_120_dialog_content = "使者大人請恕罪，是婢等有所疏漏，竟放了小賊進來。",
  ui_story_5075_50750100_121_dialog_content = "龍女廟妖魔不敢近，一定又是那些祟靈……",
  ui_story_5075_50750100_122_dialog_content = "祟靈怎麼了？",
  ui_story_5075_50750100_123_dialog_content = "只、只是些小事，不值得使者大人掛心。",
  ui_story_5075_50750100_124_dialog_content = "今日之行是婢等失職，請您先隨侍衛移步下山，婢要將此事稟告主事官。",
  ui_story_5075_50750100_125_dialog_content = "來人呀！快護送使者大人回館！",
  ui_story_5075_50750100_126_dialog_content = "得令！",
  ui_story_5075_50750100_127_dialog_content = "哎啊啊，你們等一下……讓我多呼吸一口新鮮空氣啊——",
  ui_story_5075_50750100_128_dialog_content = "（之後的幾天，也依舊如此。）",
  ui_story_5075_50750100_129_dialog_content = "（吃飯、休息、遊樂……我被關照得無微不至，隨便走走都有護衛隨行。）",
  ui_story_5075_50750100_130_dialog_content = "（唯獨對於何時入宮的問題，始終沒得到明確的回答。）",
  ui_story_5075_50750100_131_dialog_content = "再這樣下去不行，我得自己去找那個主事官問問。",
  ui_story_5075_50750100_132_dialog_content = "到底什麼時候才能去見濟王，討論丹棠所說的交往要務？",
  ui_story_5075_50750100_133_dialog_content = "希望這次出來沒有侍衛攔我……",
  ui_story_5075_50750100_134_dialog_content = "……灼華郡主。",
  ui_story_5075_50750100_135_dialog_content = "（嗯？剛剛是不是有人提到丹棠？）",
  ui_story_5075_50750100_136_dialog_content = "消息是真的嗎？！",
  ui_story_5075_50750100_137_dialog_content = "哈哈，無風不起浪。",
  ui_story_5075_50750100_138_dialog_content = "我聽說咱們世子對那郡主可是癡心一片，眼裡半點容不下他人。",
  ui_story_5075_50750100_139_dialog_content = "郡主還沒答應。但宮裡的姐妹都說，大王有意給兩人賜婚。",
  ui_story_5075_50750100_140_dialog_content = "怕是好事將近了！所以宮裡頭才忙忙碌碌，顧不上其他。",
  ui_story_5075_50750100_141_dialog_content = "哎喲喲，一個質子，可真是高攀了！我記得她是來抵債的吧？",
  ui_story_5075_50750100_142_dialog_content = "？！",
  ui_story_5075_50750100_143_dialog_content = "請問妳們剛才說的是——",
  ui_story_5075_50750100_144_dialog_content = "使者大人您在這兒啊，下官找了好一番呢。",
  ui_story_5075_50750100_145_dialog_content = "大王有旨，特邀您參加今日的大宴，聽您引薦異邦要聞。",
  ui_story_5075_50750100_146_dialog_content = "請快準備準備，隨下官入宮吧。",
  ui_story_5075_50750100_147_dialog_content = "偏偏現在嗎？！您剛才都在幹什麼呀！",
  ui_story_5075_50750201_1_dialog_content = "<color=#e8d9bb>玉樓金闕，奇麗巍峨。和聲雅樂，奏鳴四方。</color>",
  ui_story_5075_50750201_2_dialog_content = "艾斯特拉來使，登殿——",
  ui_story_5075_50750201_3_dialog_content = "西邊大陸之人，確實與吾等有所不同。",
  ui_story_5075_50750201_4_dialog_content = "衣著也是新奇，可惜裁剪太過，倒是少了些風雅之意。",
  ui_story_5075_50750201_5_dialog_content = "據說他屬空裔一族，在西邊大陸也是少見的異人。",
  ui_story_5075_50750201_6_dialog_content = "（好像都在討論我啊。）",
  ui_story_5075_50750201_7_dialog_content = "（還好丹棠也在，沒人欺負她吧。但她的表情好像有點嚴肅？)",
  ui_story_5075_50750201_8_dialog_content = "你就是PlayerName？本王早聽說你為兩塊大陸的航線復通出力不少。",
  ui_story_5075_50750201_9_dialog_content = "今日一見，確實可稱年少有為。",
  ui_story_5075_50750201_10_dialog_content = "您過獎了，蜃風號能順利返航，還是多虧船上大家齊心協力……",
  ui_story_5075_50750201_11_dialog_content = "不必謙虛。來人，賜座上茶。",
  ui_story_5075_50750201_12_dialog_content = "難得見到海對岸的遠客，不如給眾卿講講異邦大陸之事？",
  ui_story_5075_50750201_13_dialog_content = "聽聞彼方有能征擅戰的鋼鐵巨人。",
  ui_story_5075_50750201_14_dialog_content = "戰士置於其中，以心念便可駕馭。其目如雷光，其力可斷山河。可屬實？",
  ui_story_5075_50750201_X14_option_content = "這也太誇張了",
  ui_story_5075_50750201_15_dialog_content = "這……有些誇張了。",
  ui_story_5075_50750201_16_dialog_content = "艾斯特拉的機械暫時還沒達到那種程度。",
  ui_story_5075_50750201_17_dialog_content = "雖然有巨像，但也並非如此強大的武器。",
  ui_story_5075_50750201_18_dialog_content = "更別說巨像的數量不多，能操縱巨像的人也寥寥無幾。",
  ui_story_5075_50750201_X18_option_content = "未來也許可以",
  ui_story_5075_50750201_X19_dialog_content = "雖然暫時沒有這樣強大的力量……",
  ui_story_5075_50750201_X20_dialog_content = "但有擅長軍工機械的啟光聯邦，和擅長法術儀式的白夜城。",
  ui_story_5075_50750201_X21_dialog_content = "未來艾斯特拉也許真的能造出您所形容的巨人。",
  ui_story_5075_50750201_X22_dialog_content = "喔……也就是說並沒有這種事物。",
  ui_story_5075_50750201_19_dialog_content = "那將士們如何迎戰妖魔？",
  ui_story_5075_50750201_20_dialog_content = "軍隊會研發各種武器，也有戰甲保護身體。",
  ui_story_5075_50750201_21_dialog_content = "再配合光能術，就能和暗鬼……也就是「妖魔」作戰了。",
  ui_story_5075_50750201_22_dialog_content = "原來還是以肉身相搏啊。",
  ui_story_5075_50750201_23_dialog_content = "那彼方大陸也算遼闊，可有不死之術，或是升天之法啊？",
  ui_story_5075_50750201_24_dialog_content = "這個……我想應該沒有吧。",
  ui_story_5075_50750201_25_dialog_content = "各地都有少數長壽者，北境的君主又格外以青春常駐著稱。",
  ui_story_5075_50750201_26_dialog_content = "但沒有聽過絕對的不老不死……至少我沒聽過。",
  ui_story_5075_50750201_27_dialog_content = "嚯，看來雖隔著大海，對岸倒是與龍洲也無甚差別。",
  ui_story_5075_50750201_28_dialog_content = "不全是……",
  ui_story_5075_50750201_29_dialog_content = "咳。",
  ui_story_5075_50750201_30_dialog_content = "（莫要衝動。）",
  ui_story_5075_50750201_31_dialog_content = "……",
  ui_story_5075_50750201_32_dialog_content = "比起這些，本王倒是聽說PlayerName你有些奇異的能力。",
  ui_story_5075_50750201_33_dialog_content = "可令能術之力增強數倍。",
  ui_story_5075_50750201_34_dialog_content = "不如本王給你封個虛職小官，就此留在濟國如何？",
  ui_story_5075_50750201_35_dialog_content = "這幾日你也見識了皓津之景。",
  ui_story_5075_50750201_36_dialog_content = "我濟國川澤沃衍，有海陸之饒，百事繁庶，堪稱地上天宮。",
  ui_story_5075_50750201_37_dialog_content = "豈不比那片妖魔橫行的大陸更好？",
  ui_story_5075_50750201_38_dialog_content = "呃，感謝您的美意，但艾斯特拉是我的家鄉，我終究還是得回去。",
  ui_story_5075_50750201_39_dialog_content = "而且我以使節身分前來，也不是為自己享樂，而是為了促進兩塊大陸的交流。",
  ui_story_5075_50750201_40_dialog_content = "在艾斯特拉大陸，有不少對暗鬼十分有效的科技產品，不只啟光、白夜城……",
  ui_story_5075_50750201_41_dialog_content = "嗯，所言有理、有理。但此等小事就交給市舶司去處理吧。",
  ui_story_5075_50750201_42_dialog_content = "現在談這些話題，未免辜負了此刻的良辰美景。",
  ui_story_5075_50750201_43_dialog_content = "春朔佳節將至，濟國之繁華富裕，無奇不有，我等當共相慶。",
  ui_story_5075_50750201_44_dialog_content = "眾卿，舉杯——",
  ui_story_5075_50750201_45_dialog_content = "但我……",
  ui_story_5075_50750201_46_dialog_content = "敬大王萬壽千秋！",
  ui_story_5075_50750201_47_dialog_content = "敬濟國物阜年豐！",
  ui_story_5075_50750201_48_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5075_50750201_49_dialog_content = "是地動！",
  ui_story_5075_50750201_50_dialog_content = "快、快保護大王！",
  ui_story_5075_50750201_51_dialog_content = "<color=#e8d9bb>桌椅搖晃，碗碟摔落，震動好半天才完全平息。</color>",
  ui_story_5075_50750201_52_dialog_content = "<color=#e8d9bb>歌舞昇平的大殿已成一片狼藉，只聽得眾人奔忙傳令之聲。</color>",
  ui_story_5075_50750201_53_dialog_content = "<color=#e8d9bb>方才還意氣風發的官員們，時下則多有狼狽之相。</color>",
  ui_story_5075_50750201_54_dialog_content = "呼……好在得到訊息，百姓都平安無事。",
  ui_story_5075_50750201_55_dialog_content = "雖然不盡如人意，但今日的宴會只能就此結束了。",
  ui_story_5075_50750201_56_dialog_content = "丹棠？",
  ui_story_5075_50750201_57_dialog_content = "來吧，PlayerName公子，我們換個清淨的地方。",
  ui_story_5075_50750201_58_dialog_content = "頭巾好像勾到什麼，我拉一下……",
  ui_story_5075_50750201_59_dialog_content = "不好意思，丹棠，能幫我個忙嗎？",
  ui_story_5075_50750201_60_dialog_content = "這樹上的花苞這麼好看，一定很嬌貴，我怕太用力扯壞了。",
  ui_story_5075_50750201_61_dialog_content = "噗——一點也不嬌貴，這梅花樹院裡到處都有，公子怕是第一位這麼小心對待的人。",
  ui_story_5075_50750201_62_dialog_content = "請先別動，我來解開。",
  ui_story_5075_50750201_63_dialog_content = "……",
  ui_story_5075_50750201_64_dialog_content = "呵呵，好了。",
  ui_story_5075_50750201_65_dialog_content = "這幾日未見，你在禮賓館過得可還習慣？",
  ui_story_5075_50750201_66_dialog_content = "嗯，就是總覺得大家對我照顧過頭了。",
  ui_story_5075_50750201_67_dialog_content = "連倒水都不讓我自己動手，好像我有多貴重一樣。",
  ui_story_5075_50750201_68_dialog_content = "難道不是？",
  ui_story_5075_50750201_69_dialog_content = "妳別調侃我了啦。",
  ui_story_5075_50750201_70_dialog_content = "在那種讓人眼花繚亂的招待下，我沒鬧笑話就不錯了。",
  ui_story_5075_50750201_71_dialog_content = "而且使節的工作也處理得不太好。",
  ui_story_5075_50750201_72_dialog_content = "好不容易等到進宮，別說商談合作了，甚至都沒好好介紹一下艾斯特拉。",
  ui_story_5075_50750201_73_dialog_content = "……抱歉，PlayerName公子。",
  ui_story_5075_50750201_74_dialog_content = "是我思慮不周。",
  ui_story_5075_50750201_75_dialog_content = "將你從另一片大陸請來，卻沒準備好任你發言的舞台。",
  ui_story_5075_50750201_76_dialog_content = "這也不能怪丹棠啊，要是我有提前做些準備，也不至於這麼手忙腳亂。",
  ui_story_5075_50750201_77_dialog_content = "不，還是我……",
  ui_story_5075_50750201_78_dialog_content = "噗嗤。",
  ui_story_5075_50750201_79_dialog_content = "啊哈哈……這麼互相搶著道歉有點怪怪的。",
  ui_story_5075_50750201_80_dialog_content = "算了，過去的事情糾結也沒用。我回去後好好準備，下次進宮再努力吧。",
  ui_story_5075_50750201_81_dialog_content = "……還有一件事。",
  ui_story_5075_50750201_82_dialog_content = "嗯？",
  ui_story_5075_50750201_83_dialog_content = "來之前，我聽禮賓館的侍女說……妳和濟國世子之間有婚約？",
  ui_story_5075_50750201_84_dialog_content = "她們談論你的口氣也很不好聽，說妳是抵債的。",
  ui_story_5075_50750201_85_dialog_content = "所以我想知道，妳是不是在這裡受人欺負了？",
  ui_story_5075_50750201_86_dialog_content = "公子……",
  ui_story_5075_50750201_87_dialog_content = "我、我沒事。",
  ui_story_5075_50750201_88_dialog_content = "其實，這些傳言我也聽過幾句，只是沒想到都傳進你耳中了。",
  ui_story_5075_50750201_89_dialog_content = "國君確有此意，但我拒絕之志已明，他並不能逼迫我。",
  ui_story_5075_50750201_X89_dialog_content = "至於抵債之事……丹棠是因鄴國借貸而入質，此事不假。",
  ui_story_5075_50750201_X90_dialog_content = "然而，下人確實不應隨意置評此事。我此後定會處置這些說長道短之人。",
  ui_story_5075_50750201_X91_dialog_content = "丹棠……",
  ui_story_5075_50750201_90_dialog_content = "請放心，我在這裡也算是經營已久，絕非孤立無援。",
  ui_story_5075_50750201_91_dialog_content = "偌大宮廷，還沒有人敢明目張膽地欺到我頭上來。",
  ui_story_5075_50750201_92_dialog_content = "那世子也不敢囉？",
  ui_story_5075_50750201_93_dialog_content = "呵呵，當然不敢！況且世子還只是個……",
  ui_story_5075_50750201_94_dialog_content = "丹棠！丹棠！妳沒事吧！",
  ui_story_5075_50750201_95_dialog_content = "……世子？！夜已深了，您該回寢殿休息才對。",
  ui_story_5075_50750201_96_dialog_content = "我擔心丹棠啊。",
  ui_story_5075_50750201_97_dialog_content = "剛剛地動得那麼厲害，妳沒事吧？有沒有受傷？害怕嗎？",
  ui_story_5075_50750201_98_dialog_content = "唉。您放心，我好好的，哪裡都沒傷到。",
  ui_story_5075_50750201_99_dialog_content = "倒是世子您，連個護衛都不帶就跑出來，小心大王知道，又要打手板了。",
  ui_story_5075_50750201_100_dialog_content = "本、本世子已經長大了！打手板什麼的才、才不害怕呢！",
  ui_story_5075_50750201_101_dialog_content = "而且男子漢大丈夫，危急時刻，不待在未婚妻身邊怎麼行！",
  ui_story_5075_50750201_102_dialog_content = "噗——",
  ui_story_5075_50750201_103_dialog_content = "您怎能又這般胡亂開口——",
  ui_story_5075_50750201_104_dialog_content = "喔？大丈夫？看來是老夫疏忽了。",
  ui_story_5075_50750201_105_dialog_content = "世子的課業如今是幼學小童的標準，但若是已成了大丈夫。那……",
  ui_story_5075_50750201_106_dialog_content = "要去告知夫子，課業太少，今後加倍！",
  ui_story_5075_50750201_107_dialog_content = "不……不當了不當了！我不當大丈夫了！！",
  ui_story_5075_50750201_108_dialog_content = "本，本世子雖志存高遠，但身心還不夠強健，恐難當此大任！",
  ui_story_5075_50750201_109_dialog_content = "……累了累了，本世子就先回去休息了～",
  ui_story_5075_50750201_110_dialog_content = "丹棠，明天再一起玩！",
  ui_story_5075_50750201_111_dialog_content = "宮裡新來了一個擅長做鄴國菜的廚子，父王叫妳明天去吃大餐。",
  ui_story_5075_50750201_112_dialog_content = "一定要來喔！",
  ui_story_5075_50750201_113_dialog_content = "唉……",
  ui_story_5075_50750201_114_dialog_content = "多謝老師幫忙，不然世子一定不會這麼乖乖回去睡覺。",
  ui_story_5075_50750201_115_dialog_content = "PlayerName公子，這位是濟國的國師大人，在大王身邊輔佐朝政。",
  ui_story_5075_50750201_116_dialog_content = "同時也是我的老師。",
  ui_story_5075_50750201_117_dialog_content = "多年來，幸得老師的教導跟照顧，我才在濟國安穩成長至今。",
  ui_story_5075_50750201_118_dialog_content = "（是這麼重要的人嗎？等等，龍洲的禮節要怎麼做來著？！）",
  ui_story_5075_50750201_119_dialog_content = "見過國師大人！",
  ui_story_5075_50750201_120_dialog_content = "老師，這是來自艾斯特拉的PlayerName公子，您剛剛也見過了。",
  ui_story_5075_50750201_121_dialog_content = "嗯。我印象深刻。",
  ui_story_5075_50750201_122_dialog_content = "（不愧是丹棠的老師。被他盯著看，比之前在大殿裡被圍觀還要緊張……）",
  ui_story_5075_50750201_123_dialog_content = "咦？老師手裡的信，那標誌是……",
  ui_story_5075_50750201_124_dialog_content = "來自「巡檢司」的急報。",
  ui_story_5075_50750201_125_dialog_content = "難道是早前因為暗鬼增加，臨時調去城外海灣戍守的那隊？",
  ui_story_5075_50750201_126_dialog_content = "現在他們的對手，恐怕不只妖魔了。",
  ui_story_5075_50750201_127_dialog_content = "據急報所述，剛剛地動過後，近海忽有祟靈狂化傷人。",
  ui_story_5075_50750201_128_dialog_content = "巡邏隊雖及時制止，但恐怕這並非孤例。",
  ui_story_5075_50750201_129_dialog_content = "祟靈狂化？怎麼會這樣……莫非這次地動並非單純的天災，而是另有隱情？",
  ui_story_5075_50750202_1_dialog_content = "所以老夫來此，本是希望將此事交予妳調查。",
  ui_story_5075_50750202_2_dialog_content = "好，那我明天——",
  ui_story_5075_50750202_3_dialog_content = "妳明日不是還要幫大王帶孩子嗎？",
  ui_story_5075_50750202_4_dialog_content = "這……",
  ui_story_5075_50750202_5_dialog_content = "我能幫忙嗎？",
  ui_story_5075_50750202_6_dialog_content = "丹棠沒有時間，但我有空，只是調查的話我應該也能勝任。",
  ui_story_5075_50750202_7_dialog_content = "不行，讓PlayerName公子臨時前來擔任使節，本就已是強人所難。",
  ui_story_5075_50750202_8_dialog_content = "怎可再為濟國之事麻煩你？",
  ui_story_5075_50750202_9_dialog_content = "老夫認為可行。",
  ui_story_5075_50750202_10_dialog_content = "老師？",
  ui_story_5075_50750202_11_dialog_content = "灼華的那份交流計畫，老夫曾看過。",
  ui_story_5075_50750202_12_dialog_content = "但在殿內，大王無意立即推行的態度也已十分明顯。",
  ui_story_5075_50750202_13_dialog_content = "實在可惜。",
  ui_story_5075_50750202_14_dialog_content = "PlayerName，你既身為一方使節，想必也希望能去大王面前再爭取一二。",
  ui_story_5075_50750202_15_dialog_content = "是的。",
  ui_story_5075_50750202_16_dialog_content = "我背負著很多人的期待，又在很多人的幫助下來到這裡。絕不想無功而返。",
  ui_story_5075_50750202_17_dialog_content = "那這就是個好機會了。",
  ui_story_5075_50750202_18_dialog_content = "春朔節就在眼前，城內人流往來，各色活動眾多。",
  ui_story_5075_50750202_19_dialog_content = "此時妖魔與祟靈的任何異動都可能造成嚴重後果，傷及民生。",
  ui_story_5075_50750202_20_dialog_content = "若是有人能儘早解決此事，就是立功。",
  ui_story_5075_50750202_21_dialog_content = "大王必會論功行賞。",
  ui_story_5075_50750202_22_dialog_content = "賞賜倒是無所謂，禮賓館裡還有一堆我都不知道怎麼用的東西……",
  ui_story_5075_50750202_23_dialog_content = "但我非常想藉此機會，拜託濟王殿下聽聽我們的計畫！",
  ui_story_5075_50750202_24_dialog_content = "國師大人，請將這個任務交給我吧。",
  ui_story_5075_50750202_25_dialog_content = "老夫還有一個要求，若你能答應，此事便交由你做。",
  ui_story_5075_50750202_26_dialog_content = "什麼要求？",
  ui_story_5075_50750202_27_dialog_content = "……盡量隱密行動，勿將差事透漏給朝中之人。",
  ui_story_5075_50750202_28_dialog_content = "老師，PlayerName公子來自異域，在濟國本就行動不便，怎還叫他獨自行動？",
  ui_story_5075_50750202_29_dialog_content = "老夫可不曾說要叫PlayerName獨自行動。",
  ui_story_5075_50750202_30_dialog_content = "聽言不察意。灼華，妳心急了。",
  ui_story_5075_50750202_31_dialog_content = "……",
  ui_story_5075_50750202_32_dialog_content = "丹棠，沒事的。",
  ui_story_5075_50750202_33_dialog_content = "在艾斯特拉大陸時，我也去過很多陌生的地方接委託，勉強能算經驗豐富。",
  ui_story_5075_50750202_34_dialog_content = "甚好。",
  ui_story_5075_50750202_35_dialog_content = "灼華，送這位少年子出宮吧。",
  ui_story_5075_50750202_36_dialog_content = "……好。",
  ui_story_5075_50750202_37_dialog_content = "PlayerName公子——",
  ui_story_5075_50750202_38_dialog_content = "如果妳要再說抱歉或勸我放棄之類的話，我可不打算聽喔。",
  ui_story_5075_50750202_39_dialog_content = "但一而再，再而三地讓公子奔波，我卻待在宮裡……",
  ui_story_5075_50750202_40_dialog_content = "可是宴會上的菜很好吃。",
  ui_story_5075_50750202_41_dialog_content = "？",
  ui_story_5075_50750202_42_dialog_content = "丹棠不覺得嗎？比雙榭城的菜還要精緻好多。",
  ui_story_5075_50750202_43_dialog_content = "嗯，畢竟都是出自御廚之手。",
  ui_story_5075_50750202_44_dialog_content = "也就是說不是我們自己做的。那麼，米是我們種的嗎？",
  ui_story_5075_50750202_45_dialog_content = "當然是田間的農人。",
  ui_story_5075_50750202_46_dialog_content = "是我們運進城的嗎？",
  ui_story_5075_50750202_47_dialog_content = "不，是各地的商行。",
  ui_story_5075_50750202_48_dialog_content = "是我們買的嗎？",
  ui_story_5075_50750202_49_dialog_content = "不，是宮中的採買司。",
  ui_story_5075_50750202_50_dialog_content = "但丹棠不會覺得麻煩他們，轉而想自己去替他們做這些事吧。",
  ui_story_5075_50750202_51_dialog_content = "……這是各司其職，我倒也沒有傲慢至此。",
  ui_story_5075_50750202_52_dialog_content = "這件事也差不多。",
  ui_story_5075_50750202_53_dialog_content = "誰都不可能一個人做完所有事，丹棠抽不開身，而我有能力，那就我去做。",
  ui_story_5075_50750202_54_dialog_content = "麻煩別人，依賴別人，世界就是這樣運作的。",
  ui_story_5075_50750202_55_dialog_content = "啊，當然了，要是妳覺得我辦事妳不放心……",
  ui_story_5075_50750202_56_dialog_content = "怎麼會！",
  ui_story_5075_50750202_57_dialog_content = "……真是的，比起使節，PlayerName公子倒比較適合當個辯士。",
  ui_story_5075_50750202_58_dialog_content = "你都說到這種地步，我再推拒，可就有些不知好歹了。",
  ui_story_5075_50750202_59_dialog_content = "哈哈，嗯……",
  ui_story_5075_50750202_60_dialog_content = "太好了，公子的氣色比我們剛出來時好多了。",
  ui_story_5075_50750202_61_dialog_content = "咳，有這麼明顯嗎……",
  ui_story_5075_50750202_62_dialog_content = "怪我害公子操了太多心，又要擔心交往使命，又要擔心地動之災……",
  ui_story_5075_50750202_63_dialog_content = "還要擔心我有沒有受委屈。心裡壓了這麼多事，狀態都受影響了。",
  ui_story_5075_50750202_64_dialog_content = "那我算是在瞎操心嗎？",
  ui_story_5075_50750202_65_dialog_content = "不，不如說多虧公子提醒。",
  ui_story_5075_50750202_66_dialog_content = "看在公子的面子上，我也得打起精神，早點解決這些事情才是。",
  ui_story_5075_50750202_67_dialog_content = "好啊，那就一起努力吧！即便我們不在同一個地方戰鬥……",
  ui_story_5075_50750202_68_dialog_content = "也依然能同心協力，共赴所望。",
  ui_story_5075_50750202_69_dialog_content = "使者大人，下官來接您回去。",
  ui_story_5075_50750202_70_dialog_content = "咦，主事官您怎麼來了？是特地來接我的嗎？",
  ui_story_5075_50750202_71_dialog_content = "當然，您在濟國一日，便一日是禮賓館的貴客，怎能怠慢？",
  ui_story_5075_50750202_72_dialog_content = "那我就回去了，等有新消息再見吧。",
  ui_story_5075_50750202_73_dialog_content = "我在宮中，靜候佳音。",
  ui_story_5075_50750202_74_dialog_content = "<color=#e8d9bb>片刻之後——</color>",
  ui_story_5075_50750202_75_dialog_content = "殿下？您怎麼一個人站在這裡？",
  ui_story_5075_50750202_76_dialog_content = "阿玖，妳回來啦。之前說的事情辦得順利嗎？",
  ui_story_5075_50750202_77_dialog_content = "玖駑鈍，還未查出真相。",
  ui_story_5075_50750202_78_dialog_content = "但近日仍有不少暗探在皓津暗中活動。",
  ui_story_5075_50750202_79_dialog_content = "玖不在殿下身邊時，還請殿下務必小心。",
  ui_story_5075_50750202_80_dialog_content = "我明白，辛苦阿玖了。",
  ui_story_5075_50750202_81_dialog_content = "不過我最近應該都會待在宮內，想來也難遇到什麼危險。",
  ui_story_5075_50750202_82_dialog_content = "對了，回寢殿記得提醒我寫封信。",
  ui_story_5075_50750202_83_dialog_content = "就連月白船長她們都送完貨，回了皓津。",
  ui_story_5075_50750202_84_dialog_content = "某位「璇璣卿」卻一上岸就音信全無，只留下幾句不知所云的話……",
  ui_story_5075_50750202_85_dialog_content = "看來還得我親自寫信興師問罪一番。",
  ui_story_5075_50750202_86_dialog_content = "咦？",
  ui_story_5075_50750202_87_dialog_content = "殿下，怎麼了？",
  ui_story_5075_50750202_88_dialog_content = "不用緊張，只是有點驚訝。",
  ui_story_5075_50750202_89_dialog_content = "感覺只過了一眨眼的功夫，這樹上的梅花苞，竟都開了……",
  ui_story_5075_50750202_90_dialog_content = "殿下不是獨愛海棠？",
  ui_story_5075_50750202_91_dialog_content = "但今日的梅，開得倒也令人歡心。",
  ui_story_5075_50750301_1_dialog_content = "（雖然自信滿滿地接下了調查任務……）",
  ui_story_5075_50750301_2_dialog_content = "（但還是出現了意想不到的阻礙啊！）",
  ui_story_5075_50750301_3_dialog_content = "我說啊……我只是想在街上逛逛，沒必要擺出這種陣勢吧。",
  ui_story_5075_50750301_4_dialog_content = "使者大人身分貴重，區區六名侍衛，不過最基本的儀仗罷了。",
  ui_story_5075_50750301_5_dialog_content = "下官已申請再為您增加九名侍衛，才好保證安全。",
  ui_story_5075_50750301_6_dialog_content = "還要增加嗎？！",
  ui_story_5075_50750301_7_dialog_content = "算了，先不說這個……",
  ui_story_5075_50750301_8_dialog_content = "這條街上，為什麼一個人都沒有？",
  ui_story_5075_50750301_9_dialog_content = "自然是為了不讓閒雜人等擾了您的雅興，已事先清場了。",
  ui_story_5075_50750301_10_dialog_content = "這已經根本不是逛街了吧！",
  ui_story_5075_50750301_11_dialog_content = "真是怪事，再怎麼說這也太過度保護了！",
  ui_story_5075_50750301_12_dialog_content = "（這樣下去別說調查，我根本連其他人都接觸不到啊。）",
  ui_story_5075_50750301_13_dialog_content = "……何必勞動您，我來轉交便好。",
  ui_story_5075_50750301_14_dialog_content = "（嗯？外面在說什麼？）",
  ui_story_5075_50750301_15_dialog_content = "宮裡可是吩咐婢要親手交給使者大人，您就別為難婢了。",
  ui_story_5075_50750301_16_dialog_content = "這可不敢，裡面請。",
  ui_story_5075_50750301_17_dialog_content = "使者大人安好。",
  ui_story_5075_50750301_18_dialog_content = "這是宮裡新來的御廚做的點心，貴人們都覺得味道不錯。",
  ui_story_5075_50750301_19_dialog_content = "特命婢為您送來些嚐嚐。",
  ui_story_5075_50750301_20_dialog_content = "謝謝。咦，竟然還是熱的？",
  ui_story_5075_50750301_21_dialog_content = "咱們皓津雖氣候溫和，但現在終究是冬天。",
  ui_story_5075_50750301_22_dialog_content = "為了使者大人吃得舒心，食盒底下放了暖爐溫著。",
  ui_story_5075_50750301_23_dialog_content = "這暖爐用的是鄴國傳來的新手藝。",
  ui_story_5075_50750301_24_dialog_content = "宮中所用的款式，還特意請巧匠在內側雕了花，可當擺飾。",
  ui_story_5075_50750301_25_dialog_content = "內側？在那種完全看不見的地方雕花？",
  ui_story_5075_50750301_26_dialog_content = "貴人說了……看不見的地方，才方便行事嘛。",
  ui_story_5075_50750301_27_dialog_content = "什麼？",
  ui_story_5075_50750301_28_dialog_content = "婢自言自語罷了，使者大人慢用，婢這便回宮覆命了。",
  ui_story_5075_50750301_29_dialog_content = "使者大人要現在用點心嗎？可要婢子再添些什麼？",
  ui_story_5075_50750301_30_dialog_content = "不用了，我想睡一會，妳們先回去吧。",
  ui_story_5075_50750301_31_dialog_content = "啊，點心就放在這裡吧，我醒了再吃。",
  ui_story_5075_50750301_32_dialog_content = "是。",
  ui_story_5075_50750301_33_dialog_content = "<color=#e8d9bb>暖爐冒著淡淡的煙氣，透過連綴層疊的銅片縫隙，能看到內部躍動的火焰。</color>",
  ui_story_5075_50750301_34_dialog_content = "<color=#e8d9bb>咔。</color>",
  ui_story_5075_50750301_35_dialog_content = "<color=#e8d9bb>爐內火焰熄滅的同時，本來聚在一起的銅片也驟然散開。</color>",
  ui_story_5075_50750301_36_dialog_content = "<color=#e8d9bb>在桌上攤成一朵小巧的海棠。</color>",
  ui_story_5075_50750301_37_dialog_content = "裡面藏著一塊令牌，和一張紙條？",
  ui_story_5075_50750301_38_dialog_content = "還望使者大人在濟之日，生活康樂，也好讓灼華郡主放心。",
  ui_story_5075_50750301_39_dialog_content = "她是來替丹棠傳信的！",
  ui_story_5075_50750301_40_dialog_content = "（令牌上的標誌，是那個「巡檢司」？但還不知道有什麼用。）",
  ui_story_5075_50750301_41_dialog_content = "（紙條上……是地圖！還標了地址！）",
  ui_story_5075_50750301_42_dialog_content = "（剛好現在侍女都被支開了。趁機溜走吧！）",
  ui_story_5075_50750301_43_option_content = "感應",
  ui_story_5075_50750301_44_dialog_content = "（附近的侍衛，東邊好像有兩人，南邊有三人……往西邊走吧。）",
  ui_story_5075_50750301_45_dialog_content = "喂，快動起來，使者大人不見了！",
  ui_story_5075_50750301_46_dialog_content = "你留在這，我去那邊找！",
  ui_story_5075_50750301_47_dialog_content = "（被發現得真快，好在這裡就是院子的邊緣，只要翻過這道牆……）",
  ui_story_5075_50750301_48_dialog_content = "……好高！",
  ui_story_5075_50750301_49_dialog_content = "使者大人！使者大人——",
  ui_story_5075_50750301_50_dialog_content = "（快被包圍了，得想個辦法……）",
  ui_story_5075_50750301_51_dialog_content = "你在玩捉迷藏嗎？",
  ui_story_5075_50750301_52_dialog_content = "誰？！",
  ui_story_5075_50750301_53_dialog_content = "這裡、這裡～",
  ui_story_5075_50750301_54_dialog_content = "抬頭往上看。",
  ui_story_5075_50750301_55_dialog_content = "小孩子？為什麼會在牆上……很危險的！",
  ui_story_5075_50750301_56_dialog_content = "才不危險，就算是一根繩子阿霓都能走喔。",
  ui_story_5075_50750301_57_dialog_content = "你還沒回答呢，是在玩捉迷藏嗎？阿霓也要加入。",
  ui_story_5075_50750301_58_dialog_content = "我不是在玩……",
  ui_story_5075_50750301_59_dialog_content = "使者大人？您在這裡嗎？",
  ui_story_5075_50750301_60_dialog_content = "糟糕，我還有急事！先走了——",
  ui_story_5075_50750301_61_dialog_content = "！",
  ui_story_5075_50750301_62_dialog_content = "啊，那個，我只是出來散步……",
  ui_story_5075_50750301_63_dialog_content = "使者大人！您在哪裡——",
  ui_story_5075_50750301_64_dialog_content = "？",
  ui_story_5075_50750301_65_dialog_content = "這裡也沒有，到底去哪了？",
  ui_story_5075_50750301_66_dialog_content = "使者大人——",
  ui_story_5075_50750301_67_dialog_content = "還說不是在玩。",
  ui_story_5075_50750301_68_dialog_content = "剛才那個侍衛好像完全沒看見我，難道是妳做的嗎？",
  ui_story_5075_50750301_69_dialog_content = "哼哼，稍微用了一點小手段。",
  ui_story_5075_50750301_70_dialog_content = "？",
  ui_story_5075_50750301_71_dialog_content = "？",
  ui_story_5075_50750301_72_dialog_content = "不對不對。",
  ui_story_5075_50750301_73_dialog_content = "這種時候，你不是應該震驚於阿霓的霸氣雄風，感激涕零，納頭便拜嗎？",
  ui_story_5075_50750301_74_dialog_content = "霸氣雄風……",
  ui_story_5075_50750301_75_dialog_content = "咳，妳為什麼覺得會是這種發展？",
  ui_story_5075_50750301_76_dialog_content = "來的路上，聽橋頭說故事的人講的～",
  ui_story_5075_50750301_77_dialog_content = "他說當今正流行這個呢，不對嗎？",
  ui_story_5075_50750301_78_dialog_content = "我想他說的應該不是這種流行……",
  ui_story_5075_50750301_79_dialog_content = "不過妳——",
  ui_story_5075_50750301_80_dialog_content = "我確實聽到這邊有動靜。",
  ui_story_5075_50750301_81_dialog_content = "但我剛檢查過……保險起見，再確認一遍吧。",
  ui_story_5075_50750301_82_dialog_content = "我們是在玩捉迷藏！",
  ui_story_5075_50750301_83_dialog_content = "拜託了，霸氣雄風的阿霓大人，請幫我溜出去吧。",
  ui_story_5075_50750301_84_dialog_content = "喔～你這小鬼頭還蠻會說話的。",
  ui_story_5075_50750301_85_dialog_content = "放心，捉迷藏這種遊戲，阿霓很擅長呢。",
  ui_story_5075_50750301_86_dialog_content = "祕訣就是一鼓作氣～",
  ui_story_5075_50750302_1_dialog_content = "呼……哈……呼……",
  ui_story_5075_50750302_2_dialog_content = "我覺得……妳可能對捉迷藏的玩法也有點誤會……",
  ui_story_5075_50750302_3_dialog_content = "絕無可能。",
  ui_story_5075_50750302_4_dialog_content = "你看，我們不是平安走出大門了嗎？",
  ui_story_5075_50750302_5_dialog_content = "中途沒被任何一個人發現喔。",
  ui_story_5075_50750302_6_dialog_content = "我就是在說，大搖大擺地一口氣衝出來，這不叫捉迷藏……",
  ui_story_5075_50750302_7_dialog_content = "而且所有人都對我們視若無睹，這應該算作弊吧。",
  ui_story_5075_50750302_8_dialog_content = "……不，仔細想想我也是受益者。",
  ui_story_5075_50750302_9_dialog_content = "謝謝，阿霓……呃，大人？",
  ui_story_5075_50750302_10_dialog_content = "噗哈哈，既然你都陪阿霓玩過了，大人的稱呼就免啦。",
  ui_story_5075_50750302_11_dialog_content = "好，阿霓。我叫PlayerName，是……",
  ui_story_5075_50750302_12_dialog_content = "空裔。",
  ui_story_5075_50750302_13_dialog_content = "阿霓知道喲。",
  ui_story_5075_50750302_14_dialog_content = "咦？",
  ui_story_5075_50750302_15_dialog_content = "使者大人？是您在外頭嗎？",
  ui_story_5075_50750302_16_dialog_content = "我還是快點離開吧。",
  ui_story_5075_50750302_17_dialog_content = "使者大人，真的是您！",
  ui_story_5075_50750302_18_dialog_content = "您怎麼不帶侍衛就自己出來？太危險了。",
  ui_story_5075_50750302_19_dialog_content = "快來人！",
  ui_story_5075_50750302_20_dialog_content = "等等，不用——",
  ui_story_5075_50750302_21_dialog_content = "吱！",
  ui_story_5075_50750302_22_dialog_content = "呀——有老鼠！救……救命！",
  ui_story_5075_50750302_23_dialog_content = "<color=#e8d9bb>唰！</color>",
  ui_story_5075_50750302_24_dialog_content = "啊啊啊！是祟靈……祟靈咬人啊！",
  ui_story_5075_50750302_25_dialog_content = "……噓噓噓，別大聲嚷嚷呀。",
  ui_story_5075_50750302_26_dialog_content = "<color=#e8d9bb>咚。</color>",
  ui_story_5075_50750302_27_dialog_content = "阿霓，妳幹了什麼？",
  ui_story_5075_50750302_28_dialog_content = "讓她稍微睡一會而已。",
  ui_story_5075_50750302_29_dialog_content = "然後是這傢伙。",
  ui_story_5075_50750302_30_dialog_content = "吱……",
  ui_story_5075_50750302_31_dialog_content = "怎麼看都不可能是普通老鼠……",
  ui_story_5075_50750302_32_dialog_content = "這就是厘青他們之前提過，沒有化過人形的祟靈嗎。",
  ui_story_5075_50750302_33_dialog_content = "身上還有種讓人很不舒服的感覺……難道是狂化？？",
  ui_story_5075_50750302_X33_dialog_content = "據急報所述，剛剛地動過後，近海忽有祟靈狂化傷人。",
  ui_story_5075_50750302_34_dialog_content = "你看得出來？",
  ui_story_5075_50750302_35_dialog_content = "那這個也該看得到吧。",
  ui_story_5075_50750302_36_dialog_content = "<color=#e8d9bb>阿霓的指尖在倒地的祟靈身上虛虛拂過，竟從牠體內撈出一團黑影。</color>",
  ui_story_5075_50750302_37_dialog_content = "<color=#e8d9bb>像是渾濁的霧氣，又聚集著隱約的惡意。</color>",
  ui_story_5075_50750302_38_option_content = "試著感應",
  ui_story_5075_50750302_39_dialog_content = "……恨……",
  ui_story_5075_50750302_40_dialog_content = "嘶——",
  ui_story_5075_50750302_41_dialog_content = "感應時會有種碰觸到腐蝕性液體一樣的痛感……那是什麼？",
  ui_story_5075_50750302_42_dialog_content = "陰魂不散的壞東西。",
  ui_story_5075_50750302_43_dialog_content = "小心！牠動起來了，可能要逃跑！",
  ui_story_5075_50750302_44_dialog_content = "<color=#e8d9bb>但眼前的女孩連表情都沒變。</color>",
  ui_story_5075_50750302_45_dialog_content = "<color=#e8d9bb>只指腹一合、一捻，張牙舞爪的黑氣就如火苗被掐滅般煙消雲散。</color>",
  ui_story_5075_50750302_46_dialog_content = "真是的，阿霓連覺都不睡跑來城裡，可不是為了幹這種麻煩事的。",
  ui_story_5075_50750302_47_dialog_content = "小PlayerName，你先自己玩會捉迷藏吧，阿霓還有別的事要做。",
  ui_story_5075_50750302_48_dialog_content = "等等——",
  ui_story_5075_50750302_49_dialog_content = "地上的這兩個要怎麼辦呢……",
  ui_story_5075_50750302_50_dialog_content = "糟糕，忘了做完事要處理現場。",
  ui_story_5075_50750302_51_dialog_content = "嘿咻。",
  ui_story_5075_50750302_52_dialog_content = "<color=#e8d9bb>女孩托起侍女的肩膀，讓她「飛」回了禮賓館。</color>",
  ui_story_5075_50750302_53_dialog_content = "<color=#e8d9bb>又扯著祟靈的尾巴，向著天空將牠甩得老遠。</color>",
  ui_story_5075_50750302_54_dialog_content = "這樣沒問題嗎？！",
  ui_story_5075_50750302_55_dialog_content = "當然了，祟靈可沒那麼脆弱。",
  ui_story_5075_50750302_56_dialog_content = "要是連這點都承受不住，還不如別修煉了，當一輩子野物還比較好。",
  ui_story_5075_50750302_57_dialog_content = "剛才感應的時候就覺得有點像，加上這個奇奇怪怪的樣子……",
  ui_story_5075_50750302_58_dialog_content = "果然，妳也是祟靈吧？",
  ui_story_5075_50750302_59_dialog_content = "咦？人呢？阿霓？",
  ui_story_5075_50750302_60_dialog_content = "我還想問問那團黑氣的事……算了。",
  ui_story_5075_50750302_61_dialog_content = "繼續調查下去，或許還能遇見她。",
  ui_story_5075_50750302_62_dialog_content = "我還是先去這個地址看看吧。",
  ui_story_5075_50750302_63_dialog_content = "……",
  ui_story_5075_50750401_1_dialog_content = "又一年春朔，都來嚐嚐我家的「甜福橘」呀——",
  ui_story_5075_50750401_2_dialog_content = "吃福橘，剝橘皮。我來剝給您免費嚐，不甜不要錢啊。",
  ui_story_5075_50750401_3_dialog_content = "芝麻瓜子糖白果，阿公家的老手藝，小郎君不來瞧一瞧？",
  ui_story_5075_50750401_4_dialog_content = "真熱鬧啊，自己逛街就是不一樣。",
  ui_story_5075_50750401_5_dialog_content = "打擾一下，請問您知道「魚林街」該怎麼走嗎？",
  ui_story_5075_50750401_6_dialog_content = "那遠了，你先朝著人最多的那個橋頭走，過了路口再問吧。",
  ui_story_5075_50750401_7_dialog_content = "謝謝，那邊人還真多啊。",
  ui_story_5075_50750401_8_dialog_content = "外鄉人第一次來？皓津每年春朔節期間都有廟會，很受歡迎呢。",
  ui_story_5075_50750401_9_dialog_content = "就在那條街。",
  ui_story_5075_50750401_10_dialog_content = "等會還有名角唱戲，你要是不急也去看看呀！",
  ui_story_5075_50750401_11_dialog_content = "好，我有時間就去。",
  ui_story_5075_50750401_12_dialog_content = "唉，你來得不巧，往年還更熱鬧呢。",
  ui_story_5075_50750401_13_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_5075_50750401_14_dialog_content = "什麼聲音？",
  ui_story_5075_50750401_15_dialog_content = "喔，小孩子摔炮竹鬧著玩呢。",
  ui_story_5075_50750401_16_dialog_content = "這個不夠響，再來一個！",
  ui_story_5075_50750401_17_dialog_content = "放鞭炮、驅祟獸，趕得霉運嗷嗷叫！",
  ui_story_5075_50750401_18_dialog_content = "<color=#e8d9bb>砰！砰！</color>",
  ui_story_5075_50750401_19_dialog_content = "哈哈哈哈！",
  ui_story_5075_50750401_20_dialog_content = "吱……",
  ui_story_5075_50750401_21_dialog_content = "這哪叫鬧著玩？在大街上這麼做很危險吧！",
  ui_story_5075_50750401_22_dialog_content = "而且那隻祟靈並沒有狂……根本沒有傷人啊！",
  ui_story_5075_50750401_23_dialog_content = "也沒什麼關係吧？就算是普通的春朔節，也有放鞭炮驅趕祟靈的傳統儀式。",
  ui_story_5075_50750401_24_dialog_content = "只差在以前都是商家雇的祟靈演員，這幾個孩子是玩真的而已。",
  ui_story_5075_50750401_25_dialog_content = "我以前也沒把這儀式當回事，但最近越來越不太平。",
  ui_story_5075_50750401_26_dialog_content = "怕是祟靈真有點不吉利。",
  ui_story_5075_50750401_27_dialog_content = "雖然你是異鄉人，但我勸你也離那些東西遠一點吧。唉，我先走了。",
  ui_story_5075_50750401_28_dialog_content = "牠怎麼都不動了？該不會死了吧……",
  ui_story_5075_50750401_29_dialog_content = "再炸一下看看？",
  ui_story_5075_50750401_30_dialog_content = "不行，不管怎麼說這都太過分了。",
  ui_story_5075_50750401_31_dialog_content = "！",
  ui_story_5075_50750401_32_dialog_content = "（是那種黑氣！又出現了……而且漸漸往祟靈身上聚集！）",
  ui_story_5075_50750401_33_dialog_content = "你們快躲開！",
  ui_story_5075_50750401_34_dialog_content = "啊？幹嘛呀。",
  ui_story_5075_50750401_35_dialog_content = "……",
  ui_story_5075_50750401_36_dialog_content = "這傢伙……是不是不太對勁？",
  ui_story_5075_50750401_37_dialog_content = "吱！",
  ui_story_5075_50750401_38_dialog_content = "糟糕，來不及——",
  ui_story_5075_50750401_39_dialog_content = "吃我頭槌！",
  ui_story_5075_50750401_40_dialog_content = "吱——",
  ui_story_5075_50750401_41_dialog_content = "頭槌……竟然真的用頭把祟靈撞飛了？",
  ui_story_5075_50750401_42_dialog_content = "注意周圍，牠回來了！",
  ui_story_5075_50750402_1_dialog_content = "吱……",
  ui_story_5075_50750402_2_dialog_content = "好啦，已經沒事了。哎，你別亂動啊，要是再受傷了怎麼辦？",
  ui_story_5075_50750402_3_dialog_content = "吱吱！",
  ui_story_5075_50750402_4_dialog_content = "剛才是你相助於我對不對？了不起的指導！多謝了。",
  ui_story_5075_50750402_5_dialog_content = "我都看見了，你站出來是想救這隻祟靈。真是個好心人！",
  ui_story_5075_50750402_6_dialog_content = "哈哈……我也沒做什麼，壓制住牠的人是你。",
  ui_story_5075_50750402_7_dialog_content = "而且速度好快，附近人好像都沒意識到剛才發生了什麼事。",
  ui_story_5075_50750402_8_dialog_content = "因為這就是我的工作。",
  ui_story_5075_50750402_9_dialog_content = "還沒自我介紹，我叫羅松，算是個遊方道士。",
  ui_story_5075_50750402_10_dialog_content = "吱！",
  ui_story_5075_50750402_11_dialog_content = "平常都在四處周遊，做些降妖伏魔的活計。",
  ui_story_5075_50750402_12_dialog_content = "吱吱！",
  ui_story_5075_50750402_13_dialog_content = "這幾天，近郊的祟靈動輒就失去理智，暴起傷人。",
  ui_story_5075_50750402_14_dialog_content = "我為了調查原因才進城，沒想到護衛嚴密的皓津也……",
  ui_story_5075_50750402_15_dialog_content = "吱吱！！",
  ui_story_5075_50750402_16_dialog_content = "那個……祟靈的狀態是不是不太對？",
  ui_story_5075_50750402_17_dialog_content = "確實，從我抓住牠開始，牠就一直掙扎著想咬我。",
  ui_story_5075_50750402_18_dialog_content = "小心啊。",
  ui_story_5075_50750402_19_dialog_content = "沒關係，我可是靠和祟靈打交道吃飯的。",
  ui_story_5075_50750402_20_dialog_content = "這種型態的祟靈啊，只要用拇指和食指卡在後頸，讓爪子這樣，再這樣……",
  ui_story_5075_50750402_21_dialog_content = "用力抓住，就逃不掉了！",
  ui_story_5075_50750402_22_dialog_content = "原來如此，不愧是專業的。",
  ui_story_5075_50750402_23_dialog_content = "……等等，不是這個問題！",
  ui_story_5075_50750402_24_dialog_content = "讓我感應一下……",
  ui_story_5075_50750402_25_dialog_content = "果然，那股奇怪的黑氣還在祟靈體內，沒有祛除。",
  ui_story_5075_50750402_26_dialog_content = "「奇怪的黑氣」？",
  ui_story_5075_50750402_27_dialog_content = "嗯，我看得到！我想，祟靈就是被這黑氣影響才變得狂暴的。",
  ui_story_5075_50750402_28_dialog_content = "這就不是我擅長的範圍了，興許要請高人來處理。",
  ui_story_5075_50750402_29_dialog_content = "也不知用力打一拳能不能把你說的黑氣打出來。",
  ui_story_5075_50750402_30_dialog_content = "應該不能吧。",
  ui_story_5075_50750402_31_dialog_content = "不過我之前見過一個女孩子——",
  ui_story_5075_50750402_32_dialog_content = "喂！你們突然衝過來，又站在這裡碎碎唸些什麼呀？",
  ui_story_5075_50750402_33_dialog_content = "差點忘了，還有這幫小娃呢。",
  ui_story_5075_50750402_34_dialog_content = "還有……請教閣下的高姓大名？",
  ui_story_5075_50750402_35_dialog_content = "問我？PlayerName，我叫PlayerName。",
  ui_story_5075_50750402_36_dialog_content = "PlayerName，我記住了。先幫我抓一下這傢伙，好嗎？",
  ui_story_5075_50750402_37_dialog_content = "咦？",
  ui_story_5075_50750402_38_dialog_content = "吱！！",
  ui_story_5075_50750402_39_dialog_content = "哇啊，別把祟靈直接扔過來——嘶，掙扎得好厲害。",
  ui_story_5075_50750402_40_dialog_content = "（在羅松手裡的時候明明動也不動，他的力氣到底有多大——啊、別動！）",
  ui_story_5075_50750402_41_option_content = "強制感應！",
  ui_story_5075_50750402_42_dialog_content = "吱……",
  ui_story_5075_50750402_43_dialog_content = "呼，總算安靜了。",
  ui_story_5075_50750402_44_dialog_content = "<color=#e8d9bb>咚！咚！咚！</color>",
  ui_story_5075_50750402_45_dialog_content = "<color=#e8d9bb>羅松用指頭彈了彈孩子們的腦袋，以示懲戒。</color>",
  ui_story_5075_50750402_46_dialog_content = "（不過照羅松的力氣……不敢想有多痛……）",
  ui_story_5075_50750402_47_dialog_content = "嗚哇哇哇——",
  ui_story_5075_50750402_48_dialog_content = "你誰啊！憑什麼突然彈我們頭！好痛喔！",
  ui_story_5075_50750402_49_dialog_content = "我是羅松，行不更名，坐不改姓。",
  ui_story_5075_50750402_50_dialog_content = "因為我身正意誠，走到哪都不怕。",
  ui_story_5075_50750402_51_dialog_content = "倒是你們，敢告訴我名字嗎？我好去找你們爺娘告狀。",
  ui_story_5075_50750402_52_dialog_content = "怎麼能放任孩子在街上亂炸爆竹，欺負弱小呢？",
  ui_story_5075_50750402_53_dialog_content = "我、我叫……",
  ui_story_5075_50750402_54_dialog_content = "不對，我憑什麼告訴你？",
  ui_story_5075_50750402_55_dialog_content = "我爺娘說了，都是因為這些祟靈帶來霉運，最近才會四處鬧妖魔。",
  ui_story_5075_50750402_56_dialog_content = "你跟牠們是一夥的，一定也不是好人！",
  ui_story_5075_50750402_57_dialog_content = "我還說這是迷信呢。",
  ui_story_5075_50750402_58_dialog_content = "不該做的事就是不該做，別人的一兩句話可成不了你們的藉口。",
  ui_story_5075_50750402_59_dialog_content = "你親眼見過祟靈帶來妖魔嗎？",
  ui_story_5075_50750402_60_dialog_content = "這……雖然沒見過，但這隻祟靈偷了我們的糖瓜！",
  ui_story_5075_50750402_61_dialog_content = "大家湊零用錢買一起的，卻一轉眼就不見了。",
  ui_story_5075_50750402_62_dialog_content = "對啊！對啊！",
  ui_story_5075_50750402_63_dialog_content = "偷東西的就是壞蛋！這也是為民除害嘛！",
  ui_story_5075_50750402_64_dialog_content = "你說「轉眼就不見了」，表示你們沒親眼看見牠偷東西的瞬間。",
  ui_story_5075_50750402_65_dialog_content = "但旁邊只有這傢伙灰溜溜地跑過去，不是牠會是誰？",
  ui_story_5075_50750402_66_dialog_content = "PlayerName。",
  ui_story_5075_50750402_67_dialog_content = "幫忙檢查一下那隻祟靈的嘴巴好嗎？看看有沒有沾到糖漿。",
  ui_story_5075_50750402_68_dialog_content = "我看看……沒有。",
  ui_story_5075_50750402_69_dialog_content = "身上也只有傷口和污泥，沒有別的。",
  ui_story_5075_50750402_70_dialog_content = "那也不能證明不是牠！",
  ui_story_5075_50750402_71_dialog_content = "說不定牠用了什麼法術，唰一下就把糖瓜變走了呢！",
  ui_story_5075_50750402_72_dialog_content = "呃，用這麼厲害的法術，就為了偷糖吃？",
  ui_story_5075_50750402_73_dialog_content = "你們的糖瓜長什麼模樣？",
  ui_story_5075_50750402_74_dialog_content = "還能是什麼模樣？就白白的、圓圓的，像是……",
  ui_story_5075_50750402_75_dialog_content = "剝了皮的福橘？",
  ui_story_5075_50750402_76_dialog_content = "對！那麼好看又好吃的糖瓜，祟靈一定也喜歡。",
  ui_story_5075_50750402_77_dialog_content = "你們是在不遠處那位阿公的攤子買的吧？",
  ui_story_5075_50750402_78_dialog_content = "花光所有人的零用錢，那一定買不起別的了。",
  ui_story_5075_50750402_79_dialog_content = "但小孩子又饞嘴——而賣糖瓜的攤子旁邊，正好有攤主讓人試吃福橘。",
  ui_story_5075_50750402_80_dialog_content = "別告訴我你們沒去啊。",
  ui_story_5075_50750402_81_dialog_content = "去了就去了，那又怎麼樣？",
  ui_story_5075_50750402_82_dialog_content = "試吃福橘的時候，你們把糖瓜放在哪裡？",
  ui_story_5075_50750402_83_dialog_content = "當然就放在水果攤旁邊……啊！",
  ui_story_5075_50750402_84_dialog_content = "真的，是我們的糖瓜，混在剝開的福橘裡。",
  ui_story_5075_50750402_85_dialog_content = "……",
  ui_story_5075_50750402_86_dialog_content = "真相大白了。",
  ui_story_5075_50750402_87_dialog_content = "現在你們該說什麼？",
  ui_story_5075_50750402_88_dialog_content = "對不起……",
  ui_story_5075_50750402_89_dialog_content = "下次再遇到這種事，先仔細想想前因後果。",
  ui_story_5075_50750402_90_dialog_content = "別覺得把什麼都賴在祟靈身上就萬事大吉。",
  ui_story_5075_50750402_91_dialog_content = "就算你們把祟靈炸得傷痕累累，就找得回糖瓜嗎？",
  ui_story_5075_50750402_92_dialog_content = "因為迷信和成見，就對不瞭解的東西抱有惡意，擅自畫靶……",
  ui_story_5075_50750402_93_dialog_content = "除了鬧脾氣之外，根本沒有用處。",
  ui_story_5075_50750402_94_dialog_content = "這可不是為民除害，是懦夫行徑——明白了嗎？",
  ui_story_5075_50750402_95_dialog_content = "明白了……",
  ui_story_5075_50750402_96_dialog_content = "明白了就回家去，跟爺娘說今天的事。",
  ui_story_5075_50750402_97_dialog_content = "知道了……",
  ui_story_5075_50750402_98_dialog_content = "他們真的願意把真相告訴家人嗎？",
  ui_story_5075_50750402_99_dialog_content = "八成不會吧。",
  ui_story_5075_50750402_100_dialog_content = "我也知道，說這些話治標不治本。",
  ui_story_5075_50750402_101_dialog_content = "但三人成虎，「祟靈晦氣」這種謊話也是說多了才有人信。",
  ui_story_5075_50750402_102_dialog_content = "我說的是真話，只要一直說，一直講，總能有些成效吧？",
  ui_story_5075_50750402_103_dialog_content = "畢竟真就是真，假就是假。",
  ui_story_5075_50750402_104_dialog_content = "羅松真厲害啊。",
  ui_story_5075_50750402_105_dialog_content = "而且你居然一下子就幫他們找到了糖瓜，簡直就像親眼看見過程一樣。",
  ui_story_5075_50750402_106_dialog_content = "哈哈，這個啊……",
  ui_story_5075_50750402_107_dialog_content = "確實是看見了，不過不是我。",
  ui_story_5075_50750402_108_dialog_content = "嗯……你想不想見見和我一起降妖伏魔的朋友？",
  ui_story_5075_50750402_109_dialog_content = "吼！",
  ui_story_5075_50750402_110_dialog_content = "你的朋友……是祟靈？",
  ui_story_5075_50750402_111_dialog_content = "牠叫阿丁。",
  ui_story_5075_50750402_112_dialog_content = "剛才那幾個孩子弄丟糖瓜的事，就是牠看見告訴我的。",
  ui_story_5075_50750402_113_dialog_content = "我本來打算直接帶牠過去說出真相，但有位賣糖人師傅攔住了我。",
  ui_story_5075_50750402_114_dialog_content = "他提醒我現在城裡人對祟靈的態度很糟，我帶阿丁過去說不定會出事。",
  ui_story_5075_50750402_115_dialog_content = "我就叫阿丁在這裡等了。",
  ui_story_5075_50750402_116_dialog_content = "那段找出糖瓜的推論，也是糖人師傅教我說的。",
  ui_story_5075_50750402_117_dialog_content = "現在想想，他說得很有道理。",
  ui_story_5075_50750402_118_dialog_content = "我得過去謝謝他，順便買些糖人送給阿丁躲在別處的同伴。",
  ui_story_5075_50750402_119_dialog_content = "雖然我覺得不太可能……但羅松，你說的糖人師傅，難道是那邊那位？",
  ui_story_5075_50750402_120_dialog_content = "對，就是他！",
  ui_story_5075_50750402_121_dialog_content = "你在這等我一下，我去跟小傢伙們打聲招呼，馬上回來。",
  ui_story_5075_50750402_122_dialog_content = "……",
  ui_story_5075_50750402_123_dialog_content = "「糖人師傅」？",
  ui_story_5075_50750402_124_dialog_content = "哎，正是在下～",
  ui_story_5075_50750500_1_dialog_content = "……你不是算命的嗎？",
  ui_story_5075_50750500_2_dialog_content = "非也非也，您看這晶瑩剔透的糖漿～",
  ui_story_5075_50750500_3_dialog_content = "再看看這栩栩如生的手藝！",
  ui_story_5075_50750500_4_dialog_content = "都是承襲自祖上，又數年如一日的捏糖人才能練就的絕活。",
  ui_story_5075_50750500_5_dialog_content = "糖人師傅，如假包換！",
  ui_story_5075_50750500_6_dialog_content = "蜃風號上一別，咱們也是許久未見了。",
  ui_story_5075_50750500_7_dialog_content = "在這相遇也是有緣，不如在下送您一支糖人吧。",
  ui_story_5075_50750500_8_dialog_content = "我不是故意想懷疑你。",
  ui_story_5075_50750500_9_dialog_content = "但我總覺得你的禮物不能隨便收。",
  ui_story_5075_50750500_10_dialog_content = "唉，沒想到……",
  ui_story_5075_50750500_11_dialog_content = "咱們相識的日子不長，您卻已如此瞭解在下了。",
  ui_story_5075_50750500_12_dialog_content = "既然您看穿了，在下就不跟您客氣了。這個，勞您拿著。",
  ui_story_5075_50750500_13_dialog_content = "這是戴在身上的飾品吧？還是女孩子的。",
  ui_story_5075_50750500_14_dialog_content = "這是您來之前不久，一位買了糖人的客人掉的。",
  ui_story_5075_50750500_15_dialog_content = "但在下這生意太好，實在抽不出空去尋她歸還東西，只能麻煩您了。",
  ui_story_5075_50750500_16_dialog_content = "但我也還有事要做。",
  ui_story_5075_50750500_17_dialog_content = "放心，在下算過了，您兩位有大緣分。",
  ui_story_5075_50750500_18_dialog_content = "您做您的事便好，途中自然能遇到。",
  ui_story_5075_50750500_19_dialog_content = "果然你還是個算命的。",
  ui_story_5075_50750500_20_dialog_content = "等等，仔細一看這東西……和我在龍女廟撿到的一樣。",
  ui_story_5075_50750500_21_dialog_content = "而且印象裡在別人身上也見到過。",
  ui_story_5075_50750500_22_dialog_content = "不會吧……",
  ui_story_5075_50750500_23_dialog_content = "對了，李天閑，你知道<color=#FFB400>祟靈</color>的事情嗎？",
  ui_story_5075_50750500_24_dialog_content = "當然了。還記得之前跟您介紹過，在下獨創的<color=#FFB400>萬類天斗卦</color>嗎？",
  ui_story_5075_50750500_25_dialog_content = "追本溯源，也和龍洲最受尊祟的<color=#FFB400>十三大祟靈</color>有些關係。",
  ui_story_5075_50750500_26_dialog_content = "不是動物嗎？",
  ui_story_5075_50750500_27_dialog_content = "動物、祟靈、神靈，不過是不同的具象形式。",
  ui_story_5075_50750500_28_dialog_content = "仲胥大人是不是也跟您說過，祟靈護佑一方，最終獲封成神的故事。",
  ui_story_5075_50750500_29_dialog_content = "這十三位祟靈，同時也是龍洲最特別的十三位神靈。",
  ui_story_5075_50750500_30_dialog_content = "包括您也知道的<color=#FFB400>「龍女鎮海」</color>那位<color=#FFB400>龍女</color>，也是其中一員。",
  ui_story_5075_50750500_31_dialog_content = "只是時移世易，如今不少人已經不記得自己拜祭的神也是祟靈了。",
  ui_story_5075_50750500_32_dialog_content = "扯遠了，回您剛才的問題。",
  ui_story_5075_50750500_33_dialog_content = "祟靈也掌握著種種能術，而那些大祟靈，或說「神靈」。",
  ui_story_5075_50750500_34_dialog_content = "所行手段尤為高妙，又稱為「神通」。",
  ui_story_5075_50750500_35_dialog_content = "傳說不論是行雲佈雨、起霧借風，亦或是隱身、變化，皆可隨心所動。",
  ui_story_5075_50750500_36_dialog_content = "令人羡慕啊。",
  ui_story_5075_50750500_37_dialog_content = "難道那個女孩也是……等等，我剛剛問了祟靈力量的問題嗎？",
  ui_story_5075_50750500_38_dialog_content = "當然問了~",
  ui_story_5075_50750500_39_dialog_content = "喔……這個神通是很厲害的光能術吧，不知道我能不能感應這種等級的力量。",
  ui_story_5075_50750500_40_dialog_content = "這恐怕就得您親自去問問<color=#FFB400>神</color>了。",
  ui_story_5075_50750500_41_dialog_content = "其實，雖然比不上神通……在下倒是有一條咒語您也能學。",
  ui_story_5075_50750500_42_dialog_content = "此乃龍洲上古傳誦至今，特別適合此時節用。",
  ui_story_5075_50750500_43_dialog_content = "來，跟著在下唸啊。",
  ui_story_5075_50750500_44_dialog_content = "<color=#FFB400>大——過——年——的！</color>",
  ui_story_5075_50750500_45_dialog_content = "大——過——年——的！",
  ui_story_5075_50750500_46_dialog_content = "哎對啦！這幾天您包準就能用上。",
  ui_story_5075_50750500_47_dialog_content = "甭管遇上什麼事，這條咒語一出，多大的干戈都能立刻化為玉帛。",
  ui_story_5075_50750500_48_dialog_content = "就這麼簡單的一句話，有這麼厲害嗎？",
  ui_story_5075_50750500_49_dialog_content = "上古咒語的威力，當然不可小覷。",
  ui_story_5075_50750500_50_dialog_content = "其實這套咒語共有四句，但另外幾句，您目前怕是還參不透其中深意。",
  ui_story_5075_50750500_51_dialog_content = "等將來有機會，在下再慢慢教您。",
  ui_story_5075_50750500_52_dialog_content = "好！太謝謝你了。",
  ui_story_5075_50750500_53_dialog_content = "客氣，舉手之勞罷了。",
  ui_story_5075_50750500_54_dialog_content = "至於您所煩惱的其他事嘛，在下雖然想給您算上一卦……",
  ui_story_5075_50750500_55_dialog_content = "久等了，PlayerName，我回來了。",
  ui_story_5075_50750500_56_dialog_content = "——但實在沒那個時間。",
  ui_story_5075_50750500_57_dialog_content = "竟然不算了？",
  ui_story_5075_50750500_58_dialog_content = "你們在說算什麼？",
  ui_story_5075_50750500_59_dialog_content = "喔對！我想起來羅松說自己是遊方道士，你也會占卜算命之類的事嗎？",
  ui_story_5075_50750500_60_dialog_content = "什麼？PlayerName，你可別讓人給騙了。",
  ui_story_5075_50750500_61_dialog_content = "什麼命數、緣分、因果啊，別聽他們說得神乎其神。",
  ui_story_5075_50750500_62_dialog_content = "但實際上就是些高明的話術加上戲法而已。",
  ui_story_5075_50750500_63_dialog_content = "咦？",
  ui_story_5075_50750500_64_dialog_content = "只要問心無愧，做了什麼事，自然能得到什麼果。",
  ui_story_5075_50750500_65_dialog_content = "再玄乎的卦籤都比不上這顆拳頭實在。",
  ui_story_5075_50750500_66_dialog_content = "（李天閑……）",
  ui_story_5075_50750500_67_dialog_content = "（別看在下，在下就一糖人師傅。）",
  ui_story_5075_50750500_68_dialog_content = "傻道士。",
  ui_story_5075_50750500_69_dialog_content = "一根筋。",
  ui_story_5075_50750500_70_dialog_content = "不懂不懂。",
  ui_story_5075_50750500_71_dialog_content = "麻煩麻煩。",
  ui_story_5075_50750500_72_dialog_content = "你們倆又胡說八道什麼呢，真是聽不懂啊，哈哈。",
  ui_story_5075_50750500_73_dialog_content = "……",
  ui_story_5075_50750500_74_dialog_content = "正好，您的糖人做好了。",
  ui_story_5075_50750500_75_dialog_content = "謝……這不是梅花嗎？！哪裡是糖人了？",
  ui_story_5075_50750500_76_dialog_content = "不好意思，在下的糖不太夠了。",
  ui_story_5075_50750500_77_dialog_content = "但您也別急，那詩裡頭不都這麼說了。",
  ui_story_5075_50750500_78_dialog_content = "美人兮美人，不知為暮雨兮為朝雲。相思一夜梅花發，忽到窗前疑是君。",
  ui_story_5075_50750500_79_dialog_content = "這<color=#FFB400>梅花</color>，怎麼就不能當個糖<color=#FFB400>美人</color>呢？",
  ui_story_5075_50750500_80_dialog_content = "絕對是在強詞奪理吧。",
  ui_story_5075_50750500_81_dialog_content = "人有時候也需解解風情嘛。",
  ui_story_5075_50750500_82_dialog_content = "好了，快去辦您的要事吧，在下就不送了。",
  ui_story_5075_50750500_83_dialog_content = "記著在下的話：要是遇見猶移不定之事，您不妨試著<color=#FFB400>拜拜神仙</color>。",
  ui_story_5075_50750500_84_dialog_content = "那邊廟會的戲台上，之後說是要跳《龍女鎮海》呢。",
  ui_story_5075_50750500_85_dialog_content = "戲台上的神又不是真神。",
  ui_story_5075_50750500_86_dialog_content = "嗯？那邊是……黑氣？！",
  ui_story_5075_50750500_87_dialog_content = "我過去看看！",
  ui_story_5075_50750500_88_dialog_content = "PlayerName等等，我也一起——",
  ui_story_5075_50750500_89_dialog_content = "麻煩的小子走了，這下可以算算接下來的事了。",
  ui_story_5075_50750500_90_dialog_content = "哎呀。",
  ui_story_5075_50750500_91_dialog_content = "看來這戲台上的神是不是真神，還真說不準呢。",
  ui_story_5075_50750601_1_dialog_content = "吱吱！",
  ui_story_5075_50750601_2_dialog_content = "安靜一點，別太引人注目。",
  ui_story_5075_50750601_3_dialog_content = "咦，牠醒了呀。",
  ui_story_5075_50750601_4_dialog_content = "越是接近廟會，牠的掙扎越厲害了……",
  ui_story_5075_50750601_5_dialog_content = "是因為接近你說的黑氣吧。",
  ui_story_5075_50750601_6_dialog_content = "依你所言，我猜那應該是一種有侵蝕性的力量。",
  ui_story_5075_50750601_7_dialog_content = "像毒一樣，會讓祟靈失去理智。",
  ui_story_5075_50750601_8_dialog_content = "可惜我沒有祛除這種力量的手段。",
  ui_story_5075_50750601_9_dialog_content = "野外那些同樣症狀的祟靈也沒法恢復，只能躲去沒人的地方。",
  ui_story_5075_50750601_10_dialog_content = "這隻小祟靈也是……",
  ui_story_5075_50750601_11_dialog_content = "你之前說有個女孩能夠抽走這種侵蝕力量，我們可以去找她嗎？",
  ui_story_5075_50750601_12_dialog_content = "其實我和她也是今天才認識的，我只知道她叫「阿霓」。",
  ui_story_5075_50750601_13_dialog_content = "似乎是個很厲害的祟靈。",
  ui_story_5075_50750601_14_dialog_content = "除此之外的線索，就是她弄丟的飾品了。",
  ui_story_5075_50750601_15_dialog_content = "這麼值錢的東西竟然能弄丟兩件……",
  ui_story_5075_50750601_16_dialog_content = "你是說類似腳環、手環的金製飾品嗎？",
  ui_story_5075_50750601_17_dialog_content = "你怎麼知道？",
  ui_story_5075_50750601_18_dialog_content = "因為我看見了。",
  ui_story_5075_50750601_19_dialog_content = "你也收到了？剛有個小鬼來我這買小籠包。",
  ui_story_5075_50750601_20_dialog_content = "只買了一顆包子，就付了我這個。",
  ui_story_5075_50750601_21_dialog_content = "這是金子吧？我剛想說這不能收，結果一抬頭她就不見人了。",
  ui_story_5075_50750601_22_dialog_content = "我這也是，不過我都沒見到人。",
  ui_story_5075_50750601_23_dialog_content = "只見這桌上的糖芋仔少了一碗，只留下這金子。",
  ui_story_5075_50750601_24_dialog_content = "你說，該不會是財神顯靈了吧？",
  ui_story_5075_50750601_25_dialog_content = "嗯……我想那位應該不是財神吧。",
  ui_story_5075_50750601_26_dialog_content = "重點是這個嗎？！",
  ui_story_5075_50750601_27_dialog_content = "你說用金片買桂花藕的小鬼啊？見過，應該是往裡面去了。",
  ui_story_5075_50750601_28_dialog_content = "兩位看看我這的年畫，每一張都做得頂頂細巧。",
  ui_story_5075_50750601_29_dialog_content = "用金子的小鬼？啊，記得記得。",
  ui_story_5075_50750601_30_dialog_content = "她很喜歡我這年畫呢，特別是《龍女鎮海》的主題，她拿了好幾張去。",
  ui_story_5075_50750601_31_dialog_content = "我記得她買完畫，就聽見戲台那邊不知道在喊些什麼。",
  ui_story_5075_50750601_32_dialog_content = "她過去看熱鬧了吧。",
  ui_story_5075_50750601_33_dialog_content = "她跟我分開前說有事要做，原來是逛廟會啊。",
  ui_story_5075_50750601_34_dialog_content = "而且逛得好仔細。",
  ui_story_5075_50750601_35_dialog_content = "還每一家都很好吃！",
  ui_story_5075_50750601_36_dialog_content = "這個「凍米糖」吃起來沒有艾斯特拉的點心那麼甜，反而更讓人想再吃一塊。",
  ui_story_5075_50750601_37_dialog_content = "確實，不愧是那位，從那麼多攤販裡選的桂花藕又甜又鮮，真是絕了！",
  ui_story_5075_50750601_38_dialog_content = "你也很喜歡吧，阿丁？",
  ui_story_5075_50750601_39_dialog_content = "嗷～",
  ui_story_5075_50750601_40_dialog_content = "說起來，我們本來是要做什麼來著？",
  ui_story_5075_50750601_41_dialog_content = "……",
  ui_story_5075_50750601_42_dialog_content = "……",
  ui_story_5075_50750601_43_dialog_content = "廟、廟會的氣氛真吸引人啊。",
  ui_story_5075_50750601_44_dialog_content = "是啊，哈哈……",
  ui_story_5075_50750601_45_dialog_content = "不過你有沒有注意到？",
  ui_story_5075_50750601_46_dialog_content = "我們帶來的小祟靈從剛才開始就不再掙扎，好像穩定下來了。",
  ui_story_5075_50750601_47_dialog_content = "讓我感應看看……",
  ui_story_5075_50750601_48_dialog_content = "周圍也沒有黑氣了！是消失了嗎？",
  ui_story_5075_50750601_49_dialog_content = "還有更壞的可能。",
  ui_story_5075_50750601_50_dialog_content = "或許黑氣開始在某處聚集起來了。希望能趕緊把人找到。",
  ui_story_5075_50750601_51_dialog_content = "啊！小PlayerName！",
  ui_story_5075_50750601_52_dialog_content = "阿霓，太好了，終於……",
  ui_story_5075_50750601_53_dialog_content = "太好了，你還帶了小朋友！",
  ui_story_5075_50750601_54_dialog_content = "來得正好！快上台！",
  ui_story_5075_50750601_55_dialog_content = "上什麼？",
  ui_story_5075_50750601_56_dialog_content = "你……您……對了，這隻祟靈——",
  ui_story_5075_50750601_57_dialog_content = "怎麼又一個？",
  ui_story_5075_50750601_58_dialog_content = "<color=#e8d9bb>就像之前見過的那樣，阿霓心不在焉地揮了揮手。</color>",
  ui_story_5075_50750601_59_dialog_content = "<color=#e8d9bb>祟靈體內的黑氣便被抽離、捏碎，彷彿從未存在過。</color>",
  ui_story_5075_50750601_60_dialog_content = "吱！",
  ui_story_5075_50750601_61_dialog_content = "<color=#e8d9bb>小祟靈輕快地跳到阿霓腳邊，像是表示感激般低下頭。</color>",
  ui_story_5075_50750601_62_dialog_content = "果然您是——",
  ui_story_5075_50750601_63_dialog_content = "到我們了，快來！",
  ui_story_5075_50750601_64_dialog_content = "下面好多觀眾！",
  ui_story_5075_50750601_65_dialog_content = "直接就被拉上來了，我們究竟要幹什麼呀？",
  ui_story_5075_50750601_66_dialog_content = "跳<color=#FFB400>《龍女鎮海》</color>呀。",
  ui_story_5075_50750601_67_dialog_content = "各位父老鄉親，大家好啊！我知道大家今個都是奔著「名角」來的。",
  ui_story_5075_50750601_68_dialog_content = "但想必大家也聽說了，龍女跳得最好的那位名角扭傷了腳，實在上不了台。",
  ui_story_5075_50750601_69_dialog_content = "廟會期間戲台可不能空著，所以我們臨時換了個新規矩。",
  ui_story_5075_50750601_70_dialog_content = "接下來會有幾名龍女輪番上台，分別為大家獻上自己的《龍女鎮海》。",
  ui_story_5075_50750601_71_dialog_content = "由各位自己選出今年春朔最好的「龍女」，怎麼樣？",
  ui_story_5075_50750601_72_dialog_content = "好！",
  ui_story_5075_50750601_73_dialog_content = "幸虧小PlayerName你帶了朋友來，不然人還湊不夠呢。",
  ui_story_5075_50750601_74_dialog_content = "你的小朋友就扮演在海裡搗亂，欺負人的黑龍。",
  ui_story_5075_50750601_75_dialog_content = "我是龍女。",
  ui_story_5075_50750601_76_dialog_content = "那我呢？",
  ui_story_5075_50750601_77_dialog_content = "小PlayerName，你可要做好準備，你的角色最重要啦。",
  ui_story_5075_50750601_78_dialog_content = "<size=50>你來扮演大海！</size>",
  ui_story_5075_50750601_79_dialog_content = "有這個必要嗎？？",
  ui_story_5075_50750601_80_dialog_content = "你在說什麼呀？大海多重要啊。",
  ui_story_5075_50750601_81_dialog_content = "音樂開始了，快跳吧。",
  ui_story_5075_50750601_82_dialog_content = "啊——啊——",
  ui_story_5075_50750601_83_dialog_content = "「天命龍女，降而生兆。」",
  ui_story_5075_50750601_84_dialog_content = "「萬里海闊，煙波浩渺。」",
  ui_story_5075_50750601_85_dialog_content = "（大海，快展示你的海闊和煙波呀！）",
  ui_story_5075_50750601_86_dialog_content = "（就算妳對我使眼色也沒用啊！總、總之先模仿一下波濤。）",
  ui_story_5075_50750601_87_dialog_content = "「天佑龍女……」",
  ui_story_5075_50750601_88_dialog_content = "……",
  ui_story_5075_50750601_89_dialog_content = "（這個……妳該不會忘詞了吧？！）",
  ui_story_5075_50750601_90_dialog_content = "「百祿多福」！後面是「百祿多福」！",
  ui_story_5075_50750601_91_dialog_content = "（不行，音樂已經過去了，但後面也不能指望阿霓有背……）",
  ui_story_5075_50750601_92_dialog_content = "「禍蛟降世，日月無光。」",
  ui_story_5075_50750601_93_dialog_content = "（羅松？！）",
  ui_story_5075_50750601_94_dialog_content = "「雷霆隆隆，電光爍爍。」",
  ui_story_5075_50750601_95_dialog_content = "（雖然動作很僵硬，台詞也明顯不對，但接下去了！幹得好！）",
  ui_story_5075_50750601_96_dialog_content = "（但為什麼你也不動了？）",
  ui_story_5075_50750601_97_dialog_content = "（上吧，雷霆和電光！）",
  ui_story_5075_50750601_98_dialog_content = "（這也要我來嗎？！）",
  ui_story_5075_50750601_99_dialog_content = "（總、總之先模仿雷霆。）",
  ui_story_5075_50750601_100_dialog_content = "轟隆隆隆——！",
  ui_story_5075_50750601_101_dialog_content = "「妖魔肆虐，蒼生何辜！」",
  ui_story_5075_50750601_102_dialog_content = "「幸有龍女，憐民除害。」",
  ui_story_5075_50750601_103_dialog_content = "「彼之力強，彼之志堅。」",
  ui_story_5075_50750601_104_dialog_content = "「唯以拳往，開闢四方！」",
  ui_story_5075_50750601_105_dialog_content = "（誰家的龍女是用拳頭啦！）",
  ui_story_5075_50750601_106_dialog_content = "（而且你是惡蛟，角色已經亂七八糟了！）",
  ui_story_5075_50750601_107_dialog_content = "嗷！",
  ui_story_5075_50750601_108_dialog_content = "（在這災難般的演出裡，為什麼唯獨暗鬼做得這麼逼真啊……）",
  ui_story_5075_50750601_109_dialog_content = "（不對！）",
  ui_story_5075_50750601_110_dialog_content = "這是真的暗鬼！",
  ui_story_5075_50750602_1_dialog_content = "感謝幾位帶來如此……",
  ui_story_5075_50750602_2_dialog_content = "獨樹一格……標新立異的……《龍女鎮海》。",
  ui_story_5075_50750602_3_dialog_content = "戲班主臉色好差，我們帶來的打擊這麼大嗎？",
  ui_story_5075_50750602_4_dialog_content = "我覺得半邊舞台被妖魔砸垮帶來的打擊更大。",
  ui_story_5075_50750602_5_dialog_content = "不是說龍洲的暗鬼幾乎不會出現在城裡嗎？",
  ui_story_5075_50750602_6_dialog_content = "又是狂化的祟靈，又是暗鬼，還有那莫名其妙的黑氣……",
  ui_story_5075_50750602_7_dialog_content = "皓津城究竟發生了什麼事？",
  ui_story_5075_50750602_8_dialog_content = "你們兩個怎麼都愁眉苦臉的？",
  ui_story_5075_50750602_9_dialog_content = "阿霓覺得我們演得很好啊，還收拾了妖魔。",
  ui_story_5075_50750602_10_dialog_content = "特別是小PlayerName的表演，阿霓很喜歡！",
  ui_story_5075_50750602_11_dialog_content = "那真的算得上表演嗎……",
  ui_story_5075_50750602_12_dialog_content = "而且後續的故事已經跟《龍女鎮海》沒有半點關係了吧。",
  ui_story_5075_50750602_13_dialog_content = "我以前聽過的故事就是這樣沒錯啊。",
  ui_story_5075_50750602_14_dialog_content = "八百年前，有黑蛟作惡，民不聊生。",
  ui_story_5075_50750602_15_dialog_content = "幸有龍女顯靈，立於海上，對著天邊惡蛟提氣揮拳。",
  ui_story_5075_50750602_16_dialog_content = "一拳便有千鈞之力。那惡蛟尚不及驚愕，便已讓拳風推出十幾好哩。",
  ui_story_5075_50750602_17_dialog_content = "不待其反應，龍女欺身壓上，數十拳連出，打得惡蛟面目全非！",
  ui_story_5075_50750602_18_dialog_content = "嗯嗯，後來呢後來呢？",
  ui_story_5075_50750602_19_dialog_content = "惡蛟只覺耳中嗡嗡作響，怒從心起，猛地——",
  ui_story_5075_50750602_20_dialog_content = "不，當時的情形您應該比我更清楚吧，畢竟……",
  ui_story_5075_50750602_21_dialog_content = "您才是善女龍王——辰霓大人本尊，對吧？",
  ui_story_5075_50750602_22_dialog_content = "等等。雖然聽了李天閑的話，我已經有阿霓是神的心理準備了……",
  ui_story_5075_50750602_23_dialog_content = "但眼前的阿霓……就是那個「龍女」？！",
  ui_story_5075_50750602_24_dialog_content = "那確也是吾之名號。",
  ui_story_5075_50750602_25_dialog_content = "拜見善女龍王大人！",
  ui_story_5075_50750602_26_dialog_content = "拜得好乾脆！",
  ui_story_5075_50750602_27_dialog_content = "這可是貨真價實的神仙菩薩，該拜自然就要拜。",
  ui_story_5075_50750602_28_dialog_content = "您在皓津現身，有什麼要事嗎？",
  ui_story_5075_50750602_29_dialog_content = "有人損毀鎮海封印，擾吾安眠，吾來討個交代。",
  ui_story_5075_50750602_30_dialog_content = "這、這不是大事不妙了嗎？！",
  ui_story_5075_50750602_31_dialog_content = "所以最近妖魔橫生，祟靈躁動，是因為惡蛟的封印破了？！",
  ui_story_5075_50750602_32_dialog_content = "原來黑蛟也真的存在啊。",
  ui_story_5075_50750602_33_dialog_content = "對，《龍女鎮海》雖然有各種版本，但畢竟描述的是真實的歷史。",
  ui_story_5075_50750602_34_dialog_content = "所以主要內容相去不遠。",
  ui_story_5075_50750602_35_dialog_content = "以惡蛟降世開始，以龍女親手將惡蛟封印至海底，還百姓安寧結束。",
  ui_story_5075_50750602_36_dialog_content = "但這個「阿霓鎮海」也是八百年前的事了吧？",
  ui_story_5075_50750602_37_dialog_content = "這麼久了，那隻黑蛟還活著嗎？",
  ui_story_5075_50750602_38_dialog_content = "黑龍之軀早已消亡，汝等無需擔憂此事。",
  ui_story_5075_50750602_39_dialog_content = "但當年之事，本非吾同族之罪。",
  ui_story_5075_50750602_40_dialog_content = "海中有一深窟，曾葬有大魔殘軀，其上怨力甚重。",
  ui_story_5075_50750602_41_dialog_content = "吾同族誤闖其中，遭怨力依附，才有鬧海一遭。",
  ui_story_5075_50750602_42_dialog_content = "今封印雖破，吾力仍存。怨力有所逸散，但若無軀體可借，則亦無禍世之能。",
  ui_story_5075_50750602_43_dialog_content = "便是借了新軀，也需先做融合，無法行動自如。",
  ui_story_5075_50750602_44_dialog_content = "（所以之前感應時一閃而過的，是曾經的「大魔」？）",
  ui_story_5075_50750602_45_dialog_content = "（感覺不太對……可惜沒看清楚。好在按照阿霓的說法，我們還有時間。）",
  ui_story_5075_50750602_46_dialog_content = "不管怎麼說，看來阿霓的目標和我們一致。",
  ui_story_5075_50750602_47_dialog_content = "身為暫時的同伴，我可以問個小問題嗎？",
  ui_story_5075_50750602_48_dialog_content = "允。",
  ui_story_5075_50750602_49_dialog_content = "我們第一次見面，應該是在龍女廟吧？",
  ui_story_5075_50750602_50_dialog_content = "但妳就是龍女本人，所以那時候妳是在……偷自己的供品嗎？",
  ui_story_5075_50750602_51_dialog_content = "……那才不叫偷。",
  ui_story_5075_50750602_52_dialog_content = "阿霓拿人家送給阿霓的東西，怎麼是偷啦。",
  ui_story_5075_50750602_53_dialog_content = "哈哈好，我說錯了，是拿，不是偷。",
  ui_story_5075_50750602_54_dialog_content = "果然還是看著這樣的阿霓比較習慣。",
  ui_story_5075_50750602_55_dialog_content = "對了，這兩條金飾，都是阿霓的吧？",
  ui_story_5075_50750602_56_dialog_content = "一條是我在龍女廟撿到的，一條是李天閑……糖人師傅撿到的，還給妳。",
  ui_story_5075_50750602_57_dialog_content = "那阿霓收回一條。",
  ui_story_5075_50750602_58_dialog_content = "那條既然是小PlayerName在我的廟中撿到，就是你的了。",
  ui_story_5075_50750602_59_dialog_content = "將來你若有所求，可以拿它向我許一個願望。",
  ui_story_5075_50750602_60_dialog_content = "願望嗎……",
  ui_story_5075_50750602_61_dialog_content = "幾位，打擾了。",
  ui_story_5075_50750602_62_dialog_content = "班主？剛才真是不好意思。",
  ui_story_5075_50750602_63_dialog_content = "哪有哪有，反倒是多虧了你們，除了舞台沒有別的損失。",
  ui_story_5075_50750602_64_dialog_content = "雖然比賽只能這樣了，沒法頒發獎品，但還是請拿上這個吧。",
  ui_story_5075_50750602_65_dialog_content = "是我自家做的點心，比不得外面的精緻。",
  ui_story_5075_50750602_66_dialog_content = "好歹祖上傳下來的祕方，別家沒有，幾位就拿去當嚐個新鮮吧。",
  ui_story_5075_50750602_67_dialog_content = "就是這個！",
  ui_story_5075_50750602_68_dialog_content = "阿霓就是聞到這個味道才去參賽的，原來竟然不是獎品啊。",
  ui_story_5075_50750602_69_dialog_content = "就為了這個點心？！",
  ui_story_5075_50750602_70_dialog_content = "啊呣。",
  ui_story_5075_50750602_71_dialog_content = "嗯，就是這個味道！班主你做的，跟你爺爺做的一模一樣呢！",
  ui_story_5075_50750602_72_dialog_content = "嘿嘿，這次廟會之行總算是圓滿成功了。",
  ui_story_5075_50750602_73_dialog_content = "我們走吧。",
  ui_story_5075_50750602_74_dialog_content = "跟我爺爺做的一模一樣……但他老人家已辭世多年，我家也沒賣過這點心。",
  ui_story_5075_50750602_75_dialog_content = "莫非是……！！！",
  ui_story_5075_50750602_76_dialog_content = "小PlayerName、小羅松、小阿丁，你們也吃吃看～",
  ui_story_5075_50750602_77_dialog_content = "這點心真的很好吃，可惜只有他家的人會做。",
  ui_story_5075_50750602_78_dialog_content = "嗷～",
  ui_story_5075_50750602_79_dialog_content = "多謝辰霓大人！",
  ui_story_5075_50750602_80_dialog_content = "小羅松也是一起玩過的夥伴，可以叫阿霓喔。",
  ui_story_5075_50750602_81_dialog_content = "好，那我就謹遵神意了！",
  ui_story_5075_50750602_82_dialog_content = "小PlayerName，你怎麼不吃呀？",
  ui_story_5075_50750602_83_dialog_content = "這樣好嗎？",
  ui_story_5075_50750602_84_dialog_content = "什麼？",
  ui_story_5075_50750602_85_dialog_content = "那個戲班主，是阿霓以前舊識的後代吧？",
  ui_story_5075_50750602_86_dialog_content = "不用和他再說些什麼嗎？",
  ui_story_5075_50750602_87_dialog_content = "嗯……",
  ui_story_5075_50750602_88_dialog_content = "阿霓是龍，是大祟靈，是百姓眼中的海神。我和普通人不同，能活很久很久。",
  ui_story_5075_50750602_89_dialog_content = "所以也能認識很多很多的人。",
  ui_story_5075_50750602_90_dialog_content = "那邊的戲班主，是以前一個常送點心給阿霓吃的人的孫子。",
  ui_story_5075_50750602_91_dialog_content = "東邊的那條街，以前曾跟阿霓一起划過船的人的孫女正要結婚。",
  ui_story_5075_50750602_92_dialog_content = "南邊河對岸的巷子裡，是鬥蟋蟀總能贏過阿霓的人的小侄子的葬禮。",
  ui_story_5075_50750602_93_dialog_content = "——那是他在世上最後的血親。",
  ui_story_5075_50750602_94_dialog_content = "大家都活得太短，所以做什麼都急匆匆的。",
  ui_story_5075_50750602_95_dialog_content = "還總要舉辦些儀式來證明一下。",
  ui_story_5075_50750602_96_dialog_content = "要是阿霓因為認識過一個人，就也要去認識他的後代的話……",
  ui_story_5075_50750602_97_dialog_content = "那阿霓就只能每天都奔波在不同的儀式上了。",
  ui_story_5075_50750602_98_dialog_content = "但這樣不會覺得寂寞嗎？",
  ui_story_5075_50750602_99_dialog_content = "因為長壽，一直只能做送別朋友的那一方。",
  ui_story_5075_50750602_100_dialog_content = "不會呀，這不是很好嘛。",
  ui_story_5075_50750602_101_dialog_content = "小PlayerName也該覺得幸運才對。",
  ui_story_5075_50750602_102_dialog_content = "因為你認識了能活很久很久的阿霓，而阿霓會記住你。",
  ui_story_5075_50750602_103_dialog_content = "哪怕你遭遇不測，阿霓的記憶裡也依然有你，會隨阿霓一起，長長久久。",
  ui_story_5075_50750602_104_dialog_content = "（我能夠明白阿霓話語的意思，卻始終無法真正理解。）",
  ui_story_5075_50750602_105_dialog_content = "（不管是她此刻臉上毫無陰霾的笑容，還是說出這些話時的心情。）",
  ui_story_5075_50750602_106_dialog_content = "（這一刻我才突然真正認知到——我們確實不同。）",
  ui_story_5075_50750701_1_dialog_content = "我、們、不、同。",
  ui_story_5075_50750701_2_dialog_content = "所、以。",
  ui_story_5075_50750701_3_dialog_content = "不、相、容。",
  ui_story_5075_50750701_4_dialog_content = "嘶……",
  ui_story_5075_50750701_5_dialog_content = "你沒事吧？要不要休息一下？",
  ui_story_5075_50750701_6_dialog_content = "這一路上你一直在感應那些黑氣，還撐得住嗎？",
  ui_story_5075_50750701_7_dialog_content = "當然了，我沒那麼脆弱。",
  ui_story_5075_50750701_8_dialog_content = "而且越是感應，越能發現這些黑氣本質上其實和暗能沒兩樣。",
  ui_story_5075_50750701_9_dialog_content = "只是多了感染和侵蝕的特性，所以用一般對付暗能的手段難以清除。",
  ui_story_5075_50750701_10_dialog_content = "如果這種特性是來自阿霓所說的怨力，那或許也能當作一種「意識」來看待。",
  ui_story_5075_50750701_11_dialog_content = "只要是「意識」，我就可以用感應力來干涉！",
  ui_story_5075_50750701_12_dialog_content = "試了幾次，我發現似乎真的能靠感應將那份侵蝕力隔絕開來。",
  ui_story_5075_50750701_13_dialog_content = "只要多練習幾次，說不定我也能幫上被侵蝕的祟靈了。",
  ui_story_5075_50750701_14_dialog_content = "其實都交給阿霓也沒問題呀。",
  ui_story_5075_50750701_15_dialog_content = "不行，既然我們現在是同伴，就沒道理讓妳一個人承擔責任。",
  ui_story_5075_50750701_16_dialog_content = "精細活都讓你們幹完了，那要是需要拳頭的時候，就儘管交給我吧！",
  ui_story_5075_50750701_17_dialog_content = "嗷——",
  ui_story_5075_50750701_18_dialog_content = "沒錯，還有阿丁！",
  ui_story_5075_50750701_19_dialog_content = "嗷！",
  ui_story_5075_50750701_20_dialog_content = "吱！",
  ui_story_5075_50750701_21_dialog_content = "這不是之前的那隻小祟靈嗎？怎麼也在這？",
  ui_story_5075_50750701_22_dialog_content = "阿丁，我不是叫你告訴牠去找你的同伴嗎？",
  ui_story_5075_50750701_23_dialog_content = "嗷……",
  ui_story_5075_50750701_24_dialog_content = "你說牠不聽啊。",
  ui_story_5075_50750701_25_dialog_content = "我在練習感應的時候也發現了，牠一直不遠不近地跟著我們。",
  ui_story_5075_50750701_26_dialog_content = "是不是被侵蝕過之後太害怕了，覺得跟著我們比較安全？",
  ui_story_5075_50750701_27_dialog_content = "但我們身邊反而危險吧，畢竟我們是要去……",
  ui_story_5075_50750701_28_dialog_content = "我是不是還沒問過我們現在要去哪？",
  ui_story_5075_50750701_29_dialog_content = "魚林街。",
  ui_story_5075_50750701_30_dialog_content = "討厭氣味的方向。",
  ui_story_5075_50750701_31_dialog_content = "咦？",
  ui_story_5075_50750701_32_dialog_content = "目標竟然不一樣嗎？！",
  ui_story_5075_50750701_33_dialog_content = "？",
  ui_story_5075_50750701_34_dialog_content = "不，如果真的不一樣，我們早該發現問題了。",
  ui_story_5075_50750701_35_dialog_content = "也沒什麼關係吧。",
  ui_story_5075_50750701_36_dialog_content = "反正小PlayerName的目的地已經到了。",
  ui_story_5075_50750701_37_dialog_content = "是我眼花了嗎？這些店鋪怎麼一間比一間還要貴氣。",
  ui_story_5075_50750701_38_dialog_content = "這就是魚林街……沒有廟會那邊熱鬧，但是真華麗啊。",
  ui_story_5075_50750701_39_dialog_content = "阿霓知道，這裡住的都是富人。",
  ui_story_5075_50750701_40_dialog_content = "<color=#e8d9bb>清澈的河道貫穿全街，兩畔皆是高樓危閣。雖是冬季，卻妝點得花團錦簇。</color>",
  ui_story_5075_50750701_41_dialog_content = "<color=#e8d9bb>樓間彩帶飛舞，風吹過，帶起一片銀鈴叮噹。</color>",
  ui_story_5075_50750701_42_dialog_content = "<color=#e8d9bb>翠袖三千樓上下，黃金百萬水西東。</color>",
  ui_story_5075_50750701_43_dialog_content = "街道旁邊那座雕像是什麼？",
  ui_story_5075_50750701_44_dialog_content = "一群魚簇擁著一艘船，而且這艘船和這些魚的尾巴都有點眼熟……",
  ui_story_5075_50750701_45_dialog_content = "好像在哪裡見過？",
  ui_story_5075_50750701_46_dialog_content = "是螭龍魚，牠們很能游呢，總是一群群地來來回回。",
  ui_story_5075_50750701_47_dialog_content = "但不管在海裡游了多遠，牠們到了冬天都會回到龍洲近海產卵。",
  ui_story_5075_50750701_48_dialog_content = "所以也有不少人拜託牠們幫忙引導航船。",
  ui_story_5075_50750701_49_dialog_content = "拜託魚？",
  ui_story_5075_50750701_50_dialog_content = "是呀，人有做不了的事就可以送些禮物，拜託動物或祟靈幫忙。",
  ui_story_5075_50750701_51_dialog_content = "自古以來不就是這樣？",
  ui_story_5075_50750701_52_dialog_content = "至少現在看起來不太像……",
  ui_story_5075_50750701_53_dialog_content = "這座雕像應該有些年頭了，上面還有不少髒污跟刮痕，顯然很久沒保養過。",
  ui_story_5075_50750701_54_dialog_content = "就算曾經有過友好的關係，現在恐怕也……",
  ui_story_5075_50750701_55_dialog_content = "結束了。",
  ui_story_5075_50750701_56_dialog_content = "月白！妳已經回皓津了啊？",
  ui_story_5075_50750701_57_dialog_content = "幾天前就回來了，只是林家又出了些事，沒空去看你。",
  ui_story_5075_50750701_58_dialog_content = "但這不是碰見了嘛。",
  ui_story_5075_50750701_59_dialog_content = "林家又遇上什麼麻煩了嗎？",
  ui_story_5075_50750701_60_dialog_content = "不能說是麻煩。",
  ui_story_5075_50750701_61_dialog_content = "是錯誤。",
  ui_story_5075_50750701_62_dialog_content = "林家犯下了有關螭龍魚的錯誤。",
  ui_story_5075_50750701_63_dialog_content = "和妳剛剛說的「結束了」有關？",
  ui_story_5075_50750701_64_dialog_content = "嗯。",
  ui_story_5075_50750701_65_dialog_content = "請您不要摸我的尾巴。",
  ui_story_5075_50750701_66_dialog_content = "我、我沒有啊！",
  ui_story_5075_50750701_67_dialog_content = "不是說PlayerName。",
  ui_story_5075_50750701_68_dialog_content = "哎呀，被發現啦。",
  ui_story_5075_50750701_69_dialog_content = "阿霓難得見到有螭龍魚血統的光靈，一時手癢。",
  ui_story_5075_50750701_70_dialog_content = "按照螭龍魚是龍的遠親算起來，我們其實還有些親戚關係呢。",
  ui_story_5075_50750701_71_dialog_content = "那是我高攀您了。",
  ui_story_5075_50750701_72_dialog_content = "難怪我看這條魚很眼熟，原來是因為月白啊。",
  ui_story_5075_50750701_73_dialog_content = "而且仔細一看，這艘船也好像蜃風號！",
  ui_story_5075_50750701_74_dialog_content = "那是蜃風號的雛形。",
  ui_story_5075_50750701_75_dialog_content = "也是多年前林家第一艘跨越大海，成功抵達艾斯特拉大陸的商船。",
  ui_story_5075_50750701_76_dialog_content = "原來如此，不過為什麼林家商船的雕塑會在這裡？",
  ui_story_5075_50750701_77_dialog_content = "你們不知道嗎？",
  ui_story_5075_50750701_78_dialog_content = "這條商街，以前是林家的。",
  ui_story_5075_50750701_79_dialog_content = "一、一整條街？！",
  ui_story_5075_50750701_80_dialog_content = "只是近年因為一些交易和抵押，以及前陣子林家的變故，街道被拆分了。",
  ui_story_5075_50750701_81_dialog_content = "現在還在林家名下的，只剩下一半。",
  ui_story_5075_50750701_82_dialog_content = "且這一半的最終歸屬，也要看事情的走向。",
  ui_story_5075_50750701_83_dialog_content = "還剩一半也很不得了了啊。",
  ui_story_5075_50750701_84_dialog_content = "吱——！",
  ui_story_5075_50750701_85_dialog_content = "嗚哇。",
  ui_story_5075_50750701_86_dialog_content = "<color=#e8d9bb>被突然撞過來的小祟靈撲倒，一道漆黑的暗能正中腳邊地面。</color>",
  ui_story_5075_50750701_87_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5075_50750701_88_dialog_content = "PlayerName！你沒事吧！",
  ui_story_5075_50750701_89_dialog_content = "嗯，被那隻小祟靈救了。",
  ui_story_5075_50750701_90_dialog_content = "吱……",
  ui_story_5075_50750701_91_dialog_content = "牠怎麼了？好像突然很難受。",
  ui_story_5075_50750701_92_dialog_content = "……牠的身體什麼時候又感染了黑氣！",
  ui_story_5075_50750701_93_dialog_content = "阿丁？！",
  ui_story_5075_50750701_94_dialog_content = "嗷……",
  ui_story_5075_50750701_95_dialog_content = "<color=#e8d9bb>阿丁發出痛苦的低吼，周身本來穩定的光能開始紊亂。</color>",
  ui_story_5075_50750701_96_dialog_content = "這個症狀，難道是……",
  ui_story_5075_50750701_97_dialog_content = "強制感應！",
  ui_story_5075_50750701_98_dialog_content = "我暫時隔絕了那股力量對牠們的侵蝕，但得快點找到源頭才行。",
  ui_story_5075_50750701_99_dialog_content = "周圍突然出現的大片黑氣，究竟是從哪裡來的……",
  ui_story_5075_50750701_100_dialog_content = "阿霓要找的是破壞封印之人，不是你。冷靜點，別被牽著鼻子走。",
  ui_story_5075_50750701_101_dialog_content = "阿霓？妳在和誰說話？",
  ui_story_5075_50750701_102_dialog_content = "魚。",
  ui_story_5075_50750701_103_dialog_content = "魚……是那座雕像？",
  ui_story_5075_50750701_104_dialog_content = "感應！",
  ui_story_5075_50750701_105_dialog_content = "這裡是……海底？",
  ui_story_5075_50750701_106_dialog_content = "誰、在。",
  ui_story_5075_50750701_107_dialog_content = "你有螭龍魚的尾巴？",
  ui_story_5075_50750701_108_dialog_content = "是和林家有關的人嗎？",
  ui_story_5075_50750701_109_dialog_content = "林、家。",
  ui_story_5075_50750701_110_dialog_content = "卑、鄙。",
  ui_story_5075_50750701_111_dialog_content = "可、恨！",
  ui_story_5075_50750701_112_dialog_content = "！",
  ui_story_5075_50750701_113_dialog_content = "痛……",
  ui_story_5075_50750701_114_dialog_content = "PlayerName，振作。",
  ui_story_5075_50750701_115_dialog_content = "沒事，只是感應到的地方，黑氣的侵蝕力比之前見過的還要強。",
  ui_story_5075_50750701_116_dialog_content = "我還看見了一個人，他好像……和林家有關係。",
  ui_story_5075_50750701_117_dialog_content = "是尤。",
  ui_story_5075_50750701_118_dialog_content = "月白，妳知道？",
  ui_story_5075_50750701_119_dialog_content = "那是曾經和林家合作過的祟靈。",
  ui_story_5075_50750701_120_dialog_content = "不久前，家主曾經拜託牠去海邊探查妖魔異動的原因，但之後就沒再回來。",
  ui_story_5075_50750701_121_dialog_content = "……軀體，他成了阿霓所說的軀體！看來最壞的事情發生了。",
  ui_story_5075_50750701_122_dialog_content = "封印下的力量，找到新的依附了。",
  ui_story_5075_50750701_123_dialog_content = "吱！",
  ui_story_5075_50750701_124_dialog_content = "<color=#e8d9bb>小祟靈突然竄出，狠狠咬住角落裡一位陌生人的手腕。</color>",
  ui_story_5075_50750701_125_dialog_content = "嗚呃……該死的畜生！",
  ui_story_5075_50750701_126_dialog_content = "給我滾！",
  ui_story_5075_50750701_127_dialog_content = "<color=#e8d9bb>小祟靈被他用力甩飛，在地面上滑得老遠，不動了。</color>",
  ui_story_5075_50750701_128_dialog_content = "小傢伙！",
  ui_story_5075_50750701_129_dialog_content = "呵。",
  ui_story_5075_50750701_130_dialog_content = "這個人……這個人身上也有黑氣！他懷裡拿著什麼？",
  ui_story_5075_50750701_131_dialog_content = "你是什麼人！",
  ui_story_5075_50750701_132_dialog_content = "你們沒必要知道。",
  ui_story_5075_50750701_133_dialog_content = "糟糕，快攔住他！",
  ui_story_5075_50750701_134_dialog_content = "來不及了！",
  ui_story_5075_50750701_135_dialog_content = "<color=#e8d9bb>陌生人將懷裡的東西狠狠摔碎，釋放出大量黑氣。</color>",
  ui_story_5075_50750701_136_dialog_content = "（和剛剛在海裡感應到的力量一樣……！）",
  ui_story_5075_50750701_137_dialog_content = "<color=#e8d9bb>這一次，不必使用感應力也能看見。</color>",
  ui_story_5075_50750701_138_dialog_content = "<color=#e8d9bb>這一次，不必使用感應力也能看見。</color>",
  ui_story_5075_50750701_139_dialog_content = "<color=#e8d9bb>無窮無盡的黑氣挾著幽深的暗能，如同沸水般瘋狂翻湧起來。</color>",
  ui_story_5075_50750701_140_dialog_content = "<color=#e8d9bb>所有不安定的能量聚為一體，最後……</color>",
  ui_story_5075_50750701_141_dialog_content = "<color=#e8d9bb>猛然爆開！</color>",
  ui_story_5075_50750701_142_dialog_content = "休得放肆！",
  ui_story_5075_50750701_143_dialog_content = "<color=#e8d9bb>轟——</color>",
  ui_story_5075_50750701_144_dialog_content = "<color=#e8d9bb>一道燦金的身影裹挾著天雷竄出，擋下爆破形成的黑浪，但餘氣依然流散。</color>",
  ui_story_5075_50750701_145_dialog_content = "哼……就是你們這些人破壞了封印？給我回來服罪！",
  ui_story_5075_50750701_146_dialog_content = "咳咳……",
  ui_story_5075_50750701_147_dialog_content = "怎麼回事？阿霓呢？",
  ui_story_5075_50750701_148_dialog_content = "跟黑氣撞上之後，就追著剛才那人跑了。",
  ui_story_5075_50750701_149_dialog_content = "太衝動了！",
  ui_story_5075_50750701_150_dialog_content = "好在應該也沒人傷得了她。",
  ui_story_5075_50750701_151_dialog_content = "我們這裡呢？看起來應該沒人受傷？",
  ui_story_5075_50750701_152_dialog_content = "只是傷的不是人而已……阿丁！小傢伙！",
  ui_story_5075_50750701_153_dialog_content = "嗷……",
  ui_story_5075_50750701_154_dialog_content = "剛才的爆炸讓黑氣四散，牠們受到的侵蝕也加深了。",
  ui_story_5075_50750701_155_dialog_content = "不只如此，暗鬼也會被吸引過來。",
  ui_story_5075_50750701_156_dialog_content = "準備戰鬥！",
  ui_story_5075_50750701_157_dialog_content = "嘎！",
  ui_story_5075_50750702_1_dialog_content = "林家的祖興之地，豈能容得妖魔撒野？",
  ui_story_5075_50750702_2_dialog_content = "嘎——",
  ui_story_5075_50750702_3_dialog_content = "還好有月白開路，集中在這裡的暗鬼總算都解決了。",
  ui_story_5075_50750702_4_dialog_content = "但剛才那些黑霧都散進城內了，感覺會出大事。",
  ui_story_5075_50750702_5_dialog_content = "有沒有什麼辦法……",
  ui_story_5075_50750702_6_dialog_content = "有。",
  ui_story_5075_50750702_7_dialog_content = "即便狀況遠不及當年，林家在皓津也依然有些底牌。",
  ui_story_5075_50750702_8_dialog_content = "我會負責把各位安全送至林家大宅。",
  ui_story_5075_50750702_9_dialog_content = "並稟明家主，調用我們在城內的資源協助處理此事。",
  ui_story_5075_50750702_10_dialog_content = "好啊！可月白不問前因後果就願意這麼幫我們嗎？",
  ui_story_5075_50750702_11_dialog_content = "此事原就和林家有關……",
  ui_story_5075_50750702_12_dialog_content = "且幫你也本不需過問。",
  ui_story_5075_50750702_13_dialog_content = "PlayerName，慢著。",
  ui_story_5075_50750702_14_dialog_content = "羅松？怎麼了？",
  ui_story_5075_50750702_15_dialog_content = "這隻小祟靈能先拜託你嗎？",
  ui_story_5075_50750702_16_dialog_content = "當然，差點忘了，阿丁也過來吧。",
  ui_story_5075_50750702_17_dialog_content = "阿霓還沒回來，我先試著替你們隔絕黑氣的侵蝕。",
  ui_story_5075_50750702_18_dialog_content = "嗷……",
  ui_story_5075_50750702_19_dialog_content = "阿丁？",
  ui_story_5075_50750702_20_dialog_content = "我們就不跟著你去了。",
  ui_story_5075_50750702_21_dialog_content = "怎麼羅松你也？",
  ui_story_5075_50750702_22_dialog_content = "那些黑氣在皓津擴散，一定會有其他祟靈受到感染。",
  ui_story_5075_50750702_23_dialog_content = "牠們不壞，只是因為出身山野，有時候會本能照野獸的習慣行事而已。",
  ui_story_5075_50750702_24_dialog_content = "現在百姓對祟靈的態度越來越偏激。",
  ui_story_5075_50750702_25_dialog_content = "要是再有祟靈因被感染而狂暴傷人，恐怕人和祟靈的關係就再沒法修復了。",
  ui_story_5075_50750702_26_dialog_content = "所以趁事情有轉機，我要去把那些受感染的祟靈都抓出來。",
  ui_story_5075_50750702_27_dialog_content = "有些祟靈確實和人有過節。",
  ui_story_5075_50750702_28_dialog_content = "但沒人有資格用這種方式強行決定牠們的立場。",
  ui_story_5075_50750702_29_dialog_content = "對吧，阿丁？",
  ui_story_5075_50750702_30_dialog_content = "你做了錯事我會揍你，你做了好事我也會稱讚你。",
  ui_story_5075_50750702_31_dialog_content = "但要做什麼，永遠只能你自己決定。",
  ui_story_5075_50750702_32_dialog_content = "你要和我一起去嗎？",
  ui_story_5075_50750702_33_dialog_content = "<color=#e8d9bb>羅松俯下身注視著阿丁。</color>",
  ui_story_5075_50750702_34_dialog_content = "<color=#e8d9bb>本來伏在地面上的阿丁撐著身體，搖搖晃晃地站了起來。</color>",
  ui_story_5075_50750702_35_dialog_content = "嗷！",
  ui_story_5075_50750702_36_dialog_content = "不愧是我的好搭檔。",
  ui_story_5075_50750702_37_dialog_content = "但阿丁現在的狀態……",
  ui_story_5075_50750702_38_dialog_content = "要是阿霓……龍女大人在就好了。",
  ui_story_5075_50750702_39_dialog_content = "哎，你的想望也太奢侈了。",
  ui_story_5075_50750702_40_dialog_content = "求神仙這種事，怎麼能篤定神仙一定會顯靈？",
  ui_story_5075_50750702_41_dialog_content = "就是自己的阿兄阿娘，你要什麼都求他們幫忙還得挨罵呢，更別說神仙。",
  ui_story_5075_50750702_42_dialog_content = "嗯，也是。",
  ui_story_5075_50750702_43_dialog_content = "說到底，給神仙燒香祭祀，大多是人一廂情願。",
  ui_story_5075_50750702_44_dialog_content = "神仙也有幫你和不幫你的自由。",
  ui_story_5075_50750702_45_dialog_content = "人活於世，還是自己的拳頭最靠得住！",
  ui_story_5075_50750702_46_dialog_content = "不管前路萬難，拳有力，便可破。",
  ui_story_5075_50750702_47_dialog_content = "嗷嗷！",
  ui_story_5075_50750702_48_dialog_content = "走吧。",
  ui_story_5075_50750702_49_dialog_content = "祝你們行動順利。",
  ui_story_5075_50750702_50_dialog_content = "我們也走吧。",
  ui_story_5075_50750702_51_dialog_content = "我帶你回林家宅邸。",
  ui_story_5075_50750801_1_dialog_content = "<color=#e8d9bb>濟國王宮</color>",
  ui_story_5075_50750801_2_dialog_content = "大王，鄴國又有消息傳來。",
  ui_story_5075_50750801_3_dialog_content = "之前向鄴國訂購的<color=#FFB400>岸防砲</color>到了？",
  ui_story_5075_50750801_4_dialog_content = "不……是……",
  ui_story_5075_50750801_5_dialog_content = "不是？上次同意漲價後不是開始押送了嗎？",
  ui_story_5075_50750801_6_dialog_content = "鄴國的傳信確實是這麼說。",
  ui_story_5075_50750801_7_dialog_content = "但至今已過去半月，貨物卻遲遲未到，我們發信催促，那邊卻……",
  ui_story_5075_50750801_8_dialog_content = "讓本王猜猜，他們又要漲價？",
  ui_story_5075_50750801_9_dialog_content = "……是。",
  ui_story_5075_50750801_10_dialog_content = "信上說送貨的隊伍在山中失聯。",
  ui_story_5075_50750801_11_dialog_content = "因為是濟國急需之物，可以有限調撥人手幫我們搜尋。",
  ui_story_5075_50750801_12_dialog_content = "但需要我們承擔搜尋所需的費用。",
  ui_story_5075_50750801_13_dialog_content = "當然，也可以用五年前鄴國向濟國借貸的款項作抵。",
  ui_story_5075_50750801_14_dialog_content = "所以下官猜測，這理由不過是就地起價的幌子。",
  ui_story_5075_50750801_15_dialog_content = "若我們不答應付款，這批岸防砲便會一直在搜。",
  ui_story_5075_50750801_16_dialog_content = "恐怕……永遠搜不到。",
  ui_story_5075_50750801_17_dialog_content = "荒唐！",
  ui_story_5075_50750801_18_dialog_content = "此前妖魔剛有異動時我們就下了訂單，結果卻被一拖再拖。",
  ui_story_5075_50750801_19_dialog_content = "此次是隊伍失蹤，下次岸防砲是不是就會憑空消失了？",
  ui_story_5075_50750801_20_dialog_content = "回信告訴他們，再想趁火打劫，兩國的一切交易全數取消！",
  ui_story_5075_50750801_21_dialog_content = "但是大王，最近四處的妖魔都越發猖獗。",
  ui_story_5075_50750801_22_dialog_content = "特別是沿海一帶，各地都希望宮中來援。",
  ui_story_5075_50750801_23_dialog_content = "鄴國的岸防砲再不到，防線怕是難守啊。",
  ui_story_5075_50750801_24_dialog_content = "難守？",
  ui_story_5075_50750801_25_dialog_content = "龍洲只剩鄴國了不成？",
  ui_story_5075_50750801_26_dialog_content = "我濟國民物豐阜，商販駢集，每日所賺金銀多不勝數。",
  ui_story_5075_50750801_27_dialog_content = "海運不便，還有河運；鄴國不肯交易，那就去找其他人。",
  ui_story_5075_50750801_28_dialog_content = "錢生百物，只要出得起價，便是央京雄師都能為我所用！",
  ui_story_5075_50750801_29_dialog_content = "那鄴國的要求……？",
  ui_story_5075_50750801_30_dialog_content = "一律不應。",
  ui_story_5075_50750801_31_dialog_content = "是。",
  ui_story_5075_50750801_32_dialog_content = "呵，如今就連鄴國都敢如此戲耍本王了。",
  ui_story_5075_50750801_33_dialog_content = "怕是早忘了當年向濟國借貸時的窘迫。",
  ui_story_5075_50750801_34_dialog_content = "說來，灼華也是那年來到濟國的。",
  ui_story_5075_50750801_35_dialog_content = "國師怎麼看？灼華要是真當了本王的兒媳，這筆錢倒也不是不能商量。",
  ui_story_5075_50750801_36_dialog_content = "大王，君無戲言，灼華是有志之女，此事不可玩笑。",
  ui_story_5075_50750801_37_dialog_content = "哼，本王也知道。",
  ui_story_5075_50750801_38_dialog_content = "只是難得有這麼一個能管得住世子的人……",
  ui_story_5075_50750801_39_dialog_content = "這些不過兒女小事，如今風雲動盪，大王可想過對策？",
  ui_story_5075_50750801_40_dialog_content = "濟國多年來只重商賈，糧草機關等物皆仰賴與他國交易。",
  ui_story_5075_50750801_41_dialog_content = "若是再有如今日鄴國之事……",
  ui_story_5075_50750801_42_dialog_content = "濟國數百年來皆以商為本，國師所言對策可非易事。",
  ui_story_5075_50750801_43_dialog_content = "且妖魔之患，未必長久。",
  ui_story_5075_50750801_44_dialog_content = "還是之後再議吧。",
  ui_story_5075_50750801_45_dialog_content = "本王累了，先回去休息了。",
  ui_story_5075_50750801_46_dialog_content = "……是。",
  ui_story_5075_50750801_47_dialog_content = "老師？您在這裡呀。",
  ui_story_5075_50750801_48_dialog_content = "聽說城外海灣的妖魔力量再度增強，祟靈之事也還未查明原因。",
  ui_story_5075_50750801_49_dialog_content = "而且那日宮中一別，我就再沒收到PlayerName公子的消息了！",
  ui_story_5075_50750801_50_dialog_content = "老師可知道什麼？",
  ui_story_5075_50750801_51_dialog_content = "放心，那位少年安全無虞，交給他的差事也在順利進行。",
  ui_story_5075_50750801_52_dialog_content = "但恐怕妳想問的不只如此吧？",
  ui_story_5075_50750801_53_dialog_content = "左右老師都看得出來，那我就不拐彎抹角了。",
  ui_story_5075_50750801_54_dialog_content = "您之前要PlayerName公子隱密行動，不要告知朝中之人。",
  ui_story_5075_50750801_55_dialog_content = "是因為您懷疑朝中有人居心不良嗎？",
  ui_story_5075_50750801_56_dialog_content = "這個問題與其問老夫，不如去問問妳那侍衛。",
  ui_story_5075_50750801_57_dialog_content = "<color=#FFB400>阿玖</color>？她最近在……",
  ui_story_5075_50750801_58_dialog_content = "不必告訴老夫。老夫這把年紀了，看不懂妳們小姑娘的玩意。",
  ui_story_5075_50750801_59_dialog_content = "妳們自己看。",
  ui_story_5075_50750801_60_dialog_content = "……我明白了，多謝老師指點。",
  ui_story_5075_50750801_61_dialog_content = "喔，還有一事，老夫要先向妳致歉。",
  ui_story_5075_50750801_62_dialog_content = "等之後妳再見到少年，也望替老夫傳達一下歉意。",
  ui_story_5075_50750801_63_dialog_content = "此前，老夫藉妳的名義遞了件東西給少年。",
  ui_story_5075_50750801_64_dialog_content = "希望能順利派上用場。",
  ui_story_5075_50750801_65_dialog_content = "（老師果然是在防備朝中之人。）",
  ui_story_5075_50750801_66_dialog_content = "（但究竟是什麼人，能讓國師都如此謹慎？）",
  ui_story_5075_50750801_67_dialog_content = "（如果和阿玖最近在調查的事情有關……）",
  ui_story_5075_50750801_68_dialog_content = "（說來，城內有可疑的暗探行動，為何宮中沒有任何消息？）",
  ui_story_5075_50750801_69_dialog_content = "（只有阿玖發現嗎？還是說……有人故意叫阿玖發現？）",
  ui_story_5075_50750801_70_dialog_content = "（但阿玖只是個質子郡主的侍衛，她也只會為了我行動。）",
  ui_story_5075_50750801_71_dialog_content = "（就算朝中有居心叵測之人，也沒必要做這些事，除非……）",
  ui_story_5075_50750801_72_dialog_content = "（背後之人的立場，不是濟國，而是……）",
  ui_story_5075_50750801_73_dialog_content = "嗶嗶。",
  ui_story_5075_50750801_74_dialog_content = "<color=#FFB400>璇璣卿</color>的傳信鳥？",
  ui_story_5075_50750801_75_dialog_content = "明明之前還說什麼性能不足，躲不開護衛，不肯替我傳信。",
  ui_story_5075_50750801_76_dialog_content = "果然又是在唬我。",
  ui_story_5075_50750801_77_dialog_content = "……",
  ui_story_5075_50750801_78_dialog_content = "這個璇極，真是膽大包天！",
  ui_story_5075_50750801_79_dialog_content = "我得出宮。",
  ui_story_5075_50750801_80_dialog_content = "國師大人，按照您的吩咐，已經撤了周圍的守衛。",
  ui_story_5075_50750801_81_dialog_content = "灼華郡主也已收到信了。",
  ui_story_5075_50750801_82_dialog_content = "那便好。",
  ui_story_5075_50750902_1_dialog_content = "到了，這就是林家在魚林街的宅邸。",
  ui_story_5075_50750902_2_dialog_content = "咦？這個地方，不就是紙條上標註的地址嗎？",
  ui_story_5075_50750902_3_dialog_content = "紙條？",
  ui_story_5075_50750902_4_dialog_content = "我來之前收到過一個宮裡的食盒，裡面地圖上標註的地址就是這裡。",
  ui_story_5075_50750902_5_dialog_content = "還放著一塊不知道有什麼用的令牌。",
  ui_story_5075_50750902_6_dialog_content = "這是……「巡檢司」的令牌。",
  ui_story_5075_50750902_7_dialog_content = "小郎君，你可知濟國除水師之外，在陸上並沒有常備軍隊？",
  ui_story_5075_50750902_8_dialog_content = "扼要道、察奸偽、除妖魔，皆由巡檢司負責。",
  ui_story_5075_50750902_9_dialog_content = "而你手中這塊令牌，可以調動巡檢司的隊伍。",
  ui_story_5075_50750902_10_dialog_content = "且不論王宮禁衛，你手中握著的，該是皓津最強的力量。",
  ui_story_5075_50750902_11_dialog_content = "我居然帶著這麼重要的東西跑來跑去？！",
  ui_story_5075_50750902_12_dialog_content = "咦？您是……",
  ui_story_5075_50750902_13_dialog_content = "家主，您怎麼出來了？",
  ui_story_5075_50750902_14_dialog_content = "我聽見外面有些異動，出來看看情況。",
  ui_story_5075_50750902_15_dialog_content = "沒想到妳接了客人來。",
  ui_story_5075_50750902_16_dialog_content = "這位小郎君，想必就是PlayerName了。",
  ui_story_5075_50750902_17_dialog_content = "總聽仲兄、厘青、月白他們提及你的名字，我倒是今日才有緣得見。",
  ui_story_5075_50750902_18_dialog_content = "不過現在不是寒暄的時候。",
  ui_story_5075_50750902_19_dialog_content = "請問小郎君，你看到我時，為什麼這麼驚訝？",
  ui_story_5075_50750902_20_dialog_content = "啊，抱歉。但我好像見過您。",
  ui_story_5075_50750902_21_dialog_content = "就在海底那位……好像在操縱那些黑氣的祟靈記憶裡。",
  ui_story_5075_50750902_22_dialog_content = "是「尤」嗎。",
  ui_story_5075_50750902_23_dialog_content = "應該沒錯。",
  ui_story_5075_50750902_24_dialog_content = "家主也知道他，而他恨著林家。你們之間究竟有什麼過節？",
  ui_story_5075_50750902_25_dialog_content = "這就是個很長的故事了。",
  ui_story_5075_50750902_26_dialog_content = "進去說吧。",
  ui_story_5075_50750902_27_dialog_content = "我還有些事情要處理，月白妳先招待一下客人。",
  ui_story_5075_50750902_28_dialog_content = "好。",
  ui_story_5075_50750902_29_dialog_content = "要喝茶嗎？",
  ui_story_5075_50750902_30_dialog_content = "啊，不用麻煩了。",
  ui_story_5075_50750902_31_dialog_content = "懂了，那便不喝。",
  ui_story_5075_50750902_32_dialog_content = "哈哈……差點忘了月白是這種個性。",
  ui_story_5075_50750902_33_dialog_content = "？",
  ui_story_5075_50750902_34_dialog_content = "不，沒什麼，現在也確實不需要那些客套的虛禮。",
  ui_story_5075_50750902_35_dialog_content = "說正事吧——尤和林家，究竟是怎麼回事？",
  ui_story_5075_50750902_36_dialog_content = "嗯，關於林家和祟靈的事，能追溯到很久以前。",
  ui_story_5075_50750902_37_dialog_content = "那時林家只是間小商會，還因經營不善連年虧損，幾近歇業。",
  ui_story_5075_50750902_38_dialog_content = "先祖為了自救，用僅存的資產換了一艘商船，試圖在海外找到一線生機。",
  ui_story_5075_50750902_39_dialog_content = "他也確實成功了。",
  ui_story_5075_50750902_40_dialog_content = "這就是林家前往艾斯特拉行商的起始。",
  ui_story_5075_50750902_41_dialog_content = "我聽卡蓮說過這段故事，雙榭城也是從那時開始繁榮起來的。",
  ui_story_5075_50750902_42_dialog_content = "那我就不贅述其他了。",
  ui_story_5075_50750902_43_dialog_content = "故事的重點，是先祖返航時迷失方向，誤入海中死域。",
  ui_story_5075_50750902_44_dialog_content = "那時林家還沒有渾儀，也無璇極那般可力挽狂瀾的機巧師隨行。",
  ui_story_5075_50750902_45_dialog_content = "先祖在迷霧中飄蕩半月，幾近彈盡糧絕。",
  ui_story_5075_50750902_46_dialog_content = "就在這時，他遇上了螭龍魚群。",
  ui_story_5075_50750902_47_dialog_content = "我聽阿霓說過，螭龍魚每年冬季都會成群回到龍洲產卵。",
  ui_story_5075_50750902_48_dialog_content = "所以螭龍魚救了這位先祖？",
  ui_story_5075_50750902_49_dialog_content = "正是。",
  ui_story_5075_50750902_50_dialog_content = "跟隨著被視為吉兆的螭龍魚，先祖終於逃離死域，成功返鄉。",
  ui_story_5075_50750902_51_dialog_content = "之後，他每次前往艾斯特拉，都會特別選在冬季歸航。",
  ui_story_5075_50750902_52_dialog_content = "林家為螭龍魚提供大量食物，螭龍魚則為林家商船指引航道。",
  ui_story_5075_50750902_53_dialog_content = "螭龍魚就這樣成了林家的圖騰。",
  ui_story_5075_50750902_54_dialog_content = "這條「魚林街」，也是由此得名。",
  ui_story_5075_50750902_55_dialog_content = "但隨著先祖死去，後代降生，林家商會規模越來越大。",
  ui_story_5075_50750902_56_dialog_content = "每年一次的商船往返已經滿足不了商會需求。",
  ui_story_5075_50750902_57_dialog_content = "之後的家主，開始要求螭龍魚增加引船的次數。",
  ui_story_5075_50750902_58_dialog_content = "等等，和魚商量？",
  ui_story_5075_50750902_59_dialog_content = "我就站在這裡，PlayerName卻還沒意識到嗎？",
  ui_story_5075_50750902_60_dialog_content = "當時的螭龍魚首領，是<color=#FFB400>祟靈</color>。",
  ui_story_5075_50750902_61_dialog_content = "林家的螭龍魚血統，也是從那時開始傳下來的。",
  ui_story_5075_50750902_62_dialog_content = "但隨著林家不再遵守最初的約定，不顧螭龍魚的習性強行行船。",
  ui_story_5075_50750902_63_dialog_content = "雙方的關係也逐漸惡化。",
  ui_story_5075_50750902_64_dialog_content = "甚至有一次，林家的船破壞了螭龍魚的棲息地。",
  ui_story_5075_50750902_65_dialog_content = "這件事徹底惹惱了現任的螭龍魚首領，牠決定徹底中止和林家的合作。",
  ui_story_5075_50750902_66_dialog_content = "我至今還記得，當時剛能化形的尤衝進院子，罵我卑鄙時的樣子。",
  ui_story_5075_50750902_67_dialog_content = "家主，您回來了。",
  ui_story_5075_50750902_68_dialog_content = "林家主，您……",
  ui_story_5075_50750902_69_dialog_content = "哈哈，我聽到剛才的話了。",
  ui_story_5075_50750902_70_dialog_content = "這種事，對小郎君來說應該難以接受吧。",
  ui_story_5075_50750902_71_dialog_content = "我也不會為林家開脫。前人所做之事，確實背信棄義。",
  ui_story_5075_50750902_72_dialog_content = "但我是個商人，我很清楚，林家最終因此而得利，問鼎皓津商界。",
  ui_story_5075_50750902_73_dialog_content = "如果那時是我當家，我恐怕也會做出同樣的決定。",
  ui_story_5075_50750902_74_dialog_content = "若非當時已得知「渾儀」的消息，林家甚至不會那麼輕易放牠離開。",
  ui_story_5075_50750902_75_dialog_content = "說不定會將牠囚禁起來，成為引路的工具。",
  ui_story_5075_50750902_76_dialog_content = "他恨我、恨林家，無可厚非。",
  ui_story_5075_50750902_77_dialog_content = "輕諾寡信，過河拆橋，過去的林家曾做過這樣的事。",
  ui_story_5075_50750902_78_dialog_content = "如今，林家也算是遭了報應。",
  ui_story_5075_50750902_79_dialog_content = "沿海妖魔出沒，濟國卻始終無力清出穩定的防線。",
  ui_story_5075_50750902_80_dialog_content = "之前聽說要從鄴國購置的岸防砲，也一直遲遲未到。",
  ui_story_5075_50750902_81_dialog_content = "林家商船已許久無法出海，沿岸生意停滯，簡直是才出虎口又入狼窩。",
  ui_story_5075_50750902_82_dialog_content = "我剛從市舶司脫身，就不顧仲兄勸阻，恬不知恥地去找尤。",
  ui_story_5075_50750902_83_dialog_content = "希望他能再幫林家探探水路，護一護商船。結果自然是被趕了出來。",
  ui_story_5075_50750902_84_dialog_content = "依PlayerName所言，他終究還是去了海中調查情況……",
  ui_story_5075_50750902_85_dialog_content = "隨後被惡蛟的怨力侵蝕，逐漸狂化，也引燃附近祟靈的憎恨之火。",
  ui_story_5075_50750902_86_dialog_content = "……這是林家之罪，林家必須解決。",
  ui_story_5075_50750902_87_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5075_50750902_88_dialog_content = "把祟靈都趕出去！",
  ui_story_5075_50750902_89_dialog_content = "外面怎麼了？",
  ui_story_5075_50751001_1_dialog_content = "<color=#e8d9bb>羅松站在街道中央，面對一群憤怒的百姓，護著幾隻昏迷倒地的祟靈。</color>",
  ui_story_5075_50751001_2_dialog_content = "大家冷靜點！這些祟靈並不是自己想要傷人的！",
  ui_story_5075_50751001_3_dialog_content = "我已經控制住牠們了！只要祛除牠們身上的侵蝕力就——",
  ui_story_5075_50751001_4_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5075_50751001_5_dialog_content = "<color=#e8d9bb>人群中飛出一顆石子砸在羅松身上。</color>",
  ui_story_5075_50751001_6_dialog_content = "嗷！",
  ui_story_5075_50751001_7_dialog_content = "阿丁！你也冷靜！",
  ui_story_5075_50751001_8_dialog_content = "我沒事，現在不能和他們起衝突。",
  ui_story_5075_50751001_9_dialog_content = "人都傷了，管牠們想不想還有什麼用！",
  ui_story_5075_50751001_10_dialog_content = "就說祟靈不是什麼好東西！平常偷偷東西就算了，現在可是要殺人呀！",
  ui_story_5075_50751001_11_dialog_content = "皓津這幾百年都安安穩穩的，今天連妖魔都進城了！",
  ui_story_5075_50751001_12_dialog_content = "還說不是祟靈搞的鬼！牠們就是一夥的邪祟！",
  ui_story_5075_50751001_13_dialog_content = "你們會法術，當然站著說話不腰疼！",
  ui_story_5075_50751001_14_dialog_content = "但你們不怕，我們怕啊！",
  ui_story_5075_50751001_15_dialog_content = "不能讓這些晦氣的傢伙在城裡待著！把牠們都趕出去！",
  ui_story_5075_50751001_16_dialog_content = "趕出去！趕出去！！！",
  ui_story_5075_50751001_17_dialog_content = "我得去幫羅松——",
  ui_story_5075_50751001_18_dialog_content = "慢著。若無準備，去了也無濟於事。",
  ui_story_5075_50751001_19_dialog_content = "憤怒的人群沒有理智，什麼道理都不會聽的。",
  ui_story_5075_50751001_20_dialog_content = "除非你能展現出更強的力量，或給出絕對能令人信服的保證。",
  ui_story_5075_50751001_21_dialog_content = "我有那塊令牌！不是說可以調動巡檢司嗎？",
  ui_story_5075_50751001_22_dialog_content = "巡檢司的隊伍應該正分散在城裡對付暗鬼。",
  ui_story_5075_50751001_23_dialog_content = "而且若是巡檢司介入……對百姓而言只會激化矛盾。",
  ui_story_5075_50751001_24_dialog_content = "但現在也沒有其他方法……",
  ui_story_5075_50751001_25_dialog_content = "不是說了嗎，我有。應該說，林家有。",
  ui_story_5075_50751001_26_dialog_content = "家主，您也聽見了。",
  ui_story_5075_50751001_27_dialog_content = "我要正式向您索求——皓津<color=#FFB400>代行林家家主</color>的資格。",
  ui_story_5075_50751001_28_dialog_content = "請給我調配林家資源和人手的權力，讓我能處理此事。",
  ui_story_5075_50751001_29_dialog_content = "妳打算怎麼做？",
  ui_story_5075_50751001_30_dialog_content = "林家商會雖然不如幾年前顯赫，但多代經營，在百姓中的名望不小。",
  ui_story_5075_50751001_31_dialog_content = "我想用林家的名義確保解決此事，並派出醫師、夥計去幫助受害民眾。",
  ui_story_5075_50751001_32_dialog_content = "妳可知妳輕飄飄的一句話，押上的是什麼？",
  ui_story_5075_50751001_33_dialog_content = "林家家業不小，但也沒到能隨隨便便就能為一城百姓負責的地步。",
  ui_story_5075_50751001_34_dialog_content = "況且此前林家牽涉走私案，好不容易才洗清污名。",
  ui_story_5075_50751001_35_dialog_content = "商場如戰場，私下可以耍手腕弄心眼，台上的名聲卻必須乾乾淨淨。",
  ui_story_5075_50751001_36_dialog_content = "妳拿林家名義為祟靈作保，但凡有所差池，林家將成眾矢之的。",
  ui_story_5075_50751001_37_dialog_content = "我知道。",
  ui_story_5075_50751001_38_dialog_content = "但祟靈傷人之事是尤在操控，他對人的憎恨又是因林家而起。",
  ui_story_5075_50751001_39_dialog_content = "林家需負起責任。",
  ui_story_5075_50751001_40_dialog_content = "如今的環境真是變了。",
  ui_story_5075_50751001_41_dialog_content = "濟國重商，商人逐利。",
  ui_story_5075_50751001_42_dialog_content = "我年輕時，多小的利益都有人爭奪，乞丐的一捧糙米也能引來垂涎。",
  ui_story_5075_50751001_43_dialog_content = "林家更是連世代供奉的螭龍魚都可拋棄。",
  ui_story_5075_50751001_44_dialog_content = "現在，妳竟敢要我為了一句「負責」的漂亮話，再賭上辛苦賺來的一切？",
  ui_story_5075_50751001_45_dialog_content = "能實現，就不是漂亮話。",
  ui_story_5075_50751001_46_dialog_content = "等等，你們別自己人吵起來啊，現在……",
  ui_story_5075_50751001_47_dialog_content = "在下這有一條您也能學的咒語。",
  ui_story_5075_50751001_48_dialog_content = "甭管遇上什麼事，這條咒語一出，多大的干戈都能立刻化為玉帛。",
  ui_story_5075_50751001_49_dialog_content = "（雖然總覺得不太可能，但試試看總不會有損失！）",
  ui_story_5075_50751001_50_dialog_content = "<color=#FFB400>大、<size=45>大過年的！</size></color>",
  ui_story_5075_50751001_51_dialog_content = "……",
  ui_story_5075_50751001_52_dialog_content = "……",
  ui_story_5075_50751001_53_dialog_content = "哈哈哈……過年啊。",
  ui_story_5075_50751001_54_dialog_content = "辭舊，迎新，舊貌煥新顏。",
  ui_story_5075_50751001_55_dialog_content = "籌備了這麼久，再過一日就是春朔正日了吧？",
  ui_story_5075_50751001_56_dialog_content = "是。",
  ui_story_5075_50751001_57_dialog_content = "年夜飯都備好了嗎？",
  ui_story_5075_50751001_58_dialog_content = "大半食材已經放進了冰窖，鮮菜也已訂好，當天會有人送來。",
  ui_story_5075_50751001_59_dialog_content = "商會的帳目剛清點完成，總結條陳放在您的書房。",
  ui_story_5075_50751001_60_dialog_content = "今年林家生意艱難，但我還是自作主張替護衛和幫工多發了兩個月工錢。",
  ui_story_5075_50751001_61_dialog_content = "妳倒是有主見。",
  ui_story_5075_50751001_62_dialog_content = "行船時，面對瞬息萬變的海況，船長需以最快的速度做出應對的決斷。",
  ui_story_5075_50751001_63_dialog_content = "一陣順風，一股潮湧，若是不能在出現的瞬間抓住，就會徹底錯失。",
  ui_story_5075_50751001_64_dialog_content = "妳覺得眼前此景，是能推動林家的「順風」嗎？",
  ui_story_5075_50751001_65_dialog_content = "妳若能篤定，我就答應妳的請求。",
  ui_story_5075_50751001_66_dialog_content = "太好了……",
  ui_story_5075_50751001_67_dialog_content = "<size=45>我不能。</size>",
  ui_story_5075_50751001_68_dialog_content = "噗——咳咳咳……",
  ui_story_5075_50751001_69_dialog_content = "但我知道，當真正的滔天巨浪襲來時，縱船上之人有千般算計，也於事無補。",
  ui_story_5075_50751001_70_dialog_content = "能支撐一艘船掙扎到最後的，唯有其本身最穩，最正的龍骨。",
  ui_story_5075_50751001_71_dialog_content = "船的脊樑，不能彎。",
  ui_story_5075_50751001_72_dialog_content = "……",
  ui_story_5075_50751001_73_dialog_content = "或許妳對今日形勢的判斷才是對的，而我終究是舊時代的老古板。",
  ui_story_5075_50751001_74_dialog_content = "在我看來，妳行事太過激進冒險。",
  ui_story_5075_50751001_75_dialog_content = "家主——",
  ui_story_5075_50751001_76_dialog_content = "但妳是蜃風號的船長，手握堪稱林家命脈的航線。",
  ui_story_5075_50751001_77_dialog_content = "在他人眼中，妳的話完全可以代表林家。",
  ui_story_5075_50751001_78_dialog_content = "您的意思是？",
  ui_story_5075_50751001_79_dialog_content = "我是老古板，但更是個商人，會多方考量，權衡利弊。",
  ui_story_5075_50751001_80_dialog_content = "妳是能掌新時代機巧大船的船長，自可按妳所想行事。",
  ui_story_5075_50751001_81_dialog_content = "若成，妳是林家的功臣，我會將龍洲近海的航線也交由妳負責。",
  ui_story_5075_50751001_82_dialog_content = "若不成，妳就是違背家主命令，擅自行動的罪人。",
  ui_story_5075_50751001_83_dialog_content = "林家也許會將妳徹底逐出，妳怕是連木都要姓不成。",
  ui_story_5075_50751001_84_dialog_content = "這樣的條件，妳可接受？",
  ui_story_5075_50751001_85_dialog_content = "<size=45>我接受。</size>",
  ui_story_5075_50751001_86_dialog_content = "PlayerName，走吧。",
  ui_story_5075_50751001_87_dialog_content = "好……啊，稍等一下。",
  ui_story_5075_50751001_88_dialog_content = "林家主，這塊令牌能拜託您先保管嗎？",
  ui_story_5075_50751001_89_dialog_content = "這麼重要的東西，你放心交給我？",
  ui_story_5075_50751001_91_dialog_content = "別忘了我可是個背信棄義的小人。",
  ui_story_5075_50751001_92_dialog_content = "哈哈……說完全放心確實是騙人的。",
  ui_story_5075_50751001_93_dialog_content = "但我現在沒有使用這塊令牌的機會。和令牌一起的地圖也指向您這裡。",
  ui_story_5075_50751001_94_dialog_content = "儘管您一直強調自己不值得信任，月白和仲胥卻都信賴您。",
  ui_story_5075_50751001_95_dialog_content = "我相信他們的判斷。",
  ui_story_5075_50751001_96_dialog_content = "我的感應能力也告訴我，就算您真要做什麼壞事，這裡也絕對有人能阻止您。",
  ui_story_5075_50751001_97_dialog_content = "那我就收下了。",
  ui_story_5075_50751001_98_dialog_content = "拜託您了。",
  ui_story_5075_50751001_99_dialog_content = "月白，我們走吧——",
  ui_story_5075_50751001_100_dialog_content = "唉，年輕人。",
  ui_story_5075_50751001_101_dialog_content = "就知道往危險的地方跑，還是太不穩重了。林家的未來真是讓人放不下心啊。",
  ui_story_5075_50751001_102_dialog_content = "你的表情可不是這麼說的。",
  ui_story_5075_50751001_103_dialog_content = "就差把「我林家後繼有人囉」寫臉上了。",
  ui_story_5075_50751001_104_dialog_content = "哈哈哈，仲兄火眼金睛。",
  ui_story_5075_50751001_105_dialog_content = "我本還想慢慢將過去的糾葛帶走，好交給後人一個更乾淨的林家。",
  ui_story_5075_50751001_106_dialog_content = "沒想到這後浪推前浪，還沒等我出手，她就先接下這個重擔了。",
  ui_story_5075_50751001_107_dialog_content = "不過仲兄，你一直在暗處看著，不過去幫忙嗎？",
  ui_story_5075_50751001_108_dialog_content = "PlayerName都發現你在了。",
  ui_story_5075_50751001_109_dialog_content = "你不也是？",
  ui_story_5075_50751001_110_dialog_content = "小友都已將巡檢司的令牌帶來，你卻半點不提自己和國師的交易。",
  ui_story_5075_50751001_111_dialog_content = "明明早就答應國師要幫忙，小友剛到就急忙去叫我準備調動林家的護衛。",
  ui_story_5075_50751001_112_dialog_content = "何必還特地演這齣戲？",
  ui_story_5075_50751001_113_dialog_content = "我們這些老頭子太過迂迴，跟年輕人不好解釋。",
  ui_story_5075_50751001_114_dialog_content = "就當是我為春朔節準備的辭舊迎新儀式吧。",
  ui_story_5075_50751001_115_dialog_content = "你看，還沒到春朔，就聽到這麼多漂亮話。",
  ui_story_5075_50751001_116_dialog_content = "這可是個好彩頭啊。",
  ui_story_5075_50751001_117_dialog_content = "別廢話了！這傢伙護著祟靈，絕對也不是什麼好東西。",
  ui_story_5075_50751001_118_dialog_content = "你現在讓開，讓我們把邪祟趕出去還來得及。",
  ui_story_5075_50751001_119_dialog_content = "不然就算你有法術，我們也要不客氣了。",
  ui_story_5075_50751001_120_dialog_content = "我知道你們的恐懼，但無論如何都得講道理——",
  ui_story_5075_50751001_121_dialog_content = "把牠們全都趕出去——！",
  ui_story_5075_50751001_122_dialog_content = "趕出去——！",
  ui_story_5075_50751001_123_dialog_content = "嗷！",
  ui_story_5075_50751001_124_dialog_content = "糟糕，是那些來不及處理的祟靈……",
  ui_story_5075_50751001_125_dialog_content = "螭龍席捲！",
  ui_story_5075_50751002_1_dialog_content = "<color=#e8d9bb>如同一把鋒利的匕首，木月白輕盈地刺入祟靈群中。</color>",
  ui_story_5075_50751002_2_dialog_content = "<color=#e8d9bb>觀者甚至來不及反應，上一秒還狂暴的祟靈便失去意識，倒在一旁。</color>",
  ui_story_5075_50751002_3_dialog_content = "那……那是誰啊，太厲害了吧？",
  ui_story_5075_50751002_4_dialog_content = "我知道，那是林家商會的木船長。",
  ui_story_5075_50751002_5_dialog_content = "但她的尾巴……她也有祟靈血統，是不是……",
  ui_story_5075_50751002_6_dialog_content = "她剛才救了我們，你怎能說這種話！",
  ui_story_5075_50751002_7_dialog_content = "諸位，請聽我一言。",
  ui_story_5075_50751002_8_dialog_content = "我知今日之事令大家惶恐不安，有人受傷，也有人蒙受損失。",
  ui_story_5075_50751002_9_dialog_content = "我與你們一樣憤怒。",
  ui_story_5075_50751002_10_dialog_content = "但這些變故的真凶，不是這些祟靈，而是在背後利用牠們傷人的貨色。",
  ui_story_5075_50751002_11_dialog_content = "我們若一股腦針對祟靈，便是掉進了陷阱。",
  ui_story_5075_50751002_12_dialog_content = "妳也有牠們的血統，當然會這麼說了！",
  ui_story_5075_50751002_13_dialog_content = "但我身上也有更多普通光靈的血統。林家是與人做生意，又不是與祟靈。",
  ui_story_5075_50751002_14_dialog_content = "我為何要對人不利？",
  ui_story_5075_50751002_15_dialog_content = "……",
  ui_story_5075_50751002_16_dialog_content = "口說無憑，我知道自己沒資格要求大家全盤信我。",
  ui_story_5075_50751002_17_dialog_content = "但我以林家商會的信譽保證，會拿出證據，查出真相。",
  ui_story_5075_50751002_18_dialog_content = "諸位也一定不願被罪魁禍首誤導利用，任由對方在暗處逍遙吧。",
  ui_story_5075_50751002_19_dialog_content = "就算妳這麼說……",
  ui_story_5075_50751002_20_dialog_content = "（他們還是有所懷疑，但我們又拿不出證據……對了！）",
  ui_story_5075_50751002_21_dialog_content = "強制感應！",
  ui_story_5075_50751002_22_dialog_content = "（拜託，哪怕只有一點點也好，把我看到的東西傳遞給其他人……）",
  ui_story_5075_50751002_23_dialog_content = "各位！請看這些祟靈的身上！",
  ui_story_5075_50751002_24_dialog_content = "那……那是什麼？！",
  ui_story_5075_50751002_25_dialog_content = "這就是幕後黑手操控祟靈的力量。",
  ui_story_5075_50751002_26_dialog_content = "只要這份力量不消失，就算趕走這些祟靈也沒有用。",
  ui_story_5075_50751002_27_dialog_content = "他們好像……不是在騙人。",
  ui_story_5075_50751002_28_dialog_content = "林家這麼多年確實幫大夥出過不少貢獻，但……",
  ui_story_5075_50751002_29_dialog_content = "<color=#e8d9bb>他們聚在一起，小聲商議片刻後，派出了一名代表。</color>",
  ui_story_5075_50751002_30_dialog_content = "我們暫且相信你們。",
  ui_story_5075_50751002_31_dialog_content = "今日天色已晚，我們也不想在這裡耗著。",
  ui_story_5075_50751002_32_dialog_content = "但城裡還有不少祟靈遊蕩，誰知道你們調查的時候牠們又會做出什麼好事？",
  ui_story_5075_50751002_33_dialog_content = "所以我們有個條件。",
  ui_story_5075_50751002_34_dialog_content = "你們得在春朔節之前解決這件事，讓大家過個好年。",
  ui_story_5075_50751002_35_dialog_content = "好。",
  ui_story_5075_50751002_36_dialog_content = "就是說啊，大過年的！誰不想早點解決呢！",
  ui_story_5075_50751002_37_dialog_content = "<color=#e8d9bb>木月白又派出人手安撫了他們一番，眾人終於陸續離開。</color>",
  ui_story_5075_50751002_38_dialog_content = "多謝你們的幫忙。",
  ui_story_5075_50751002_39_dialog_content = "不然我一個人單挑這麼多人，還真要費些力氣。",
  ui_story_5075_50751002_40_dialog_content = "你說的「單挑」，不會是真單挑吧……",
  ui_story_5075_50751002_41_dialog_content = "不過春朔節就是一天後了，時間很緊啊。",
  ui_story_5075_50751002_42_dialog_content = "好在我們已經查到了不少線索。",
  ui_story_5075_50751002_43_dialog_content = "最初是有人破壞了阿霓的封印，導致海中曾經支配黑蛟的力量溢出。",
  ui_story_5075_50751002_44_dialog_content = "這些力量雖然有些特別的性質，但本質依舊是一種暗能。",
  ui_story_5075_50751002_45_dialog_content = "暗能將大量暗鬼吸引到海邊，導致林家商船無法出海，生意停滯。",
  ui_story_5075_50751002_46_dialog_content = "林家家主只好去找曾經合作過的祟靈「尤」，希望牠能調查出暗鬼聚集的原因。",
  ui_story_5075_50751002_47_dialog_content = "結果尤在調查中受黑氣侵蝕，現在只剩下對林家的恨意。",
  ui_story_5075_50751002_48_dialog_content = "而有了軀體依附後，黑氣也變得更加活躍，開始影響周圍的祟靈。",
  ui_story_5075_50751002_49_dialog_content = "甚至逐漸蔓延到皓津城內。",
  ui_story_5075_50751002_50_dialog_content = "所以我們只要先找到尤，想辦法祛除牠身上的黑氣。",
  ui_story_5075_50751002_51_dialog_content = "再像過去的阿霓那樣封印黑氣的力量就行了吧？",
  ui_story_5075_50751002_52_dialog_content = "那還不快點出發！",
  ui_story_5075_50751002_53_dialog_content = "吱！",
  ui_story_5075_50751002_54_dialog_content = "守祟淨火！",
  ui_story_5075_50751002_55_dialog_content = "可惡，城裡的黑氣擴散得太廣，現在還陸續有祟靈受到影響。",
  ui_story_5075_50751002_56_dialog_content = "羅松，你留下來吧。",
  ui_story_5075_50751002_57_dialog_content = "牠們需要你幫忙。",
  ui_story_5075_50751002_58_dialog_content = "好吧。但在此之前，來——",
  ui_story_5075_50751002_59_dialog_content = "這是……？",
  ui_story_5075_50751002_60_dialog_content = "碰個拳吧。",
  ui_story_5075_50751002_61_dialog_content = "這樣，我們就算是共患難的朋友了。",
  ui_story_5075_50751002_62_dialog_content = "等你回來，我請你吃最新鮮的菱角。",
  ui_story_5075_50751002_63_dialog_content = "好！",
  ui_story_5075_50751002_64_dialog_content = "那我接著去找被侵蝕的祟靈了，你們也加油！",
  ui_story_5075_50751002_65_dialog_content = "我也去叫月白……咦？",
  ui_story_5075_50751002_66_dialog_content = "使者大人，終於又找到您了。",
  ui_story_5075_50751002_67_dialog_content = "您真的……很能跑。",
  ui_story_5075_50751002_68_dialog_content = "是主事官……您、您怎麼會在這裡？",
  ui_story_5075_50751002_69_dialog_content = "現在城中邪祟橫行，我們當然得保護您的安全。",
  ui_story_5075_50751002_70_dialog_content = "請隨我們回禮賓館吧。",
  ui_story_5075_50751002_71_dialog_content = "我還有很重要的事，不能回去。",
  ui_story_5075_50751002_72_dialog_content = "請別為難我們，您是千里迢迢來濟國的貴客。",
  ui_story_5075_50751002_73_dialog_content = "您少了半根汗毛，我們可是要掉腦袋的，還請體諒我們。",
  ui_story_5075_50751002_74_dialog_content = "護送使者大人回館！",
  ui_story_5075_50751002_75_dialog_content = "等等！放開我——唔。",
  ui_story_5075_50751002_76_dialog_content = "PlayerName，我回來了。",
  ui_story_5075_50751002_77_dialog_content = "……PlayerName？",
  ui_story_5075_50751101_1_dialog_content = "花事，不休！",
  ui_story_5075_50751101_2_dialog_content = "唔嗯……",
  ui_story_5075_50751101_3_dialog_content = "你們看著像刺客，招招難纏，卻又都不是傷人之技。",
  ui_story_5075_50751101_4_dialog_content = "目的只是將本郡主攔在這裡嗎？",
  ui_story_5075_50751101_5_dialog_content = "……",
  ui_story_5075_50751101_6_dialog_content = "便是剛剛本郡主假意攻之要害，你們也不曾反擊。",
  ui_story_5075_50751101_7_dialog_content = "至今你們傷了數人，本郡主卻毫髮無損。",
  ui_story_5075_50751101_8_dialog_content = "呵呵，我今日倒是明白PlayerName公子所說的話了。",
  ui_story_5075_50751101_9_dialog_content = "被莫名其妙地慎重對待至此，確實怪異。",
  ui_story_5075_50751101_10_dialog_content = "但世間的莫名其妙，都必然有其原因。",
  ui_story_5075_50751101_11_dialog_content = "璇璣卿在信中所說之事，阿玖走前所囑咐之事，還有老師的提示。",
  ui_story_5075_50751101_12_dialog_content = "有了這麼多線索，若還猜不出事情的真相，可就真是愚人了。",
  ui_story_5075_50751101_13_dialog_content = "你們……是鄴國的暗探吧？",
  ui_story_5075_50751101_14_dialog_content = "！",
  ui_story_5075_50751101_15_dialog_content = "殿下聰慧。既然猜到了，想必您也清楚在下不會害您。",
  ui_story_5075_50751101_16_dialog_content = "皓津城內龍蛇混雜，還請殿下回宮暫避。",
  ui_story_5075_50751101_17_dialog_content = "我現在出宮，會打亂你們的計畫嗎？",
  ui_story_5075_50751101_18_dialog_content = "這兩國之間，你來我往，明爭暗鬥是常事。",
  ui_story_5075_50751101_19_dialog_content = "殿下心善，<color=#FFB400>我們大人</color>不忍您為難，所以還請回去吧。",
  ui_story_5075_50751101_20_dialog_content = "……<color=#FFB400>你們大人</color>。",
  ui_story_5075_50751101_21_dialog_content = "殿下要是不聽勸，在下也只能冒犯了。",
  ui_story_5075_50751101_22_dialog_content = "動手！",
  ui_story_5075_50751101_23_dialog_content = "風起——",
  ui_story_5075_50751101_24_dialog_content = "<color=#e8d9bb>唰——</color>",
  ui_story_5075_50751101_25_dialog_content = "殿下，您沒受傷吧？",
  ui_story_5075_50751101_26_dialog_content = "阿玖？我還以為妳被他們引開了，一時半會回不來呢。",
  ui_story_5075_50751101_27_dialog_content = "玖的使命就是保護殿下。",
  ui_story_5075_50751101_28_dialog_content = "只要殿下需要，那玖無論身在何處，一定會回到您身邊。",
  ui_story_5075_50751101_29_dialog_content = "<color=#e8d9bb>一隻手突然抓住玖的腳腕。</color>",
  ui_story_5075_50751101_30_dialog_content = "霜……刃大人……您不能……",
  ui_story_5075_50751101_31_dialog_content = "<color=#e8d9bb>唰——</color>",
  ui_story_5075_50751101_32_dialog_content = "感覺，之後會有很多事需要問妳呢。",
  ui_story_5075_50751101_33_dialog_content = "不過現在還有另一件事迫在眉睫，先跟我去找PlayerName公子吧。",
  ui_story_5075_50751101_34_dialog_content = "殿下可知PlayerName閣下在何處？",
  ui_story_5075_50751101_35_dialog_content = "我出來得倉促，還來不及……",
  ui_story_5075_50751101_36_dialog_content = "前程風水，乾坤陰陽；您想知道什麼答案，不如來算上一卦？",
  ui_story_5075_50751101_37_dialog_content = "……李天閑。",
  ui_story_5075_50751101_38_dialog_content = "你一直在那裡看著嗎？",
  ui_story_5075_50751101_39_dialog_content = "您說什麼？在下剛賣完糖人，突然心有所感。",
  ui_story_5075_50751101_40_dialog_content = "覺著在這個方位能遇上貴人，這才走過來碰碰運氣。",
  ui_story_5075_50751101_41_dialog_content = "什麼不該看的我都沒看啊。",
  ui_story_5075_50751101_42_dialog_content = "算了，別管他。",
  ui_story_5075_50751101_43_dialog_content = "唉，想要開發新客戶還真難。還是PlayerName好，說什麼信什麼。",
  ui_story_5075_50751101_44_dialog_content = "……你見過PlayerName公子？",
  ui_story_5075_50751101_45_dialog_content = "可不？在下還送了他一支梅花糖和一句詩呢。",
  ui_story_5075_50751101_46_dialog_content = "不過您也不必太感謝在下。",
  ui_story_5075_50751101_47_dialog_content = "這話說得好沒道理，我感謝你做什麼？",
  ui_story_5075_50751101_48_dialog_content = "但你要是能告訴我PlayerName公子在何處，我倒是該謝你。",
  ui_story_5075_50751101_49_dialog_content = "喏，就在那邊的魚林街，不過您可得快點了。",
  ui_story_5075_50751101_50_dialog_content = "不然容易被人搶走囉。",
  ui_story_5075_50751101_51_dialog_content = "……阿玖，我們走吧。",
  ui_story_5075_50751101_52_dialog_content = "留步留步，在下今兒賣了一天糖人，正手癢呢。",
  ui_story_5075_50751101_53_dialog_content = "就當開業酬賓，送您一卦。",
  ui_story_5075_50751101_54_dialog_content = "依在下所算呀，您接下來必然是要往東南去，能見一貴人。",
  ui_story_5075_50751101_55_dialog_content = "魚林街就在東南，是你自己指我的方向。",
  ui_story_5075_50751101_56_dialog_content = "但您就說，您接下來是不是要往那邊去吧。",
  ui_story_5075_50751101_57_dialog_content = "我可沒閒心聽你胡言亂語。",
  ui_story_5075_50751101_58_dialog_content = "這就是在下所算的「命」。",
  ui_story_5075_50751101_59_dialog_content = "丹棠殿下，這算卦呢，大部分時候是問天、問地、問神靈。",
  ui_story_5075_50751101_60_dialog_content = "但最準的法子，乃是「問己」。",
  ui_story_5075_50751101_61_dialog_content = "己有所思，己有所慾，己有所行，即成己之「命」。",
  ui_story_5075_50751101_62_dialog_content = "哎，一不留神又耽擱您時間了，不說了不說了，您請自便。",
  ui_story_5075_50751101_63_dialog_content = "……",
  ui_story_5075_50751101_64_dialog_content = "多謝你了。",
  ui_story_5075_50751101_65_dialog_content = "客氣，多來照顧在下生意就行了。",
  ui_story_5075_50751101_66_dialog_content = "放心，不會的。",
  ui_story_5075_50751102_1_dialog_content = "唔……",
  ui_story_5075_50751102_2_dialog_content = "這裡……不是禮賓館吧？",
  ui_story_5075_50751102_3_dialog_content = "口口聲聲尊稱貴客，我卻還是第一次看到有人把貴客打暈綁走的。",
  ui_story_5075_50751102_4_dialog_content = "要是您老實聽話，我本來也沒打算這麼出現在您面前。",
  ui_story_5075_50751102_5_dialog_content = "畢竟這禮賓館主事官的身分十分方便，我還不想換。",
  ui_story_5075_50751102_6_dialog_content = "卻沒想到您這麼能折騰，就連林家都被您說動要幫忙。",
  ui_story_5075_50751102_7_dialog_content = "要是鬧不好，我們好不容易攪渾的局面可真要被您一手解決了。",
  ui_story_5075_50751102_8_dialog_content = "所以這一切都是你們幹的？",
  ui_story_5075_50751102_9_dialog_content = "破壞鎮海封印、將黑氣擴散到全城、挑起人和祟靈的矛盾。",
  ui_story_5075_50751102_10_dialog_content = "你們究竟想做什麼？",
  ui_story_5075_50751102_11_dialog_content = "這就不是您該關心的了。",
  ui_story_5075_50751102_12_dialog_content = "您只要先在這藏身處休息，等一切塵埃落定，<color=#FFB400>我們</color>就放您出去。",
  ui_story_5075_50751102_13_dialog_content = "<color=#FFB400>「你們」</color>……是指濟國朝廷內的同黨嗎？",
  ui_story_5075_50751102_14_dialog_content = "是國師告訴您的吧？",
  ui_story_5075_50751102_15_dialog_content = "那個老匹夫，還不知道我們的存在時，就三番兩次阻撓我們的行動。",
  ui_story_5075_50751102_16_dialog_content = "不過他也囂張不了幾天了。",
  ui_story_5075_50751102_17_dialog_content = "這還多虧了您。",
  ui_story_5075_50751102_18_dialog_content = "我？",
  ui_story_5075_50751102_19_dialog_content = "您入宮那天，我聽見您和國師跟郡主的談話。",
  ui_story_5075_50751102_20_dialog_content = "別看王宮牆高院深的，那裡面可是天底下最藏不住祕密的地方。",
  ui_story_5075_50751102_21_dialog_content = "老匹夫該是意識到我們的人正慢慢滲透朝堂，卻又無法確定是誰。",
  ui_story_5075_50751102_22_dialog_content = "所以才想利用您這個外人。",
  ui_story_5075_50751102_23_dialog_content = "但他這麼一動，倒是給了我機會。",
  ui_story_5075_50751102_24_dialog_content = "我知道老匹夫藉那個食盒把巡檢司的令牌交給您了。",
  ui_story_5075_50751102_25_dialog_content = "要是您真調用巡檢司，解了如今的困局，老匹夫的行為就只是事急從權。",
  ui_story_5075_50751102_26_dialog_content = "就是有人追究起來，也有辯解的餘地。",
  ui_story_5075_50751102_27_dialog_content = "但要是您什麼都還沒做，就先被人發現令牌的存在……",
  ui_story_5075_50751102_28_dialog_content = "身為國師，將這麼重要的東西交予他國，甚至是另一片大陸之人。",
  ui_story_5075_50751102_29_dialog_content = "對方還在皓津最混亂的時候行蹤成謎。",
  ui_story_5075_50751102_30_dialog_content = "誰能相信你們不是相互勾結，打算對濟國不利？",
  ui_story_5075_50751102_31_dialog_content = "這不判個叛國之罪，整個朝堂都不會同意吧。",
  ui_story_5075_50751102_32_dialog_content = "讓我看看，您把令牌藏在哪裡？口袋？衣袖？",
  ui_story_5075_50751102_33_dialog_content = "別找了，不在我身上。",
  ui_story_5075_50751102_34_dialog_content = "從國師叮囑要隱密行動時，我就在想，是不是我能接觸到的人有問題。",
  ui_story_5075_50751102_35_dialog_content = "之後又收到那個食盒，就更讓我確定不可信的人在禮賓館。",
  ui_story_5075_50751102_36_dialog_content = "但如果是這樣，裡面的東西其實不一定能瞞得住你的眼睛。",
  ui_story_5075_50751102_37_dialog_content = "所以我才覺得要盡快離開那裡。",
  ui_story_5075_50751102_38_dialog_content = "這又有什麼意義？你還不是找不到調動巡檢司的機會。",
  ui_story_5075_50751102_39_dialog_content = "何況你不過一介異域之人，在龍洲的人脈屈指可數。",
  ui_story_5075_50751102_40_dialog_content = "就算和郡主相識，但郡主居於宮中，我又命暗探時刻監視，你們沒機會交流。",
  ui_story_5075_50751102_41_dialog_content = "你能將令牌交給誰，隨隨便便就調查得出來。",
  ui_story_5075_50751102_42_dialog_content = "喔，我知道了。是林家吧？",
  ui_story_5075_50751102_43_dialog_content = "林家的家主只要有利可圖，多大的風險都敢擔。",
  ui_story_5075_50751102_44_dialog_content = "但將巡檢司的調動權交給一個有前科的商戶……哈哈哈！",
  ui_story_5075_50751102_45_dialog_content = "就算濟國重商，這也是荒唐到前所未聞的行徑，想定罪也不難。",
  ui_story_5075_50751102_46_dialog_content = "我剛剛一瞬竟真覺得你有什麼底牌，看來不過還是個涉世未深的小子。",
  ui_story_5075_50751102_47_dialog_content = "我還得去盯著底下人的動靜，就不陪你了。",
  ui_story_5075_50751102_48_dialog_content = "誰說我把令牌交給林家了？",
  ui_story_5075_50751102_49_dialog_content = "就算不是林家，也是之前跟你混在一起的那兩個人吧？",
  ui_story_5075_50751102_50_dialog_content = "平民百姓跟商戶也沒什麼兩樣——",
  ui_story_5075_50751102_51_dialog_content = "不是平民。",
  ui_story_5075_50751102_52_dialog_content = "<size=45>是<color=#FFB400>灼華郡主</color>。</size>",
  ui_story_5075_50751102_53_dialog_content = "你沒聽見嗎？我剛剛說過郡主身邊有暗探監視，她不可能……",
  ui_story_5075_50751102_54_dialog_content = "<size=45>她會來的。</size>",
  ui_story_5075_50751102_55_dialog_content = "令牌代表巡檢司，地址代表林家，指點我的是國師。",
  ui_story_5075_50751102_56_dialog_content = "而裝著這些的，是海棠花。",
  ui_story_5075_50751102_57_dialog_content = "能將這兩樣東西物盡其用的人，只有丹棠！",
  ui_story_5075_50751102_58_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_5075_50751102_59_dialog_content = "你敢動一下，就和自己的腦袋說再見吧。",
  ui_story_5075_50751102_60_dialog_content = "PlayerName公子，你沒事吧？",
  ui_story_5075_50751102_61_dialog_content = "丹棠！阿玖！",
  ui_story_5075_50751102_62_dialog_content = "妳們……妳們怎麼……啊！",
  ui_story_5075_50751102_63_dialog_content = "<color=#e8d9bb>丹棠猛地扯了一把禮賓館主事官的臉。</color>",
  ui_story_5075_50751102_64_dialog_content = "<color=#e8d9bb>一張薄如蟬翼的面具脫落，從下面露出的，竟是另一張陌生的面容。</color>",
  ui_story_5075_50751102_65_dialog_content = "果然你並不是真正的禮賓館主事官，只是冒充他的身分。",
  ui_story_5075_50751102_66_dialog_content = "……就算你們抓了我也無濟於事。",
  ui_story_5075_50751102_67_dialog_content = "吾等主上智計無雙，吾等<color=#FFB400>駿命者</color>無處不在。",
  ui_story_5075_50751102_68_dialog_content = "事到如今，計畫臨近尾聲，海底的封印已破，沉睡的噩夢正甦醒！",
  ui_story_5075_50751102_69_dialog_content = "等皓津的秩序崩潰，吾等就可趁虛而入，不費吹灰之力將濟國收入囊中。",
  ui_story_5075_50751102_70_dialog_content = "除非有菩薩保佑，不然你們——咕唔！",
  ui_story_5075_50751102_71_dialog_content = "有人叫阿霓？",
  ui_story_5075_50751102_72_dialog_content = "咕……！噗唔！！！",
  ui_story_5075_50751102_73_dialog_content = "阿霓？妳怎麼也在這？",
  ui_story_5075_50751102_74_dialog_content = "阿霓不是在找破壞封印的犯人嗎，但之前那個人追著追著就不見了。",
  ui_story_5075_50751102_75_dialog_content = "於是阿霓乾脆順著味道，將那個人接觸過的傢伙、去過的地方都搜了一遍。",
  ui_story_5075_50751102_76_dialog_content = "這裡也是～",
  ui_story_5075_50751102_77_dialog_content = "咕咕！！唔——！",
  ui_story_5075_50751102_78_dialog_content = "而且，中途還遇見了糖人師傅。",
  ui_story_5075_50751102_79_dialog_content = "那個會做梅花糖的糖人師傅？！",
  ui_story_5075_50751102_80_dialog_content = "對！他好大方唷，供奉了阿霓一大把糖人。",
  ui_story_5075_50751102_81_dialog_content = "只許了一個願，請阿霓在去過的地方插一束梅花枝就好。",
  ui_story_5075_50751102_82_dialog_content = "那阿霓照做了嗎？",
  ui_story_5075_50751102_83_dialog_content = "當然，阿霓拿了供品，當然要言而有信。",
  ui_story_5075_50751102_84_dialog_content = "這間屋子外面也插了喔。",
  ui_story_5075_50751102_85_dialog_content = "太好了……丹棠！",
  ui_story_5075_50751102_86_dialog_content = "我在。",
  ui_story_5075_50751102_87_dialog_content = "我已從林家家主處拿到令牌，還得了林家護衛的掩護。",
  ui_story_5075_50751102_88_dialog_content = "現在護衛軍已在仲胥大人的指揮下就位，控制城內暗鬼和狂化祟靈。",
  ui_story_5075_50751102_89_dialog_content = "等巡檢司處理完這些所謂的駿命者後，也會加入支援。",
  ui_story_5075_50751102_90_dialog_content = "謝謝公子……一直記得丹棠中意的花。",
  ui_story_5075_50751102_91_dialog_content = "哈哈，成功了就好！外面現在怎麼樣了？",
  ui_story_5075_50751102_92_dialog_content = "城裡暫時撐得住，城外就需拜託月白了。",
  ui_story_5075_50751102_93_dialog_content = "關於城外，禮賓館主事官……就這個人剛剛說他們的計畫已接近尾聲。",
  ui_story_5075_50751102_94_dialog_content = "尤可能要徹底跟黑氣融合了。",
  ui_story_5075_50751102_95_dialog_content = "我們必須盡快行動，跟尤談一談！",
  ui_story_5075_50751102_96_dialog_content = "那就來這邊。",
  ui_story_5075_50751102_97_dialog_content = "我調來了一艘小舟，可以走水路直接通往海灣。",
  ui_story_5075_50751102_98_dialog_content = "城內就交給丹棠了，我跟月白一起去找尤……咦？",
  ui_story_5075_50751102_99_dialog_content = "龍女……大人？",
  ui_story_5075_50751102_100_dialog_content = "雖然不太懂，但破壞封印的傢伙，有人幫阿霓懲罰了對吧？",
  ui_story_5075_50751102_101_dialog_content = "阿霓也跟你一起去海邊～",
  ui_story_5075_50751102_102_dialog_content = "不然單憑空裔之力，恐難以對抗那物與尤所造之蜃境。",
  ui_story_5075_50751201_1_dialog_content = "<color=#e8d9bb>嘩啦！</color>",
  ui_story_5075_50751201_2_dialog_content = "唔……抱歉，我好像睡著了。我們到了嗎？月……",
  ui_story_5075_50751201_3_dialog_content = "咦？",
  ui_story_5075_50751201_4_dialog_content = "我剛剛，想叫誰的名字來著？",
  ui_story_5075_50751201_5_dialog_content = "說起來，我又是為什麼會坐在船上？",
  ui_story_5075_50751201_6_dialog_content = "嘶……頭好痛。",
  ui_story_5075_50751201_7_dialog_content = "喂，你又發什麼呆啊？快點下去接著搬貨啊！船馬上就要開了！",
  ui_story_5075_50751201_8_dialog_content = "搬、搬貨？我嗎？",
  ui_story_5075_50751201_9_dialog_content = "這也沒有別人啊。",
  ui_story_5075_50751201_10_dialog_content = "不是你自己說有個叫臨空什麼的家人生病，為了湊錢買藥才急著找零工嗎？",
  ui_story_5075_50751201_11_dialog_content = "唉……就是不知道他們說的這遠洋航行，還能不能平安回去。",
  ui_story_5075_50751201_12_dialog_content = "好在林家雖然是個小商會，這次出海給的工錢還是不少，還預付一半訂金呢。",
  ui_story_5075_50751201_13_dialog_content = "有了這筆錢，總算能讓老婆孩子吃點好料了。",
  ui_story_5075_50751201_14_dialog_content = "你家人也暫時不愁藥錢了吧。",
  ui_story_5075_50751201_15_dialog_content = "（總覺得哪裡不太對勁，又好像確實是這樣……）",
  ui_story_5075_50751201_16_dialog_content = "（嘶……頭又痛起來了。）",
  ui_story_5075_50751201_17_dialog_content = "（先搬貨吧。）",
  ui_story_5075_50751201_18_dialog_content = "<color=#e8d9bb>嘩啦！</color>",
  ui_story_5075_50751201_19_dialog_content = "嗯？怎麼回事？",
  ui_story_5075_50751201_20_dialog_content = "周圍怎麼突然起霧了？",
  ui_story_5075_50751201_21_dialog_content = "你餓昏頭了？這船開進霧裡都快半個月了，兜兜轉轉就是出不去。",
  ui_story_5075_50751201_22_dialog_content = "咱們這一船人怕是都要交代在這裡了。",
  ui_story_5075_50751201_23_dialog_content = "我老婆孩子還在等我回去，我不想死啊……",
  ui_story_5075_50751201_24_dialog_content = "<color=#e8d9bb>他的嘆息引來一陣附和的嗚咽。</color>",
  ui_story_5075_50751201_25_dialog_content = "<color=#e8d9bb>只見船伕與商人都橫七豎八地躺在甲板上，就連呼吸都帶著疲憊的絕望。</color>",
  ui_story_5075_50751201_26_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_5075_50751201_27_dialog_content = "（什麼東西撞上船了？！）",
  ui_story_5075_50751201_28_dialog_content = "快……快過來看啊！",
  ui_story_5075_50751201_29_dialog_content = "那些魚，是那些魚在下面推船！",
  ui_story_5075_50751201_30_dialog_content = "是螭龍魚！吉兆啊！現在是冬天，牠們是要回龍洲！",
  ui_story_5075_50751201_31_dialog_content = "跟著牠們，我們就有救了！！",
  ui_story_5075_50751201_32_dialog_content = "看見了嗎！簡直是神仙保佑！神仙保佑啊！",
  ui_story_5075_50751201_33_dialog_content = "（是錯覺嗎？為什麼最前面那條螭龍魚……看起來好眼熟？）",
  ui_story_5075_50751201_34_dialog_content = "<color=#e8d9bb>嘩啦！</color>",
  ui_story_5075_50751201_35_dialog_content = "我是……一條螭龍魚。",
  ui_story_5075_50751201_36_dialog_content = "平常在海裡遊蕩、捕食，偶爾向修習光能術的同類討教。",
  ui_story_5075_50751201_37_dialog_content = "每年冬天，則隨著族群一起返回故鄉——龍洲。",
  ui_story_5075_50751201_38_dialog_content = "那天，我們在海上發現一艘迷路的船。",
  ui_story_5075_50751201_39_dialog_content = "那艘船跟著我們一起返回龍洲，又和首領達成約定。",
  ui_story_5075_50751201_40_dialog_content = "往後每年我們溯游時，都要和那艘船一起。",
  ui_story_5075_50751201_41_dialog_content = "我們會順路領著船回家，他們則會為我們送上食物。",
  ui_story_5075_50751201_42_dialog_content = "這是互利的關係，我們應該高興。",
  ui_story_5075_50751201_43_dialog_content = "<color=#e8d9bb>嘩啦！</color>",
  ui_story_5075_50751201_44_dialog_content = "總管、總管？您又看著螭龍魚發呆了。",
  ui_story_5075_50751201_45_dialog_content = "我只是總覺得，有一條螭龍魚……很眼熟。",
  ui_story_5075_50751201_46_dialog_content = "那玩意不都一樣，有什麼好看的？不如來看看這個。",
  ui_story_5075_50751201_47_dialog_content = "這是您這趟出海的分紅。",
  ui_story_5075_50751201_48_dialog_content = "這也太多了吧？！",
  ui_story_5075_50751201_49_dialog_content = "自從林家開了遠洋航線，賺得越來越多，這點不過是小錢。",
  ui_story_5075_50751201_50_dialog_content = "您想不想再多賺點？",
  ui_story_5075_50751201_51_dialog_content = "還、還能多賺……？",
  ui_story_5075_50751201_52_dialog_content = "我來之前啊，跟其他人也都說好了，林家商會的規模現在越來越大。",
  ui_story_5075_50751201_53_dialog_content = "跟艾斯特拉等地交易的需求也越來越多。這一年跑一趟船根本供不上啊！",
  ui_story_5075_50751201_54_dialog_content = "你說咱們能不能聯合起來跟家主說說，再加一趟？",
  ui_story_5075_50751201_55_dialog_content = "一年跑兩趟就行，怎麼樣？",
  ui_story_5075_50751201_56_dialog_content = "但螭龍魚的習性不是只在每年冬季回龍洲？",
  ui_story_5075_50751201_57_dialog_content = "那平常牠們不就是在海裡四處亂游嘛，回龍洲一趟也無所謂啊。",
  ui_story_5075_50751201_58_dialog_content = "咱們賺了錢，也好買更多魚飼餵牠們，是不是？",
  ui_story_5075_50751201_59_dialog_content = "螭龍魚應該不在乎這些。",
  ui_story_5075_50751201_60_dialog_content = "嘖，你怎麼說不通呢。算了算了，其他人都願意，也不差你一個。",
  ui_story_5075_50751201_61_dialog_content = "等等，我不——",
  ui_story_5075_50751201_62_dialog_content = "<color=#e8d9bb>嘩啦！</color>",
  ui_story_5075_50751201_63_dialog_content = "首領說，之後每年的夏天我們也要回一次龍洲。",
  ui_story_5075_50751201_64_dialog_content = "夏天的海，很熱，不喜歡。",
  ui_story_5075_50751201_65_dialog_content = "但船上的朋友需要幫助。",
  ui_story_5075_50751201_66_dialog_content = "那就沒關係。",
  ui_story_5075_50751201_67_dialog_content = "只是要多游好遠，有點累。",
  ui_story_5075_50751201_68_dialog_content = "<color=#e8d9bb>嘩啦！</color>",
  ui_story_5075_50751201_69_dialog_content = "今天叫大家來，是想宣佈一件事。",
  ui_story_5075_50751201_70_dialog_content = "林家接下了一單央京的生意，為了完成需求，今年要臨時增加一趟遠航。",
  ui_story_5075_50751201_71_dialog_content = "請等一下，我們跟螭龍魚本來就只約好牠們每年幫忙一次而已。",
  ui_story_5075_50751201_72_dialog_content = "要牠們夏季回龍洲已經違背習性了，還要再加——",
  ui_story_5075_50751201_73_dialog_content = "這可是央京的訂單，多少商會夢寐以求。",
  ui_story_5075_50751201_74_dialog_content = "你知道接下這張單，之後能為林家帶來多少收益嗎？",
  ui_story_5075_50751201_75_dialog_content = "我知道這麼做委屈了螭龍魚，之後我會親自去找那祟靈道歉的。",
  ui_story_5075_50751201_76_dialog_content = "就這麼定了。",
  ui_story_5075_50751201_77_dialog_content = "<color=#e8d9bb>嘩啦！</color>",
  ui_story_5075_50751201_78_dialog_content = "今年，要往返三趟。",
  ui_story_5075_50751201_79_dialog_content = "首領說是暫時的，因為船上的朋友遇上了麻煩。",
  ui_story_5075_50751201_80_dialog_content = "但第二年，還是三次。第三年，還是三次。",
  ui_story_5075_50751201_81_dialog_content = "周圍的同族漸漸消失了。",
  ui_story_5075_50751201_82_dialog_content = "然後，首領也提前迎來了大限。",
  ui_story_5075_50751201_83_dialog_content = "今後，我就是新的首領。",
  ui_story_5075_50751201_84_dialog_content = "船上的朋友來了，他們將我帶上岸，放進一個木屋裡的大魚缸。",
  ui_story_5075_50751201_85_dialog_content = "魚缸很小，很難游。",
  ui_story_5075_50751201_86_dialog_content = "很難受。",
  ui_story_5075_50751201_87_dialog_content = "第四年，也是三次。",
  ui_story_5075_50751201_88_dialog_content = "但就算行船的時候，他們也不讓我在海裡游。",
  ui_story_5075_50751201_89_dialog_content = "他們將魚缸搬上船，每天送很多吃的給我，叫我對同族發號施令就好。",
  ui_story_5075_50751201_90_dialog_content = "他們說，這叫供奉。是對祟靈的禮節。",
  ui_story_5075_50751201_91_dialog_content = "已經能化形了嗎。",
  ui_story_5075_50751201_92_dialog_content = "……",
  ui_story_5075_50751201_93_dialog_content = "剛化形，還不會說話吧。",
  ui_story_5075_50751201_94_dialog_content = "你想不想學？我來教你。就當是對你們的賠罪……",
  ui_story_5075_50751201_95_dialog_content = "算了，對你說這些你也聽不懂。",
  ui_story_5075_50751201_96_dialog_content = "而且我對你們犯下的罪過，也不是假惺惺做這一兩件小事就能償清的。",
  ui_story_5075_50751201_97_dialog_content = "（我知道，他是船上人的首領。）",
  ui_story_5075_50751201_98_dialog_content = "（他教我說話，教我認字。）",
  ui_story_5075_50751201_99_dialog_content = "（但我也知道，他是一個很壞、很壞的人。）",
  ui_story_5075_50751201_100_dialog_content = "<color=#e8d9bb>嘩啦！</color>",
  ui_story_5075_50751201_101_dialog_content = "四次？！",
  ui_story_5075_50751201_102_dialog_content = "齊家最近正虎視眈眈地想和林家爭奪皇商的名號。",
  ui_story_5075_50751201_103_dialog_content = "我們要是不做些更顯赫的成績出來，恐怕會被擠下去。",
  ui_story_5075_50751201_104_dialog_content = "林家的百年榮耀不能毀在我們手上。",
  ui_story_5075_50751201_105_dialog_content = "從幾年前開始，螭龍魚的死亡率就異常攀升，您難道要當不知道嗎！",
  ui_story_5075_50751201_106_dialog_content = "那又如何？",
  ui_story_5075_50751201_107_dialog_content = "說什麼那又如何……我倒想問您還想怎樣！",
  ui_story_5075_50751201_108_dialog_content = "貨物不夠，便一年兩次。有緊急需求，便一年三次。",
  ui_story_5075_50751201_109_dialog_content = "現在就連林家這個皇商的名號，都成螭龍魚的責任了嗎？",
  ui_story_5075_50751201_110_dialog_content = "螭龍魚曾救我們於水火，林家卻根本在恩將仇報。",
  ui_story_5075_50751201_111_dialog_content = "請別把自己的貪婪說得這麼冠冕堂皇！",
  ui_story_5075_50751201_112_dialog_content = "……小PlayerName……",
  ui_story_5075_50751201_113_dialog_content = "嘶……剛剛那是？",
  ui_story_5075_50751201_114_dialog_content = "你拿著林家的工錢，卻是對螭龍魚更忠心啊。",
  ui_story_5075_50751201_115_dialog_content = "林家請不起你這種人，你走吧。",
  ui_story_5075_50751201_116_dialog_content = "我還要去商討第四次航船的事宜，你自己去找管事結月錢。",
  ui_story_5075_50751201_117_dialog_content = "……您一定要這麼做嗎？",
  ui_story_5075_50751201_118_dialog_content = "你想幹什麼？",
  ui_story_5075_50751201_119_dialog_content = "我要去把螭龍魚首領放回海裡。",
  ui_story_5075_50751201_120_dialog_content = "找到了！就是這個魚缸！",
  ui_story_5075_50751201_121_dialog_content = "抱歉，要先讓妳離開水一會，等到了海邊就……",
  ui_story_5075_50751201_122_dialog_content = "攔住他！",
  ui_story_5075_50751201_123_dialog_content = "怎麼突然這麼多人！得想辦法突破……",
  ui_story_5075_50751201_124_dialog_content = "強制感應！",
  ui_story_5075_50751201_125_dialog_content = "嗚哇！",
  ui_story_5075_50751201_126_dialog_content = "……咦？感應是……？",
  ui_story_5075_50751201_127_dialog_content = "小PlayerName！",
  ui_story_5075_50751201_128_dialog_content = "阿……霓？",
  ui_story_5075_50751201_129_dialog_content = "你總算注意到我啦。",
  ui_story_5075_50751201_130_dialog_content = "我們的船剛進海灣，你和小月白就一下子睡著了，怎麼戳都戳不醒。",
  ui_story_5075_50751201_131_dialog_content = "阿霓好無聊啊，你們快點醒過來嘛。",
  ui_story_5075_50751201_132_dialog_content = "我想起來了！進入海灣的瞬間，就有一大片黑氣撲面而來。",
  ui_story_5075_50751201_133_dialog_content = "所以是那份力量將我們拖進了這個……夢？還是幻境？",
  ui_story_5075_50751201_134_dialog_content = "嗯……都一樣吧。",
  ui_story_5075_50751201_135_dialog_content = "好隨便！",
  ui_story_5075_50751201_136_dialog_content = "有什麼關係？這又不重要。",
  ui_story_5075_50751201_137_dialog_content = "比起這個，你還是快去找小月白比較好喔。",
  ui_story_5075_50751201_138_dialog_content = "她看起來很難受的樣子。",
  ui_story_5075_50751201_139_dialog_content = "是黑氣侵蝕的關係嗎……阿霓妳能不能……",
  ui_story_5075_50751201_140_dialog_content = "可以是可以，但阿霓這次只幫到這裡。",
  ui_story_5075_50751201_141_dialog_content = "為什麼——",
  ui_story_5075_50751201_142_dialog_content = "凡事光指望求神，可不是什麼好習慣。",
  ui_story_5075_50751201_143_dialog_content = "自己的攤子，要自己收拾。",
  ui_story_5075_50751201_144_dialog_content = "……我知道了。",
  ui_story_5075_50751201_145_option_content = "感應！",
  ui_story_5075_50751201_146_dialog_content = "月白！妳究竟在哪……裡……？",
  ui_story_5075_50751201_147_dialog_content = "PlayerName。",
  ui_story_5075_50751201_148_dialog_content = "這條螭龍魚……是月白？！",
  ui_story_5075_50751201_149_dialog_content = "站住！",
  ui_story_5075_50751201_150_dialog_content = "又來？！",
  ui_story_5075_50751201_151_dialog_content = "……總之先往海邊逃吧！",
  ui_story_5075_50751201_152_dialog_content = "呼……呼……總算到了。",
  ui_story_5075_50751201_153_dialog_content = "為什麼在幻境裡也會這麼累？",
  ui_story_5075_50751201_154_dialog_content = "月白妳先到水裡去吧，然後……",
  ui_story_5075_50751201_155_dialog_content = "月白？！",
  ui_story_5075_50751201_156_dialog_content = "（她剛進去就不見了……）",
  ui_story_5075_50751201_157_dialog_content = "（水底……全是黑氣！）",
  ui_story_5075_50751201_158_dialog_content = "……",
  ui_story_5075_50751201_159_dialog_content = "（好累，首領，好餓，首領，好難受，首領。）",
  ui_story_5075_50751201_160_dialog_content = "（討厭，好想回去，首領，首領，首領，救救，救救。）",
  ui_story_5075_50751201_161_dialog_content = "（救救我們，救救……首領。）",
  ui_story_5075_50751201_162_dialog_content = "（是同族傳來的訊號。）",
  ui_story_5075_50751201_163_dialog_content = "（很雜，很亂，但全都來自牠們……來自螭龍魚的心聲。）",
  ui_story_5075_50751201_164_dialog_content = "那些、聲音。",
  ui_story_5075_50751201_165_dialog_content = "每、天、響。",
  ui_story_5075_50751201_166_dialog_content = "一、直、響。",
  ui_story_5075_50751201_167_dialog_content = "牠、們、恨。",
  ui_story_5075_50751201_168_dialog_content = "尤。",
  ui_story_5075_50751201_169_dialog_content = "原來如此。",
  ui_story_5075_50751201_170_dialog_content = "我剛剛經歷的，是你的記憶嗎。",
  ui_story_5075_50751201_171_dialog_content = "林、家。",
  ui_story_5075_50751201_172_dialog_content = "叛、徒。",
  ui_story_5075_50751201_173_dialog_content = "人、無、信。",
  ui_story_5075_50751201_174_dialog_content = "你、也、是、魚。",
  ui_story_5075_50751201_175_dialog_content = "該、恨！",
  ui_story_5075_50751201_176_dialog_content = "月白！聽得到我的聲音嗎！",
  ui_story_5075_50751201_177_dialog_content = "我馬上去找妳！",
  ui_story_5075_50751201_178_dialog_content = "不必了，PlayerName。",
  ui_story_5075_50751201_179_dialog_content = "咦？",
  ui_story_5075_50751201_180_dialog_content = "林家確實愧對於尤。",
  ui_story_5075_50751201_181_dialog_content = "而我如今代表林家而來，所以尤有資格恨我，向我討債。",
  ui_story_5075_50751201_182_dialog_content = "……",
  ui_story_5075_50751201_183_dialog_content = "黑氣，停下來了？",
  ui_story_5075_50751201_184_dialog_content = "不……對……",
  ui_story_5075_50751201_185_dialog_content = "我……不……",
  ui_story_5075_50751201_186_dialog_content = "尤怎麼了？好像突然很痛苦的樣子……",
  ui_story_5075_50751201_187_dialog_content = "因為這並非牠真正的意志。",
  ui_story_5075_50751201_188_dialog_content = "我所知道的尤，關心同族，關心朋友，不會因恨意就將其他祟靈牽扯進來。",
  ui_story_5075_50751201_189_dialog_content = "而且，也並不是所有人都像林家前人一般可憎。",
  ui_story_5075_50751201_190_dialog_content = "剛剛PlayerName所做的事，你也見到了。",
  ui_story_5075_50751201_191_dialog_content = "如果他當時真的在林家……一定也會作出一樣的行動。",
  ui_story_5075_50751201_192_dialog_content = "……",
  ui_story_5075_50751201_193_dialog_content = "林家已經困住你太久。",
  ui_story_5075_50751201_194_dialog_content = "我不會再讓你被別人強加的恨意所困。",
  ui_story_5075_50751201_195_dialog_content = "螭龍魚的聲音，我也聽到了。",
  ui_story_5075_50751201_196_dialog_content = "我會把你救出來。",
  ui_story_5075_50751201_197_dialog_content = "不、對！",
  ui_story_5075_50751201_198_dialog_content = "恨、是、我！",
  ui_story_5075_50751201_199_dialog_content = "你、也、是。",
  ui_story_5075_50751201_200_dialog_content = "<size=45>叛、徒！</size>",
  ui_story_5075_50751202_1_dialog_content = "好耶～你們終於都醒啦，賴床的孩子容易長不高喔。",
  ui_story_5075_50751202_2_dialog_content = "是嗎……我現在開始早睡早起，還能再長高嗎？",
  ui_story_5075_50751202_3_dialog_content = "你可以試著拜阿霓喔～",
  ui_story_5075_50751202_4_dialog_content = "小月白也可以來拜拜。",
  ui_story_5075_50751202_5_dialog_content = "我已經不是小孩子了。",
  ui_story_5075_50751202_6_dialog_content = "和阿霓比起來，妳還小得很呢。",
  ui_story_5075_50751202_7_dialog_content = "所以別老皺著眉頭，不就是小尤不跟你打架，中途跑了而已嘛。",
  ui_story_5075_50751202_8_dialog_content = "只要牠還在水裡，想叫牠出來還不簡單？",
  ui_story_5075_50751202_9_dialog_content = "<color=#e8d9bb>阿霓突然抬手，向海中打出一道金光。</color>",
  ui_story_5075_50751202_10_dialog_content = "我是不是最好別問妳剛才做了什麼？",
  ui_story_5075_50751202_11_dialog_content = "反正已經用不了了，阿霓就把剩下的封印也解開啦。",
  ui_story_5075_50751202_12_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5075_50751202_13_dialog_content = "<color=#e8d9bb>方才平靜的海面猛然翻騰起來，驚濤四起。</color>",
  ui_story_5075_50751202_14_dialog_content = "<color=#e8d9bb>一道黑影從海中升至半空。</color>",
  ui_story_5075_50751202_15_dialog_content = "<color=#e8d9bb>無邊無際的黑氣從滿佈漩渦的海面破騰而出。</color>",
  ui_story_5075_50751202_16_dialog_content = "那就是你們一直在說的小尤？確實是很小呢。",
  ui_story_5075_50751202_17_dialog_content = "我、知、道、妳。",
  ui_story_5075_50751202_18_dialog_content = "辰、龍。",
  ui_story_5075_50751202_19_dialog_content = "透過怨力中的意識知道的嗎？真難為牠記這麼久。",
  ui_story_5075_50751202_20_dialog_content = "我、報、仇。",
  ui_story_5075_50751202_21_dialog_content = "妳、別、出、手。",
  ui_story_5075_50751202_22_dialog_content = "否、則。",
  ui_story_5075_50751202_23_dialog_content = "淹、城。",
  ui_story_5075_50751202_24_dialog_content = "難道你……",
  ui_story_5075_50751202_25_dialog_content = "（第一次見到阿霓這麼凝重的表情。）",
  ui_story_5075_50751202_26_dialog_content = "（就連她都拿尤沒辦法嗎……）",
  ui_story_5075_50751202_27_dialog_content = "牠的意思是，如果阿霓出手，就要用洪水淹沒整座皓津？",
  ui_story_5075_50751202_28_dialog_content = "牠要拿全城的百姓當人質。",
  ui_story_5075_50751202_29_dialog_content = "所以這果然……",
  ui_story_5075_50751202_30_dialog_content = "是在威脅阿霓嗎！",
  ui_story_5075_50751202_31_dialog_content = "咦？",
  ui_story_5075_50751202_32_dialog_content = "好幾百年沒被威脅過了，好新鮮啊！",
  ui_story_5075_50751202_33_dialog_content = "不過仔細想想，這件事本來也就跟阿霓沒關係嘛。",
  ui_story_5075_50751202_34_dialog_content = "雖然過程好像很複雜，阿霓看不太懂。",
  ui_story_5075_50751202_35_dialog_content = "但破壞封印的是人，小尤會產生恨意，也是人和祟靈的問題。",
  ui_story_5075_50751202_36_dialog_content = "那就該讓人和祟靈自己解決。",
  ui_story_5075_50751202_37_dialog_content = "嗯，阿霓很講道理的！",
  ui_story_5075_50751202_38_dialog_content = "這種時候不用這麼講道理啦！",
  ui_story_5075_50751202_39_dialog_content = "不過呢，雖然感覺很新鮮，但阿霓不高興被人威脅。",
  ui_story_5075_50751202_40_dialog_content = "所以——",
  ui_story_5075_50751202_41_dialog_content = "（阿霓怎麼突然飛走了？還飛到尤身邊去了。）",
  ui_story_5075_50751202_42_dialog_content = "咚咚～",
  ui_story_5075_50751202_43_dialog_content = "<color=#e8d9bb>阿霓抬起拳頭，輕敲了一下尤的腦袋。</color>",
  ui_story_5075_50751202_44_dialog_content = "阿霓出手啦，你要怎麼樣？",
  ui_story_5075_50751202_45_dialog_content = "阿霓？！",
  ui_story_5075_50751202_46_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_5075_50751202_47_dialog_content = "<color=#e8d9bb>宛如要代替尤表達憤怒一般，海面轟然炸開。</color>",
  ui_story_5075_50751202_48_dialog_content = "<color=#e8d9bb>一層層的巨浪被掀起後就不曾落下，在響徹四周的濤聲中越漲越高。</color>",
  ui_story_5075_50751202_49_dialog_content = "<color=#e8d9bb>一行人所站的海灘也被浪濤飛速淹沒。</color>",
  ui_story_5075_50751202_50_dialog_content = "這樣下去我們會先被淹死吧！",
  ui_story_5075_50751202_51_dialog_content = "沒關係，我水性很好。溺水了就叫我，我會拉住你。",
  ui_story_5075_50751202_52_dialog_content = "一開始就不要溺水比較好啦！",
  ui_story_5075_50751202_53_dialog_content = "啊，差點忘了你們兩個。",
  ui_story_5075_50751202_54_dialog_content = "（身體突然騰空了？！）",
  ui_story_5075_50751202_55_dialog_content = "怎麼樣，我的神通術很方便吧？",
  ui_story_5075_50751202_56_dialog_content = "尤呢？",
  ui_story_5075_50751202_57_dialog_content = "不是說要<color=#FFB400>淹城</color>嘛，牠現在正往皓津去。",
  ui_story_5075_50751202_58_dialog_content = "這、這不是往更糟糕的方向發展了嗎！",
  ui_story_5075_50751202_59_dialog_content = "阿霓妳為什麼要激牠啊……",
  ui_story_5075_50751202_60_dialog_content = "別那麼緊張，小PlayerName。",
  ui_story_5075_50751202_61_dialog_content = "阿霓活了很久很久，也看了龍洲的生靈很久很久。",
  ui_story_5075_50751202_62_dialog_content = "不管是小尤，還是你。",
  ui_story_5075_50751202_63_dialog_content = "都太小看他們了。",
  ui_story_5075_50751301_1_dialog_content = "急急如律——",
  ui_story_5075_50751301_2_dialog_content = "嗷！",
  ui_story_5075_50751301_3_dialog_content = "唉，打暈這個又醒了那個。",
  ui_story_5075_50751301_4_dialog_content = "城裡的黑氣也越來越濃，都開始懷念看不見牠們的時候了。",
  ui_story_5075_50751301_5_dialog_content = "光用繩子已經綁不住狂化的祟靈。要是我也能祛除牠們體內的怨力……",
  ui_story_5075_50751301_6_dialog_content = "借過、借過！藥來了！",
  ui_story_5075_50751301_7_dialog_content = "你，你在給祟靈餵藥？",
  ui_story_5075_50751301_8_dialog_content = "這不是很明顯嗎？",
  ui_story_5075_50751301_9_dialog_content = "但牠們失去理智不是因為生病，而是被怨力侵蝕——",
  ui_story_5075_50751301_10_dialog_content = "在你眼裡，醫生就只能治病嗎？",
  ui_story_5075_50751301_11_dialog_content = "既然那種力量一定要進入祟靈體內才能發揮作用，就可以視為一種毒。",
  ui_story_5075_50751301_12_dialog_content = "是毒，就一定有解方。",
  ui_story_5075_50751301_13_dialog_content = "這滿城的黑氣無孔不入，連小尾巴……我哥哥都受到了影響。",
  ui_story_5075_50751301_14_dialog_content = "不過我從師父那裡求來一帖調理光能的藥給他喝，他的狀態就好多了。",
  ui_story_5075_50751301_15_dialog_content = "所以我才跑出來幫忙的。",
  ui_story_5075_50751301_16_dialog_content = "哈！",
  ui_story_5075_50751301_17_dialog_content = "哥哥……是嗎？你也是<color=#FFB400>祟靈</color>啊。",
  ui_story_5075_50751301_18_dialog_content = "怎麼，你也對祟靈有意見？",
  ui_story_5075_50751301_19_dialog_content = "沒有沒有！我是在想，你真是個了不起的醫生啊。",
  ui_story_5075_50751301_20_dialog_content = "你真的這麼想？嘿嘿，算你有眼光。",
  ui_story_5075_50751301_21_dialog_content = "但我也沒那麼了不起……",
  ui_story_5075_50751301_22_dialog_content = "我是帶著藥出來了，但祟靈東跑西竄，我很難找到時機餵藥。",
  ui_story_5075_50751301_23_dialog_content = "這個就交給我吧！",
  ui_story_5075_50751301_24_dialog_content = "只要見到祟靈就把牠們一拳打暈，帶來讓你餵藥！",
  ui_story_5075_50751301_25_dialog_content = "噓！噓！別太大聲！",
  ui_story_5075_50751301_26_dialog_content = "我們是瞞著家裡人跑出來的，要是被發現就麻煩了。",
  ui_story_5075_50751301_27_dialog_content = "喔，我懂！我小時候也常幹這種事。",
  ui_story_5075_50751301_28_dialog_content = "放心，我替你把風，保證不讓你被人發現。",
  ui_story_5075_50751301_29_dialog_content = "我叫羅松。這是阿丁，我的搭檔。",
  ui_story_5075_50751301_30_dialog_content = "嗷！",
  ui_story_5075_50751301_31_dialog_content = "我叫厘青。這是小尾巴，我的哥哥。",
  ui_story_5075_50751301_32_dialog_content = "哈！",
  ui_story_5075_50751301_33_dialog_content = "合作愉快！",
  ui_story_5075_50751301_34_dialog_content = "哈嗷！",
  ui_story_5075_50751301_35_dialog_content = "吱！",
  ui_story_5075_50751301_36_dialog_content = "厘青醫生，你在這裡等我，我去看看！",
  ui_story_5075_50751301_37_dialog_content = "哎等等——",
  ui_story_5075_50751301_38_dialog_content = "怎麼這麼急性子啊。",
  ui_story_5075_50751301_39_dialog_content = "救……救命啊——！",
  ui_story_5075_50751301_40_dialog_content = "你，你別過來！我手裡的棍子也不是吃素的！",
  ui_story_5075_50751301_41_dialog_content = "吱！",
  ui_story_5075_50751301_42_dialog_content = "你們這些妖怪，別以為我們好欺負！喝啊——！",
  ui_story_5075_50751301_43_dialog_content = "都住手！嘶——",
  ui_story_5075_50751301_44_dialog_content = "羅松！",
  ui_story_5075_50751301_45_dialog_content = "你在幹什麼傻事！誰叫你衝到中間去的！",
  ui_story_5075_50751301_46_dialog_content = "這下好了，肩膀挨了一棍子，肚子挨了一爪子。",
  ui_story_5075_50751301_47_dialog_content = "哈哈，我看一時情急嘛。",
  ui_story_5075_50751301_48_dialog_content = "我沒事，你先餵這隻祟靈吃藥吧，我剛才抓住牠了。",
  ui_story_5075_50751301_49_dialog_content = "……真不知道你是細心還是粗心。",
  ui_story_5075_50751301_50_dialog_content = "你、我……對、對不起……打了你……",
  ui_story_5075_50751301_51_dialog_content = "沒關係，是我自己突然衝出來的。",
  ui_story_5075_50751301_52_dialog_content = "但、但那是祟靈啊！你幹嘛要護著牠？",
  ui_story_5075_50751301_53_dialog_content = "你怎麼不說他是護著你呢？",
  ui_story_5075_50751301_54_dialog_content = "啊……",
  ui_story_5075_50751301_55_dialog_content = "突然被祟靈襲擊，誰都會反擊。但祟靈也不是自願襲擊人的。",
  ui_story_5075_50751301_56_dialog_content = "都是無辜受害而已。",
  ui_story_5075_50751301_57_dialog_content = "既然沒有誰做錯，就不該有人受傷。",
  ui_story_5075_50751301_58_dialog_content = "這不是理所當然的嗎？",
  ui_story_5075_50751301_59_dialog_content = "好了，餵完藥，這隻祟靈也好一點了。",
  ui_story_5075_50751301_60_dialog_content = "我們也跑了大半個皓津城了，大部分祟靈我們應該都經手過了吧。",
  ui_story_5075_50751301_61_dialog_content = "咕。",
  ui_story_5075_50751301_62_dialog_content = "看到沒？牠們是受外力控制才會傷人的，只要恢復正常就沒事了。",
  ui_story_5075_50751301_63_dialog_content = "……如果是別人跟我說，我應該不會相信。",
  ui_story_5075_50751301_64_dialog_content = "但你說的，我信。",
  ui_story_5075_50751301_65_dialog_content = "多謝救命之恩！我也會告訴別人這件事，叫大家發現祟靈傷人就來找你。",
  ui_story_5075_50751301_66_dialog_content = "真的嗎？那太好了！",
  ui_story_5075_50751301_67_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_5075_50751301_68_dialog_content = "怎麼回事？天怎麼突然變得這麼黑？",
  ui_story_5075_50751301_69_dialog_content = "<color=#e8d9bb>啪嗒。</color>",
  ui_story_5075_50751301_70_dialog_content = "下雨了？",
  ui_story_5075_50751301_71_dialog_content = "等等，這不是下雨。",
  ui_story_5075_50751301_72_dialog_content = "<size=45>天也不是黑了，是被一大片巨浪擋住了。</size>",
  ui_story_5075_50751301_73_dialog_content = "<size=45>這是要淹沒皓津嗎？！</size>",
  ui_story_5075_50751302_1_dialog_content = "<color=#e8d9bb>街道上擠滿了驚慌逃竄的人群。</color>",
  ui_story_5075_50751302_2_dialog_content = "妖魔！是妖魔帶著洪水要淹死我們！",
  ui_story_5075_50751302_3_dialog_content = "快跑啊——",
  ui_story_5075_50751302_4_dialog_content = "龍女娘娘保佑，龍女娘娘保佑……",
  ui_story_5075_50751302_5_dialog_content = "這已經不是人能解決的問題了。",
  ui_story_5075_50751302_6_dialog_content = "阿霓！放我們下去吧，至少過去幫忙疏散人群也好。",
  ui_story_5075_50751302_7_dialog_content = "辰霓大人。",
  ui_story_5075_50751302_8_dialog_content = "嗯……阿霓覺得不用喔。",
  ui_story_5075_50751302_9_dialog_content = "可是——",
  ui_story_5075_50751302_10_dialog_content = "小PlayerName，用心聽。",
  ui_story_5075_50751302_11_dialog_content = "啊！被路磚絆倒了……好痛。",
  ui_story_5075_50751302_12_dialog_content = "這裡是哪裡啊……阿爹呢？阿娘呢？",
  ui_story_5075_50751302_13_dialog_content = "嗚……",
  ui_story_5075_50751302_14_dialog_content = "嘎！",
  ui_story_5075_50751302_15_dialog_content = "啊！救、救命——！",
  ui_story_5075_50751302_16_dialog_content = "吱！",
  ui_story_5075_50751302_17_dialog_content = "<color=#e8d9bb>暗鬼攻擊落下的前一刻，祟靈衝過去撞開了暗鬼。</color>",
  ui_story_5075_50751302_18_dialog_content = "<color=#e8d9bb>攻擊偏移了半分落空。</color>",
  ui_story_5075_50751302_19_dialog_content = "你是……",
  ui_story_5075_50751302_20_dialog_content = "這個不夠響，再來一個！",
  ui_story_5075_50751302_21_dialog_content = "放鞭炮、驅祟獸，趕得霉運嗷嗷叫！",
  ui_story_5075_50751302_22_dialog_content = "吱……",
  ui_story_5075_50751302_23_dialog_content = "你是那時候的……",
  ui_story_5075_50751302_24_dialog_content = "嘎！",
  ui_story_5075_50751302_25_dialog_content = "小心！",
  ui_story_5075_50751302_26_dialog_content = "<color=#e8d9bb>小男孩猛撲過去，抱著小祟靈滾在滿是泥濘的地上。</color>",
  ui_story_5075_50751302_27_dialog_content = "阿丁出擊——",
  ui_story_5075_50751302_28_dialog_content = "咕……",
  ui_story_5075_50751302_29_dialog_content = "嗯？你是之前的小孩？",
  ui_story_5075_50751302_30_dialog_content = "水……水要落下來了——！",
  ui_story_5075_50751302_31_dialog_content = "吱！",
  ui_story_5075_50751302_32_dialog_content = "等等，別丟下我——",
  ui_story_5075_50751302_33_dialog_content = "<color=#e8d9bb>恍若天崩。</color>",
  ui_story_5075_50751302_34_dialog_content = "<color=#e8d9bb>伴隨聲勢浩大的轟鳴，巨浪終於從上空砸落。</color>",
  ui_story_5075_50751302_35_dialog_content = "<color=#e8d9bb>在壓倒性的力量面前，光靈在地上築起的渺小城池，根本無法逃脫。</color>",
  ui_story_5075_50751302_36_dialog_content = "啊啊啊——！",
  ui_story_5075_50751302_37_dialog_content = "……",
  ui_story_5075_50751302_38_dialog_content = "沒、沒事？為什麼？",
  ui_story_5075_50751302_39_dialog_content = "……抬頭看看吧。",
  ui_story_5075_50751302_40_dialog_content = "吱！",
  ui_story_5075_50751302_41_dialog_content = "<color=#e8d9bb>小祟靈浮在半空中，從上方撐起一塊無形的屏障。</color>",
  ui_story_5075_50751302_42_dialog_content = "<color=#e8d9bb>將近在眼前的浪潮阻隔在外。</color>",
  ui_story_5075_50751302_43_dialog_content = "<color=#e8d9bb>壓力讓牠渾身顫抖，但牠依舊拼命抬起小小的爪子，撐起那一方屏障。</color>",
  ui_story_5075_50751302_44_dialog_content = "<color=#e8d9bb>然後，不遠處又浮起另一塊屏障。</color>",
  ui_story_5075_50751302_45_dialog_content = "嗷！",
  ui_story_5075_50751302_46_dialog_content = "<color=#e8d9bb>然後，又一塊。</color>",
  ui_story_5075_50751302_47_dialog_content = "<color=#e8d9bb>祟靈紛紛撐起屏障，連綴成片。</color>",
  ui_story_5075_50751302_48_dialog_content = "<color=#e8d9bb>重若千鈞的波濤傾力壓下，卻在皓津上空，半寸不進。</color>",
  ui_story_5075_50751302_49_dialog_content = "那是……",
  ui_story_5075_50751302_50_dialog_content = "這片天地，從來就不是光靈所獨有。",
  ui_story_5075_50751302_51_dialog_content = "祟靈，也總要維護自己的家嘛。",
  ui_story_5075_50751302_52_dialog_content = "就算林家的老頭子不去相求，尤也會為了朋友去探查封印，一樣的道理。",
  ui_story_5075_50751302_53_dialog_content = "哪怕光靈不願意承認，自己腳下的土地也有祟靈的份。",
  ui_story_5075_50751302_54_dialog_content = "小PlayerName，你聽見了嗎？",
  ui_story_5075_50751302_55_dialog_content = "嗯，我聽見了。",
  ui_story_5075_50751302_56_dialog_content = "而且，大家都應該聽見。",
  ui_story_5075_50751302_57_dialog_content = "傳個話不算幫忙，這我倒是可以稍微出出力～",
  ui_story_5075_50751302_58_dialog_content = "來吧——",
  ui_story_5075_50751302_59_option_content = "感應！",
  ui_story_5075_50751302_60_dialog_content = "兩條腿的人，很壞，總是見到我們就踢一腳。",
  ui_story_5075_50751302_61_dialog_content = "但是兩條腿的人，也很好，他們能抓到很好吃的獵物。",
  ui_story_5075_50751302_62_dialog_content = "有時候還會分給我們吃。",
  ui_story_5075_50751302_63_dialog_content = "這、這是什麼？",
  ui_story_5075_50751302_64_dialog_content = "是祟靈的……聲音？",
  ui_story_5075_50751302_65_dialog_content = "被用燙的東西炸，很可怕。",
  ui_story_5075_50751302_66_dialog_content = "被趕走，很可怕。",
  ui_story_5075_50751302_67_dialog_content = "明明這裡也是我們的家。",
  ui_story_5075_50751302_68_dialog_content = "但……但是我們也很害怕啊！動不動就偷走東西，毀壞糧食……",
  ui_story_5075_50751302_69_dialog_content = "還能變我們不會的戲法！我、我們應付不來啊！",
  ui_story_5075_50751302_70_dialog_content = "兩條腿的人，笨。東西丟在牆角，找不到，怪我們。",
  ui_story_5075_50751302_71_dialog_content = "兩條腿的人，很笨，食物在院子裡，不留記號，被別人吃掉。",
  ui_story_5075_50751302_72_dialog_content = "但是兩條腿的人，也很聰明。上次腿壞了，被他們用板子夾夾，就好了。",
  ui_story_5075_50751302_73_dialog_content = "我們是不是對牠們太過分了……",
  ui_story_5075_50751302_74_dialog_content = "是啊，說是祟靈，但其實也只是剛懂事的野獸。",
  ui_story_5075_50751302_75_dialog_content = "又笨，又聰明。很壞，又很好。又打我們，又道歉。兩條腿的人，很奇怪。",
  ui_story_5075_50751302_76_dialog_content = "但是沒辦法呀。",
  ui_story_5075_50751302_77_dialog_content = "沒辦法呀。",
  ui_story_5075_50751302_78_dialog_content = "誰叫我們住在同一個家。",
  ui_story_5075_50751302_79_dialog_content = "水來了，他們跑不掉。",
  ui_story_5075_50751302_80_dialog_content = "水來了，家也跑不掉。",
  ui_story_5075_50751302_81_dialog_content = "大水是壞東西，快走開——",
  ui_story_5075_50751302_82_dialog_content = "不許進……",
  ui_story_5075_50751302_83_dialog_content = "<size=45>我們的家！</size>",
  ui_story_5075_50751302_84_dialog_content = "<color=#e8d9bb>籠罩住全城的屏障上突然金光流轉，遲遲未落的巨浪被倏然轟散。</color>",
  ui_story_5075_50751302_85_dialog_content = "<color=#e8d9bb>化作一場鹹澀的雨，無聲地灑入皓津。</color>",
  ui_story_5075_50751302_86_dialog_content = "剛才的雨……也是阿霓幫了忙吧？",
  ui_story_5075_50751302_87_dialog_content = "什～麼～",
  ui_story_5075_50751302_88_dialog_content = "不……沒什麼。",
  ui_story_5075_50751302_89_dialog_content = "那些小祟靈，真厲害啊。",
  ui_story_5075_50751302_90_dialog_content = "接下來，就只剩下尤了。",
  ui_story_5075_50751302_91_dialog_content = "……",
  ui_story_5075_50751302_92_dialog_content = "你也聽見了吧，那些人和祟靈的心聲。",
  ui_story_5075_50751302_93_dialog_content = "雖然他們會有誤會，會有摩擦，甚至會因為各種原因而互相傷害。",
  ui_story_5075_50751302_94_dialog_content = "但也同樣有過合作，有過互助，有過共用同一片土地的時光。",
  ui_story_5075_50751302_95_dialog_content = "他們只是同樣生於龍洲的生靈，並沒有誰天然對另一方抱有惡意。",
  ui_story_5075_50751302_96_dialog_content = "所以至少，不要徹底讓祟靈和光靈變成你死我活的關係。",
  ui_story_5075_50751302_97_dialog_content = "還有……",
  ui_story_5075_50751302_98_dialog_content = "剛才那些心聲裡，也有對你道歉的聲音吧。",
  ui_story_5075_50751302_99_dialog_content = "尤。",
  ui_story_5075_50751302_100_dialog_content = "對不起。",
  ui_story_5075_50751401_1_dialog_content = "道、歉。",
  ui_story_5075_50751401_2_dialog_content = "為、什、麼。",
  ui_story_5075_50751401_3_dialog_content = "明、明。",
  ui_story_5075_50751401_4_dialog_content = "不、後、悔。",
  ui_story_5075_50751401_5_dialog_content = "不……嗚……！",
  ui_story_5075_50751401_6_dialog_content = "牠飛回海灣了！我們快追上去！",
  ui_story_5075_50751401_7_dialog_content = "尤！",
  ui_story_5075_50751401_8_dialog_content = "因為一兩句話就動搖，真是個廢物！",
  ui_story_5075_50751401_9_dialog_content = "不……嗚……！",
  ui_story_5075_50751401_10_dialog_content = "若是你的恨不過這種程度，乾脆將軀體全交給吾！",
  ui_story_5075_50751401_11_dialog_content = "尤……是在試圖掙脫操控！",
  ui_story_5075_50751401_12_dialog_content = "（現在的話，說不定有機可乘！）",
  ui_story_5075_50751401_13_dialog_content = "哼，這個軀體資質尚可，但意志太過薄弱。",
  ui_story_5075_50751401_14_dialog_content = "身為祟靈，卻被光靈玩弄於股掌之間，可恥。",
  ui_story_5075_50751401_15_dialog_content = "好久不見，辰霓。",
  ui_story_5075_50751401_16_dialog_content = "咦？其實也沒有很久吧，好像只是睡了兩覺的功夫。",
  ui_story_5075_50751401_17_dialog_content = "妳還是一如既往。",
  ui_story_5075_50751401_18_dialog_content = "對我們來說，就算想變也很難吧。",
  ui_story_5075_50751401_19_dialog_content = "倒是這人世間變了不少，你一直待在海底一定沒見過。",
  ui_story_5075_50751401_20_dialog_content = "有自動尋人的機關鳥，有色彩豔麗的西洋畫，還有靠自己就能跨越大海的船。",
  ui_story_5075_50751401_21_dialog_content = "哼……造物再花哨，也不過是低級生命。",
  ui_story_5075_50751401_22_dialog_content = "你要用壽命長短來衡量生命價值嗎？",
  ui_story_5075_50751401_23_dialog_content = "但這樣說起來，你不覺得奇怪嗎？",
  ui_story_5075_50751401_24_dialog_content = "光靈明明壽命短暫，但現在佔據這片大陸，無處不在的，是他們。",
  ui_story_5075_50751401_25_dialog_content = "倒是你口中，你我這樣的高級生命，很難才見到一個呢。",
  ui_story_5075_50751401_26_dialog_content = "妳要如此自貶身分？",
  ui_story_5075_50751401_27_dialog_content = "吾等祟靈皆為<color=#FFB400>「始祖」</color>嫡親後代，尊貴無比，低賤的光靈怎可與吾等相提並論！",
  ui_story_5075_50751401_28_dialog_content = "如今，甚至就連一個毫無力量的光靈都能將祟靈當做玩物羞辱。",
  ui_story_5075_50751401_29_dialog_content = "同族這等處境，妳竟能視而不見？！",
  ui_story_5075_50751401_30_dialog_content = "祟靈的力量，祟靈的血統，皆淩駕於光靈之上。",
  ui_story_5075_50751401_31_dialog_content = "吾等何需紆尊降貴，與他們共用龍洲！",
  ui_story_5075_50751401_32_option_content = "強制感應！",
  ui_story_5075_50751401_33_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5075_50751401_34_dialog_content = "強制感應！",
  ui_story_5075_50751401_35_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5075_50751401_36_dialog_content = "（不行，只能模模糊糊地感覺到尤本人的存在，卻怎麼也連不上。）",
  ui_story_5075_50751401_37_dialog_content = "PlayerName，能不能將我的意志傳達給尤？",
  ui_story_5075_50751401_38_dialog_content = "我會全力一試！但我不確定尤現在聽不聽得見我們的聲音。",
  ui_story_5075_50751401_39_dialog_content = "沒關係。",
  ui_story_5075_50751401_40_dialog_content = "能在深海中自在暢遊的螭龍魚，不會如此輕易地被「淹沒」。",
  ui_story_5075_50751401_41_dialog_content = "好，那做好準備。",
  ui_story_5075_50751401_42_option_content = "強制感應！",
  ui_story_5075_50751401_43_dialog_content = "尤，聽得到嗎？",
  ui_story_5075_50751401_44_dialog_content = "……",
  ui_story_5075_50751401_45_dialog_content = "我來之前，家主告訴過我，他過去未曾親口向你道過歉。",
  ui_story_5075_50751401_46_dialog_content = "因為他說道歉，是要逼迫你用自己的寬和去包容他的卑劣。",
  ui_story_5075_50751401_47_dialog_content = "而他既然明知故犯，也接納這一切罪過帶來的繁榮，就沒資格請求原諒。",
  ui_story_5075_50751401_48_dialog_content = "林家也是如此。",
  ui_story_5075_50751401_49_dialog_content = "如果你覺得有著螭龍魚血統的我也是叛徒，那麼自然也可以包括我。",
  ui_story_5075_50751401_50_dialog_content = "我們接受你的復仇。",
  ui_story_5075_50751401_51_dialog_content = "但必須是尤。必須是沒被他人操控的真正的你，親自來復仇。",
  ui_story_5075_50751401_52_dialog_content = "你身為螭龍魚族的恨意，難道輕浮到就這樣交給他人也無所謂嗎！",
  ui_story_5075_50751401_53_dialog_content = "不、要。",
  ui_story_5075_50751401_54_dialog_content = "有回應了！",
  ui_story_5075_50751401_55_dialog_content = "尤，接下來我要試著趕走控制你身體的那道殘念。",
  ui_story_5075_50751401_56_dialog_content = "麻煩你配合了。",
  ui_story_5075_50751401_57_dialog_content = "小PlayerName和小月白可真慢啊。",
  ui_story_5075_50751401_58_dialog_content = "妳在說什麼？",
  ui_story_5075_50751401_59_dialog_content = "阿霓在說，不想再跟你聊這種沒意思的天了。",
  ui_story_5075_50751401_60_dialog_content = "妳……",
  ui_story_5075_50751401_61_dialog_content = "別裝了。你並非吾之同族。",
  ui_story_5075_50751401_62_dialog_content = "你並非吾之同族。",
  ui_story_5075_50751401_63_dialog_content = "！",
  ui_story_5075_50751401_64_dialog_content = "阿霓剛醒的時候，曾試過送出訊號聯絡同族。",
  ui_story_5075_50751401_65_dialog_content = "但大家都在睡覺，龍洲、雲島，無論遠近，回應者寥寥無幾。",
  ui_story_5075_50751401_66_dialog_content = "所以阿霓才會和頂著黑龍氣息的你搭話。",
  ui_story_5075_50751401_67_dialog_content = "但你根本不是黑龍，只是一團偷了所憑軀體記憶的陰鬱情緒而已。",
  ui_story_5075_50751401_68_dialog_content = "你讓黑龍心中只剩下傲慢，讓小尤心裡只留下恨意。",
  ui_story_5075_50751401_69_dialog_content = "是因為你就只有這兩種情緒吧？",
  ui_story_5075_50751401_70_dialog_content = "滿口「同族」，卻又對祟靈沒有半點憐憫之心。",
  ui_story_5075_50751401_71_dialog_content = "自稱「高貴」，卻只有貪生怕死這最卑劣的私慾。",
  ui_story_5075_50751401_72_dialog_content = "你甚至沒有自己的人格，只能藏在依附的面具下苟活。",
  ui_story_5075_50751401_73_dialog_content = "這樣的你，憑什麼認為自己是高等生命呢？",
  ui_story_5075_50751401_74_dialog_content = "沒有人格又如何？吾乃真正的不死之靈！",
  ui_story_5075_50751401_75_dialog_content = "便是你們這些所謂的「神靈」，壽命都不如吾悠長！吾……",
  ui_story_5075_50751401_76_dialog_content = "就是現在，趁牠情緒激動！",
  ui_story_5075_50751401_77_option_content = "強制感應！",
  ui_story_5075_50751401_78_dialog_content = "我、的、身、體。",
  ui_story_5075_50751401_79_dialog_content = "滾、出、去！",
  ui_story_5075_50751401_80_dialog_content = "唔——！",
  ui_story_5075_50751401_81_dialog_content = "什麼！",
  ui_story_5075_50751401_82_dialog_content = "多謝阿霓，幸虧妳轉移牠的注意力，我們找到牠了！",
  ui_story_5075_50751401_83_dialog_content = "接下來只要幫尤把牠的力量從體內趕出來……",
  ui_story_5075_50751401_84_dialog_content = "想得美！",
  ui_story_5075_50751402_1_dialog_content = "桀桀桀……不過是一具無用的軀體，還給你們又怎樣？",
  ui_story_5075_50751402_2_dialog_content = "這裡可是我的原軀所葬之處。",
  ui_story_5075_50751402_3_dialog_content = "就算無所依附，你們又能奈我何！",
  ui_story_5075_50751402_4_dialog_content = "<color=#e8d9bb>遠處的海水又一次翻騰起來。</color>",
  ui_story_5075_50751402_5_dialog_content = "（但我不打算再看一次水淹皓津了。）",
  ui_story_5075_50751402_6_dialog_content = "阿霓，妳之前說，我可以用這條金飾向妳許一個願望，對吧？",
  ui_story_5075_50751402_7_dialog_content = "喔？",
  ui_story_5075_50751402_8_dialog_content = "這位善主，有何心願？",
  ui_story_5075_50751402_9_dialog_content = "那傢伙不是光靈，也不是祟靈，甚至稱不上暗鬼。",
  ui_story_5075_50751402_10_dialog_content = "只是一團僅有惡意，毫無存在價值的殘念。",
  ui_story_5075_50751402_11_dialog_content = "那麼，我想請善女龍王大人清除這一惡念，還此間太平。",
  ui_story_5075_50751402_12_dialog_content = "允。",
  ui_story_5075_50751402_13_dialog_content = "桀桀桀——八百年了，你的善女龍王連我水淹皓津時都不肯出手。",
  ui_story_5075_50751402_14_dialog_content = "一定是缺少供奉，力量衰落——",
  ui_story_5075_50751402_15_dialog_content = "<color=#e8d9bb>僅一刹那，金蓮生輝。</color>",
  ui_story_5075_50751402_16_dialog_content = "<color=#e8d9bb>琉璃般明淨的虛影升起於海天之間。</color>",
  ui_story_5075_50751402_17_dialog_content = "<color=#e8d9bb>有浩蕩金光如漣漪擴散，所到之處，妖魔寂滅。</color>",
  ui_story_5075_50751402_18_dialog_content = "<color=#e8d9bb>皓津城內</color>",
  ui_story_5075_50751402_19_dialog_content = "咕——",
  ui_story_5075_50751402_20_dialog_content = "城裡的妖魔……全都消失了？",
  ui_story_5075_50751402_21_dialog_content = "快看！快看天邊！",
  ui_story_5075_50751402_22_dialog_content = "是龍女娘娘！龍女娘娘顯靈，幫我們降妖斬邪了！",
  ui_story_5075_50751402_23_dialog_content = "<color=#e8d9bb>頂著黑蛟之形的暗鬼殘念，毫不猶豫地掉頭就逃。</color>",
  ui_story_5075_50751402_24_dialog_content = "<color=#e8d9bb>而那琉璃般的虛影卻只一彈指，便將牠定住。</color>",
  ui_story_5075_50751402_25_dialog_content = "既覺吾力已衰，汝何懼哉？",
  ui_story_5075_50751402_26_dialog_content = "桀……桀桀桀！",
  ui_story_5075_50751402_27_dialog_content = "沒想到過了這麼久，妳還留有這種程度的力量。",
  ui_story_5075_50751402_28_dialog_content = "但你們還沒有贏！",
  ui_story_5075_50751402_29_dialog_content = "只要暗鬼大祖的力量仍存，我就近乎永生不滅！",
  ui_story_5075_50751402_30_dialog_content = "就算妳毀了這道殘念，我的力量也會再度聚集，使我重生。",
  ui_story_5075_50751402_31_dialog_content = "妳能消滅我一次兩次，難道還能消滅我千次萬次？",
  ui_story_5075_50751402_32_dialog_content = "我——",
  ui_story_5075_50751402_33_dialog_content = "<color=#e8d9bb>牠沒能說完最後一句話。</color>",
  ui_story_5075_50751402_34_dialog_content = "無心無相之物，亦無需存於天地。",
  ui_story_5075_50751402_35_dialog_content = "<color=#e8d9bb>琉璃影捏碎了牠。</color>",
  ui_story_5075_50751402_36_dialog_content = "<color=#e8d9bb>下一刻，海面上再次湧起黑霧。</color>",
  ui_story_5075_50751402_37_dialog_content = "<color=#e8d9bb>怨念與暗能在黑霧中央融成渾濁的核心，飛速再生。</color>",
  ui_story_5075_50751402_38_dialog_content = "雖然不想承認，但牠說得對，我們不可能永遠守在這裡。",
  ui_story_5075_50751402_39_dialog_content = "如果沒有長久的辦法，下次、再下次，我們還能不能保證沒人受傷呢……",
  ui_story_5075_50751402_40_dialog_content = "小PlayerName你怎麼光長他人志氣呀。",
  ui_story_5075_50751402_41_dialog_content = "可是……",
  ui_story_5075_50751402_42_dialog_content = "千百年來，人皆言海中行船靠吾護佑。",
  ui_story_5075_50751402_43_dialog_content = "可距吾上次醒來，已逾百年，無人護持，海上仍行船不斷。",
  ui_story_5075_50751402_44_dialog_content = "就算沒有神靈的保佑，他們也能自己守護自己。",
  ui_story_5075_50751402_45_dialog_content = "這話我愛聽！",
  ui_story_5075_50751402_46_dialog_content = "這個聲音是……",
  ui_story_5075_50751402_47_dialog_content = "璇極！",
  ui_story_5075_50751402_48_dialog_content = "PlayerName閣下，好久不見呀。",
  ui_story_5075_50751402_49_dialog_content = "我緊趕慢趕，總算是趕在最後關頭出場了。",
  ui_story_5075_50751402_50_dialog_content = "給你們看看鄴國最新出產的好東西～",
  ui_story_5075_50751402_51_dialog_content = "確認能源穩定，全組校準目標，最大火力——",
  ui_story_5075_50751402_52_dialog_content = "<size=45>發射！</size>",
  ui_story_5075_50751402_53_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5075_50751402_54_dialog_content = "<color=#e8d9bb>灼目的金光切開海面，人造的雷霆將黑氣從正中貫穿。</color>",
  ui_story_5075_50751402_55_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5075_50751402_56_dialog_content = "<color=#e8d9bb>再度試圖凝結的黑氣還未將上次的缺口補完，便被再度擊碎。</color>",
  ui_story_5075_50751402_57_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5075_50751402_58_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5075_50751402_59_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5075_50751402_60_dialog_content = "<color=#e8d9bb>一番豪邁的狂轟濫炸後，海面終於徹底恢復了平靜。</color>",
  ui_story_5075_50751402_61_dialog_content = "沒再復活？",
  ui_story_5075_50751402_62_dialog_content = "嗯～趁牠還沒反應過來，這下消散得夠乾淨囉。",
  ui_story_5075_50751402_63_dialog_content = "這砲也是阿霓睡覺的時候開發的新玩意嗎？",
  ui_story_5075_50751402_64_dialog_content = "別、別把頭伸進砲筒呀！",
  ui_story_5075_50751402_65_dialog_content = "放心吧，我把能源關掉了。",
  ui_story_5075_50751402_66_dialog_content = "璇極！妳不是有事回鄴國了嗎？",
  ui_story_5075_50751402_67_dialog_content = "是啊，事情還沒辦完，但誰叫我中途收到我們丹棠郡主的召喚呢。",
  ui_story_5075_50751402_68_dialog_content = "我看濟國這邊的狀況比較緊急，連忙調了最高規格的<color=#FFB400>機巧砲</color>過來支援。",
  ui_story_5075_50751402_69_dialog_content = "結果郡主自己都不來迎接我……",
  ui_story_5075_50751402_70_dialog_content = "不過能見到PlayerName閣下，我也很滿足啦。",
  ui_story_5075_50751402_71_dialog_content = "丹棠就在城裡。",
  ui_story_5075_50751402_72_dialog_content = "正好現在事情都解決了，璇極也跟我們一起回去，在皓津過春朔節吧。",
  ui_story_5075_50751402_73_dialog_content = "啊，我記得皓津的新年驅獸儀式非常熱鬧，很有意思。",
  ui_story_5075_50751402_74_dialog_content = "可惜，我還得趕回鄴國處理沒辦完的事。",
  ui_story_5075_50751402_75_dialog_content = "你快回去吧，別耽誤過年了，我們下次再聚。",
  ui_story_5075_50751402_76_dialog_content = "記得幫我跟丹棠郡主問個好啊。",
  ui_story_5075_50751402_77_dialog_content = "好吧，不能耽誤妳的正事。",
  ui_story_5075_50751402_78_dialog_content = "有事機關鳥聯絡～",
  ui_story_5075_50751402_79_dialog_content = "唉，總覺得有點虧啊。",
  ui_story_5075_50751402_80_dialog_content = "從鄴國大老遠帶著機巧砲趕過來，才上場這麼一小會就又要退場了。",
  ui_story_5075_50751402_81_dialog_content = "不過登場的時候沒人迎接，退場的陣仗倒是不小啊。",
  ui_story_5075_50751402_82_dialog_content = "璇極大人。",
  ui_story_5075_50751402_83_dialog_content = "您未經允許私自盜用高規格機密武器。",
  ui_story_5075_50751402_84_dialog_content = "甚至將武器偷運他國，有叛國嫌疑。",
  ui_story_5075_50751402_X84_dialog_content = "呵，你們這夥人算不算鄴國還難說……",
  ui_story_5075_50751402_85_dialog_content = "是大王命令你們來的嗎？",
  ui_story_5075_50751402_86_dialog_content = "是，吾等奉<color=#FFB400>鄴王</color>密令，欲將您逮捕歸案。您打算抗命嗎？",
  ui_story_5075_50751402_87_dialog_content = "……不打算。",
  ui_story_5075_50751402_88_dialog_content = "我是鄴國人，更曾是鄴國的謀臣和要人。",
  ui_story_5075_50751402_89_dialog_content = "我對有損鄴國之利者拒命不從，但並不違抗國君之令。",
  ui_story_5075_50751402_90_dialog_content = "我認罪。",
  ui_story_5075_50751402_91_dialog_content = "……",
  ui_story_5075_50751402_92_dialog_content = "哎呀，別都板著個臉啊。",
  ui_story_5075_50751402_93_dialog_content = "這還是我第一次要在牢裡過年呢，有什麼不周到的，還得麻煩幾位多包涵啦。",
  ui_story_5075_50751501_1_dialog_content = "<color=#e8d9bb>砰！砰！</color>",
  ui_story_5075_50751501_2_dialog_content = "哇，有煙火！",
  ui_story_5075_50751501_3_dialog_content = "才一個晚上不見，城裡竟然就變得這麼熱鬧。",
  ui_story_5075_50751501_4_dialog_content = "妖魔已除，與祟靈的誤會也解開了。",
  ui_story_5075_50751501_5_dialog_content = "明日春朔，大家自然能放下心來好好慶祝。",
  ui_story_5075_50751501_6_dialog_content = "尤也回到海裡去了吧。",
  ui_story_5075_50751501_7_dialog_content = "嗯，牠說要自己好好思考一下，將來要做什麼，又能做什麼。",
  ui_story_5075_50751501_8_dialog_content = "牠真的會來找林家復仇嗎？",
  ui_story_5075_50751501_9_dialog_content = "不知道。",
  ui_story_5075_50751501_10_dialog_content = "但至少我們了結了前塵往事，至於將來……",
  ui_story_5075_50751501_11_dialog_content = "就等明日過了再說吧。",
  ui_story_5075_50751501_12_dialog_content = "畢竟，「大過年的」，對吧？",
  ui_story_5075_50751501_13_dialog_content = "李天閑沒騙我，這句遠古咒語真的超有效耶！",
  ui_story_5075_50751501_14_dialog_content = "？",
  ui_story_5075_50751501_15_dialog_content = "……呵呵。",
  ui_story_5075_50751501_16_dialog_content = "竟、竟然連月白都笑了，我剛剛鬧了什麼大笑話嗎？！",
  ui_story_5075_50751501_17_dialog_content = "沒有。",
  ui_story_5075_50751501_18_dialog_content = "這確實是很強力的咒語。",
  ui_story_5075_50751501_19_dialog_content = "我還要回林家為昨晚的事收尾，先告辭了。",
  ui_story_5075_50751501_20_dialog_content = "嗯，下次再見。",
  ui_story_5075_50751501_21_dialog_content = "<color=#e8d9bb>劈哩啪啦！</color>",
  ui_story_5075_50751501_22_dialog_content = "怎麼回事？",
  ui_story_5075_50751501_23_dialog_content = "是表演驅獸儀式的隊伍過來了～",
  ui_story_5075_50751501_24_dialog_content = "阿霓，妳剛才跑哪去了……",
  ui_story_5075_50751501_25_dialog_content = "妳什麼時候弄來了那麼多點心？！",
  ui_story_5075_50751501_26_dialog_content = "阿霓剛剛把龍角露出來去街上逛了一圈，攤主們就很熱情地把東西供上啦～",
  ui_story_5075_50751501_27_dialog_content = "對喔，小PlayerName沒有角也沒有尾巴。",
  ui_story_5075_50751501_28_dialog_content = "別傷心，來，阿霓把這些分你一半。",
  ui_story_5075_50751501_29_dialog_content = "謝謝，但我並不傷心啦。",
  ui_story_5075_50751501_30_dialog_content = "快看，小羅松也在驅獸隊伍裡。",
  ui_story_5075_50751501_31_dialog_content = "真的耶，而且這支隊伍裡好多祟靈。",
  ui_story_5075_50751501_32_dialog_content = "放鞭炮，驅妖邪，趕得霉運嗷嗷叫！",
  ui_story_5075_50751501_33_dialog_content = "納祥瑞，迎新春，幸福團圓笑開顏！",
  ui_story_5075_50751501_34_dialog_content = "等等，不是驅獸嗎？怎麼祟靈也加入追逐別人的一方了。",
  ui_story_5075_50751501_35_dialog_content = "這是今年改版的，驅逐的不是祟靈，而是妖魔。",
  ui_story_5075_50751501_36_dialog_content = "你沒看見昨晚龍女娘娘顯靈嗎？妖魔都被娘娘除盡了，祟靈卻半點事都沒有。",
  ui_story_5075_50751501_37_dialog_content = "這表示娘娘都覺得祟靈不會害人嘛。",
  ui_story_5075_50751501_38_dialog_content = "聽好了！面對強大的敵人，你們一定要學會通力合作。",
  ui_story_5075_50751501_39_dialog_content = "好好利用自己的特性，彼此配合，才能力半功倍！",
  ui_story_5075_50751501_40_dialog_content = "阿丁，跟大家示範一下你和新朋友的合體技！",
  ui_story_5075_50751501_41_dialog_content = "哈！",
  ui_story_5075_50751501_42_dialog_content = "嗷！",
  ui_story_5075_50751501_43_dialog_content = "是我眼花了嗎？",
  ui_story_5075_50751501_44_dialog_content = "隊伍裡好像有一隻很眼熟的貓。",
  ui_story_5075_50751501_45_dialog_content = "<color=#e8d9bb>劈哩啪啦！</color>",
  ui_story_5075_50751501_46_dialog_content = "放鞭炮，驅妖邪……哎喲。",
  ui_story_5075_50751501_47_dialog_content = "對不起，我沒好好看路，撞到你了……啊。",
  ui_story_5075_50751501_48_dialog_content = "嗯？",
  ui_story_5075_50751501_49_dialog_content = "喔，原來是之前那個欺負小祟靈的孩子呀。",
  ui_story_5075_50751501_50_dialog_content = "那、那個……姐姐妳也是祟靈吧？",
  ui_story_5075_50751501_51_dialog_content = "這個糖送給妳！",
  ui_story_5075_50751501_52_dialog_content = "然後……要是妳認識曾經被我們欺負過的祟靈，請幫我跟牠說聲對不起！",
  ui_story_5075_50751501_53_dialog_content = "跑開了……",
  ui_story_5075_50751501_54_dialog_content = "看來人們確實對祟靈改觀了。",
  ui_story_5075_50751501_55_dialog_content = "嗯……啊呣。",
  ui_story_5075_50751501_56_dialog_content = "很甜。",
  ui_story_5075_50751501_57_dialog_content = "我還以為阿霓妳見到這樣的場景會很高興呢。",
  ui_story_5075_50751501_58_dialog_content = "阿霓高興啊。",
  ui_story_5075_50751501_59_dialog_content = "但總覺得……",
  ui_story_5075_50751501_60_dialog_content = "和妳昨天的高興，甚至前天的高興並沒什麼差別。",
  ui_story_5075_50751501_61_dialog_content = "畢竟，世界就是這樣的嘛。",
  ui_story_5075_50751501_62_dialog_content = "昨天人會因為害怕對祟靈壞，今天因為愧疚對祟靈好。",
  ui_story_5075_50751501_63_dialog_content = "明天又可能因為什麼原因對祟靈壞。",
  ui_story_5075_50751501_64_dialog_content = "昨天的點心好吃，今天的難吃，明天卻又可能變得好吃。",
  ui_story_5075_50751501_65_dialog_content = "一直有好，也一直有壞；一直不好，但也一直不壞。",
  ui_story_5075_50751501_66_dialog_content = "不過阿霓覺得，這樣就好。",
  ui_story_5075_50751501_67_dialog_content = "我……還是不太能理解阿霓的心情。",
  ui_story_5075_50751501_68_dialog_content = "但經歷了這麼多，現在我好像明白了一點。",
  ui_story_5075_50751501_69_dialog_content = "在阿霓眼裡，不只人和祟靈，這片大陸上的所有生靈其實都是一樣的吧。",
  ui_story_5075_50751501_70_dialog_content = "所有生命都有自己存在的意義。",
  ui_story_5075_50751501_71_dialog_content = "正因為阿霓尊重這份意義，所以反而不會輕易干涉其中。",
  ui_story_5075_50751501_72_dialog_content = "看起來什麼都不在意，是因為你對一切都平等地在意。",
  ui_story_5075_50751501_73_dialog_content = "這麼說的話，我們這幾天的經歷，在阿霓看來也只是一件小事吧。",
  ui_story_5075_50751501_74_dialog_content = "稍微有點不甘心。",
  ui_story_5075_50751501_75_dialog_content = "阿霓之後打算做什麼？",
  ui_story_5075_50751501_76_dialog_content = "阿霓是因為被吵醒才出來的。",
  ui_story_5075_50751501_77_dialog_content = "過一會就回去繼續睡覺吧。",
  ui_story_5075_50751501_78_dialog_content = "這麼快？",
  ui_story_5075_50751501_79_dialog_content = "使者大人，大王有旨，請您進宮。",
  ui_story_5075_50751501_80_dialog_content = "啊，好。",
  ui_story_5075_50751501_81_dialog_content = "阿霓，要不要和我……咦？",
  ui_story_5075_50751501_82_dialog_content = "已經走了嗎？",
  ui_story_5075_50751501_83_dialog_content = "PlayerName公子，辛苦你了。",
  ui_story_5075_50751501_84_dialog_content = "這次——",
  ui_story_5075_50751501_85_dialog_content = "PlayerName！PlayerName！",
  ui_story_5075_50751501_86_dialog_content = "事情我都聽丹棠交代了，她說你臨危受命，智勇雙全。",
  ui_story_5075_50751501_87_dialog_content = "不只抓出濟國朝中的奸人，就連昨天洪水退去也是你的功勞！",
  ui_story_5075_50751501_88_dialog_content = "世子，我的用詞應該沒有如此誇張。",
  ui_story_5075_50751501_89_dialog_content = "反正我知道PlayerName是個大英雄了！",
  ui_story_5075_50751501_90_dialog_content = "大英雄太棒了！<size=45>我要跟PlayerName結婚！</size>",
  ui_story_5075_50751501_91_dialog_content = "<size=45>……啊？？</size>",
  ui_story_5075_50751501_92_dialog_content = "世人道，夫妻一體，有了你這樣厲害的未婚妻，我將來一定也能當上英雄！",
  ui_story_5075_50751501_93_dialog_content = "<size=45>咳！</size>",
  ui_story_5075_50751501_94_dialog_content = "來人，快把世子帶回去！",
  ui_story_5075_50751501_95_dialog_content = "叫夫子好好教教他什麼叫夫妻，省得天天胡說，害我差點當真……",
  ui_story_5075_50751501_96_dialog_content = "但他別的話倒是沒錯。",
  ui_story_5075_50751501_97_dialog_content = "皓津遭此危機是本王誤算，多虧你們力挽狂瀾。",
  ui_story_5075_50751501_98_dialog_content = "你有什麼想要的大可開口，本王定然允你。",
  ui_story_5075_50751501_99_dialog_content = "那麼，請殿下聽聽我和丹棠，關於兩塊大陸之間的交流計畫吧！",
  ui_story_5075_50751501_100_dialog_content = "就只有這個？你難道不想要金銀財寶、權勢地位？",
  ui_story_5075_50751501_101_dialog_content = "坦白說，並不是不想。但我是以艾斯特拉大陸使節的身分來到龍洲的。",
  ui_story_5075_50751501_102_dialog_content = "完成使命才是第一要務。",
  ui_story_5075_50751501_103_dialog_content = "哈哈哈，你這樣的青年俊傑，本王倒是有些捨不得放你回去了。",
  ui_story_5075_50751501_104_dialog_content = "但你又不願留在龍洲，這樣吧。",
  ui_story_5075_50751501_105_dialog_content = "本王封你為濟國的榮譽國民。",
  ui_story_5075_50751501_106_dialog_content = "無論你之後去向何方，經歷何事，濟國的土地永遠歡迎你。",
  ui_story_5075_50751501_107_dialog_content = "多謝殿下！",
  ui_story_5075_50751501_108_dialog_content = "呼……在宮裡待了這麼久，時候也不早了啊。",
  ui_story_5075_50751501_109_dialog_content = "主事官被抓之後，禮賓館的侍女跟護衛也終於撤掉了。",
  ui_story_5075_50751501_110_dialog_content = "我好像還是第一次一個人待在這裡。",
  ui_story_5075_50751501_111_dialog_content = "……好安靜。",
  ui_story_5075_50751501_112_dialog_content = "而且乍一閒下來，都不知道要做什麼才好了。",
  ui_story_5075_50751501_113_dialog_content = "對了，明天就是春朔節了。",
  ui_story_5075_50751501_114_dialog_content = "聽說今晚龍洲的百姓會整夜不睡，聚集在一起吃飯聊天。",
  ui_story_5075_50751501_115_dialog_content = "意為辭別舊歲，守望新年。",
  ui_story_5075_50751501_116_dialog_content = "我要不要也試試看呢……算了，一個人就算守夜也沒什麼意思吧。",
  ui_story_5075_50751501_117_dialog_content = "大家都在做什麼呢……",
  ui_story_5075_50751501_118_dialog_content = "在等小PlayerName發現阿霓。",
  ui_story_5075_50751501_119_dialog_content = "咦？！妳什麼時候進來的？",
  ui_story_5075_50751501_120_dialog_content = "在你回來之前就進來了啊。",
  ui_story_5075_50751501_121_dialog_content = "結果小PlayerName晃來晃去老半天，看也不看，阿霓只好自己出來啦。",
  ui_story_5075_50751501_122_dialog_content = "妳看見了啊……",
  ui_story_5075_50751501_123_dialog_content = "我還以為阿霓妳已經走了。",
  ui_story_5075_50751501_124_dialog_content = "畢竟妳之前說馬上要回海裡去。",
  ui_story_5075_50751501_125_dialog_content = "對呀，阿霓不打算久待。",
  ui_story_5075_50751501_126_dialog_content = "過個幾十年就回去吧。",
  ui_story_5075_50751501_127_dialog_content = "等等，你說的「一會兒」是幾十年的意思？！",
  ui_story_5075_50751501_128_dialog_content = "太短了？",
  ui_story_5075_50751501_129_dialog_content = "阿霓喜歡和小PlayerName一起玩。",
  ui_story_5075_50751501_130_dialog_content = "所以小PlayerName希望的話，待個一兩百年也不是完全不行啦。",
  ui_story_5075_50751501_131_dialog_content = "……對不起，是我忘了大祟靈的時間觀念和普通人不同。",
  ui_story_5075_50751501_132_dialog_content = "不過小PlayerName你這裡怎麼什麼都沒有啊？",
  ui_story_5075_50751501_133_dialog_content = "現在可是吃年夜飯的時間。",
  ui_story_5075_50751501_134_dialog_content = "哈哈，是我疏忽了。",
  ui_story_5075_50751501_135_dialog_content = "沒辦法，這是阿霓剛收到的供奉千張卷，送給你吧。",
  ui_story_5075_50751501_136_dialog_content = "謝謝……呃，千張卷？",
  ui_story_5075_50751501_137_dialog_content = "PlayerName——阿霓——",
  ui_story_5075_50751501_138_dialog_content = "你們在哪裡——",
  ui_story_5075_50751501_139_dialog_content = "好像是羅松的聲音？",
  ui_story_5075_50751501_140_dialog_content = "羅松！我們在這邊！",
  ui_story_5075_50751501_141_dialog_content = "PlayerName！阿霓！總算找到你們了。",
  ui_story_5075_50751501_142_dialog_content = "也怪我粗心，之前分開的時候忘了問你們住哪。",
  ui_story_5075_50751501_143_dialog_content = "你不會就這樣在大街上喊我們的名字找人吧。",
  ui_story_5075_50751501_144_dialog_content = "哈哈，這個辦法聽起來笨，但這不就找到了嗎？",
  ui_story_5075_50751501_145_dialog_content = "難得同行一場，你們應該不介意我一起過年吧。",
  ui_story_5075_50751501_146_dialog_content = "當然不介意！",
  ui_story_5075_50751501_147_dialog_content = "那太好了。",
  ui_story_5075_50751501_148_dialog_content = "話說剛剛我幫一位阿婆搬東西，她送了我一袋芹菜。",
  ui_story_5075_50751501_149_dialog_content = "正好可以為年夜飯添一道菜。",
  ui_story_5075_50751501_150_dialog_content = "哎喲喂，您這兒怎麼比我那算命攤子還冷清啊。",
  ui_story_5075_50751501_151_dialog_content = "李天閑，你怎麼來了？",
  ui_story_5075_50751501_152_dialog_content = "這不是想來蹭……怕您在異國他鄉過節不習慣嗎。",
  ui_story_5075_50751501_153_dialog_content = "結果您還真是連年夜飯都沒準備，在下真是來對了。",
  ui_story_5075_50751501_154_dialog_content = "來，這是在下的賀歲禮。",
  ui_story_5075_50751501_155_dialog_content = "你的好意我很感謝，但為什麼要給我野菜？",
  ui_story_5075_50751501_156_dialog_content = "這可不是一般的野菜。這名叫薺菜，在冬天可不好找。",
  ui_story_5075_50751501_157_dialog_content = "在下這幾天賣糖人的收入都搭進去了，才買到這一筐暖房裡產的。",
  ui_story_5075_50751501_158_dialog_content = "諧音「聚財」，大吉大利！過年吃一口，明年一定賺得盆滿缽滿！",
  ui_story_5075_50751501_159_dialog_content = "喲，您還有千張？這也吉利，寓意千秋百代，代代興旺。",
  ui_story_5075_50751501_160_dialog_content = "芹菜也好啊，勤勞致富，是個好彩頭。",
  ui_story_5075_50751501_161_dialog_content = "PlayerName，過來幫個忙——",
  ui_story_5075_50751501_162_dialog_content = "商會的人剛送來一車鮮藕，我想你這大概沒什麼食材，就直接拉過來了。",
  ui_story_5075_50751501_163_dialog_content = "一車？！",
  ui_story_5075_50751501_164_dialog_content = "您就收下吧，這可是好藕。",
  ui_story_5075_50751501_165_dialog_content = "掰開全是眼，是祝您順順利利，路路暢通啊。",
  ui_story_5075_50751501_166_dialog_content = "怎麼不管什麼東西，在你那裡都這麼吉利？",
  ui_story_5075_50751501_167_dialog_content = "大過年的嘛，當然萬事大吉。",
  ui_story_5075_50751501_168_dialog_content = "老遠就聽見李天閑又在這裡唬人。",
  ui_story_5075_50751501_169_dialog_content = "但這過年的吉祥話說得還不錯。",
  ui_story_5075_50751501_170_dialog_content = "PlayerName閣下，好久不見。",
  ui_story_5075_50751501_171_dialog_content = "丹棠、阿玖，妳們不用在宮裡過年嗎？",
  ui_story_5075_50751501_172_dialog_content = "本來是應該的。",
  ui_story_5075_50751501_173_dialog_content = "但因PlayerName公子這幾日大顯身手，濟王殿下特別給了我一個任務。",
  ui_story_5075_50751501_174_dialog_content = "要我招待你好好過個年。",
  ui_story_5075_50751501_175_dialog_content = "宮裡還送了好些食材在外面，等會我親自下廚，替你們做些應景的年節菜。",
  ui_story_5075_50751501_176_dialog_content = "對了，你們都在藉食材送祝福，那我也借花獻禮。",
  ui_story_5075_50751501_177_dialog_content = "將這盤金燦燦的金簪菜送給PlayerName公子。",
  ui_story_5075_50751501_178_dialog_content = "願你前程似錦。",
  ui_story_5075_50751501_179_dialog_content = "那我就送這碟豌豆葉吧！有春滿枝頭之意，也是吉祥。",
  ui_story_5075_50751501_180_dialog_content = "哇，這裡怎麼這麼多人？",
  ui_story_5075_50751501_181_dialog_content = "虧我還擔心PlayerName要一個人過年了呢。",
  ui_story_5075_50751501_182_dialog_content = "小友交遊廣泛，是好事。",
  ui_story_5075_50751501_183_dialog_content = "仲胥！厘青！你們也來啦。",
  ui_story_5075_50751501_184_dialog_content = "這桌上怎麼這麼多食材？啊，我知道了！",
  ui_story_5075_50751501_185_dialog_content = "你們一定是要做「十景菜」吧？",
  ui_story_5075_50751501_186_dialog_content = "什麼是十景菜？",
  ui_story_5075_50751501_187_dialog_content = "這是濟國的傳統名菜，將十幾種蔬菜細切成絲，以油炒之，謂之「十景」。",
  ui_story_5075_50751501_188_dialog_content = "如此，便算將菜中吉祥之意合為一體。",
  ui_story_5075_50751501_189_dialog_content = "是濟國春朔節少不了的一道菜。",
  ui_story_5075_50751501_190_dialog_content = "不過這桌上的菜品尚有些少。",
  ui_story_5075_50751501_191_dialog_content = "我便添一道雪裡蕻吧，願各位事事興旺昌盛。",
  ui_story_5075_50751501_192_dialog_content = "那我就加馬齒莧好了。",
  ui_story_5075_50751501_193_dialog_content = "這不光是菜，還是一味清熱解毒的藥材呢。",
  ui_story_5075_50751501_194_dialog_content = "你們這食材加得千奇百怪，可是要考驗我的手藝了。",
  ui_story_5075_50751501_195_dialog_content = "這點小事，還難不倒殿下。",
  ui_story_5075_50751501_196_dialog_content = "阿玖怎麼也來吹捧我了呀，那就一起去廚房吧。",
  ui_story_5075_50751501_197_dialog_content = "我也來幫忙。",
  ui_story_5075_50751501_198_dialog_content = "試菜就交給在下——",
  ui_story_5075_50751501_199_dialog_content = "阿霓可以負責試菜！",
  ui_story_5075_50751501_200_dialog_content = "得，在下搶不過您，小祖宗您請。",
  ui_story_5075_50751501_201_dialog_content = "我去把外面的食材整一整，要用的都搬進來。",
  ui_story_5075_50751501_202_dialog_content = "我還帶了些裝飾材料，可以用來佈置房間。",
  ui_story_5075_50751501_203_dialog_content = "太好了，我早就想這裡少了些節日氣氛，這怎麼行呢？",
  ui_story_5075_50751501_204_dialog_content = "大家一起貢獻出的十景菜來了。",
  ui_story_5075_50751501_205_dialog_content = "還有一會兒，龍女廟的鐘聲就要響了，在新的一年正式到來前……",
  ui_story_5075_50751501_206_dialog_content = "PlayerName公子，過去的一年，受你照拂，萬分感謝。",
  ui_story_5075_50751501_207_dialog_content = "玖不善言辭，只能道聲多謝。",
  ui_story_5075_50751501_208_dialog_content = "過去一年，多謝您照顧在下生意，明年也請多關照嘞。",
  ui_story_5075_50751501_209_dialog_content = "之前的旅途，多謝小友相助。望小友新年，一片坦途。",
  ui_story_5075_50751501_210_dialog_content = "各種事情都多謝了，新年也要身體健康，少來找我開藥啊。",
  ui_story_5075_50751501_211_dialog_content = "雖然認識不久，但你這個朋友我已經認定了。",
  ui_story_5075_50751501_212_dialog_content = "新的一年，我祝你身強體壯，什麼妖魔邪祟，見一個揍一個！",
  ui_story_5075_50751501_213_dialog_content = "祝你新年快樂，乾杯！",
  ui_story_5075_50751501_214_dialog_content = "咕——",
  ui_story_5075_50751501_215_dialog_content = "哎哎時間還沒到呢！別偷跑啊，怎麼還真喝了……",
  ui_story_5075_50751501_216_dialog_content = "小PlayerName，小PlayerName。",
  ui_story_5075_50751501_217_dialog_content = "怎麼了，阿霓？",
  ui_story_5075_50751501_218_dialog_content = "低頭。",
  ui_story_5075_50751501_219_dialog_content = "好，不過是要做什麼？",
  ui_story_5075_50751501_220_dialog_content = "摸摸頭，摸摸頭。",
  ui_story_5075_50751501_221_dialog_content = "讓小PlayerName日日歡喜，萬事順遂。",
  ui_story_5075_50751501_222_dialog_content = "這可是菩薩親言，一定靈驗～",
  ui_story_5075_50751501_223_dialog_content = "<color=#e8d9bb>噹——噹——</color>",
  ui_story_5075_50751501_224_dialog_content = "<color=#e8d9bb>龍女廟的鐘聲從南山響起，傳遍全城。</color>",
  ui_story_5075_50751501_225_dialog_content = "<color=#e8d9bb>一百零八聲，洗淨煩惱，吉祥安康。</color>",
  ui_story_5075_50751501_226_dialog_content = "這就代表春朔節……新的一年正式到來了吧。",
  ui_story_5075_50751501_227_dialog_content = "PlayerName公子。",
  ui_story_5075_50751501_228_dialog_content = "PlayerName閣下。",
  ui_story_5075_50751501_229_dialog_content = "PlayerName。",
  ui_story_5075_50751501_230_dialog_content = "PlayerName。",
  ui_story_5075_50751501_231_dialog_content = "小友。",
  ui_story_5075_50751501_232_dialog_content = "PlayerName。",
  ui_story_5075_50751501_233_dialog_content = "PlayerName。",
  ui_story_5075_50751501_234_dialog_content = "小PlayerName。",
  ui_story_5075_50751501_235_dialog_content = "<size=45>新年快樂！</size>"
}
return config
